class UplinkWatch:
    """Every 10 s: internet there? Connection drops? -> after 3 min without internet try another known network (only with two
    adapters - with one adapter the network automatic does it). Push message when the internet is back (with how long it was gone)."""
    def __init__(self):
        self.was_conn = None; self.n = 0; self.warned_unstable = 0.0
        threading.Thread(target=self.loop, daemon=True, name="uplink").start()

    def step(self):
        now = time.time(); self.n += 1
        if self.n % 6 == 1:
            try:
                dual_roles()
            except Exception as e:
                DUAL["msg"] = str(e)[:100]
        try:
            dual_safety()
        except Exception as e:
            DUAL["msg"] = str(e)[:100]
        try:
            tether_tick()
        except Exception as e:
            STATE["tether"] = {"on": False, "err": str(e)[:80]}
        try:
            noinet_apply()                               # 2.95.33: was only called after an error (also after a restart now)
        except Exception as e:
            DUAL["msg"] = str(e)[:100]
        net = STATE.get("net") or {}; w = STATE.get("wifi") or {}
        online = net.get("online")
        if online is False and DUAL["offline_since"] is None:
            DUAL["offline_since"] = now
        elif online and DUAL["offline_since"] is not None:
            gone = now - DUAL["offline_since"]; DUAL["offline_since"] = None
            if gone > 120:
                dual_log(trf("Internet was gone for {min} min - it is back ({ssid})", min=int(gone / 60 + 0.5), ssid=w.get("ssid") or "?"), push=True)
        conn = bool(w.get("connected")) and not w.get("ap")
        if self.was_conn and not conn:
            DUAL["drops"] = [t_ for t_ in DUAL["drops"] if now - t_ < 600] + [now]
            good = [v for v in list(STATE.get("wifi_hist") or [])[-10:] if v is not None]
            if len(DUAL["drops"]) >= 3 and good and max(good) > -70:
                DUAL["unstable"] = True
                if now - self.warned_unstable > 3600:
                    self.warned_unstable = now
                    dual_log(tr("Wi-Fi connection dropped 3 times in 10 minutes although the signal is good - interference or jamming?"),
                             push=bool(CFG.get("wifi_guard")))
        elif DUAL["drops"] and now - DUAL["drops"][-1] > 1800:
            DUAL["unstable"] = False
        self.was_conn = conn
        if self.n % 6 == 0 and conn and w.get("dbm") is not None:
            DUAL["sig"] = (DUAL["sig"] + [[int(now), w["dbm"]]])[-240:]          # one value per minute, 4 hours
        if (DUAL["on"] and DUAL["offline_since"] and now - DUAL["offline_since"] > 180 and now - DUAL["switch_t"] > 300
                and not WIFI.get("busy")):
            DUAL["switch_t"] = now
            cur = w.get("ssid") if conn else ""
            cand = [s for s in _visible_saved(DUAL["up"]) if s["ssid"] != cur]
            if cand:
                c = cand[0]
                code, _o, err = _run(["nmcli", "--wait", "40", "connection", "up", "uuid", c["id"], "ifname", DUAL["up"]], 50)
                dual_log(trf("No internet over «{a}» - changed to «{b}»", a=cur or "?", b=c["ssid"]) if code == 0
                         else trf("No internet - «{b}» did not work either", b=c["ssid"]))
                WIFI["refresh"] = True

    def loop(self):
        time.sleep(15)
        while True:
            try:
                self.step()
            except Exception as e:
                DUAL["msg"] = ("error: " + str(e))[:120]
            time.sleep(10)


# ---- devices in the own Wi-Fi without internet (e.g. cheap Wi-Fi cameras that "call home") ----
def noinet_apply(force=False):
    macs = sorted(m for m in (CFG.get("net_noinet") or []) if re.fullmatch(r"[0-9a-f]{2}(:[0-9a-f]{2}){5}", m))
    key = ",".join(macs)
    if key == DUAL["iso"] and not force:
        return True
    nft, ipt = shutil.which("nft"), shutil.which("iptables")
    ok, err = False, ""
    if nft:
        _run([nft, "add", "table", "inet", "mw_iso"], 8); _run([nft, "delete", "table", "inet", "mw_iso"], 8)
        if macs:
            rules = ("table inet mw_iso {\n chain mwfwd {\n  type filter hook forward priority -10; policy accept;\n"
                     f"  ether saddr {{ {', '.join(macs)} }} drop\n }}\n}}\n")
            code, _o, e = _run([nft, "-f", "-"], 10, inp=rules)
            ok, err = code == 0, e
        else:
            ok = True
    elif ipt:
        _run([ipt, "-D", "FORWARD", "-j", "MW_ISO"], 8); _run([ipt, "-F", "MW_ISO"], 8); _run([ipt, "-X", "MW_ISO"], 8)
        ok = True
        if macs:
            code, _o, err = _run([ipt, "-N", "MW_ISO"], 8)
            for m in macs:
                c2, _o, e2 = _run([ipt, "-A", "MW_ISO", "-m", "mac", "--mac-source", m, "-j", "DROP"], 8)
                if c2:
                    err = e2
            c3, _o, e3 = _run([ipt, "-I", "FORWARD", "1", "-j", "MW_ISO"], 8)
            ok = code == 0 and c3 == 0 and not err
            err = err or e3
    else:
        err = "nft / iptables missing"
    if ok:
        DUAL["iso"] = key; DUAL["iso_msg"] = ""
        if macs or force:
            log_event("sys", f"Without internet: {len(macs)} device(s)")
    else:
        DUAL["iso_msg"] = _perm_hint((err or "error").strip())[:160]
    return ok


# ---- Wi-Fi guard: listens with the stick ("monitor mode") for deauthentication frames = the usual Wi-Fi jamming attack ----
_PRESENCE_SALT = {"day": "", "salt": b""}


def presence_eval():
    P = TOOLS["presence"]
    if not (CFG.get("presence_macs") or CFG.get("presence_bt")):
        return
    now = time.time()
    is_here = now - P.get("last", 0) < float(CFG.get("presence_gone_min", 10)) * 60
    if is_here != P["here"]:
        was = P["here"]; P.update(here=is_here, since=now)
        if was is not None:
            log_event("sys", "Presence: " + ("your device is back" if is_here else "your device is gone"))
            if CFG.get("mode") != "transport":                  # 2.97.0: not while travelling
                # 2.98.15: «Wenn mein Handy zurückkommt: ausschalten / fragen / nichts» (presence_back, 577); presence_auto = arm when gone
                if is_here and CFG["armed"] and presence_back_mode() == "off":
                    disarm(); log_event("sys", "Disarmed automatically (your device is here)")
                elif not is_here and CFG.get("presence_auto"):
                    if PRESENCE.get("home") is True:
                        log_event("sys", "Presence: your device is gone, but a device still answers the ping - not armed")
                    elif not CFG["armed"]:
                        arm(); log_event("sys", "Armed automatically (your device is gone)")


class WifiGuard:
    def __init__(self):
        self.sock = None; self.mon = ""
        threading.Thread(target=self.loop, daemon=True, name="wifiguard").start()

    def want(self):
        return bool(CFG.get("wifi_guard") or CFG.get("wifi_count") or (CFG.get("presence_macs") and CFG.get("wifi_presence")))

    def pick(self):
        ads = DUAL["adapters"] or wifi_adapters()
        cand = [a for a in ads if a["monitor"] and a["driver"] != "brcmfmac" and a["phy"]]
        cand.sort(key=lambda a: (a["iface"] != DUAL.get("up"), not a["usb"]))
        return cand[0] if cand else None

    def open(self):
        import socket
        a = self.pick()
        if a is None:
            WGUARD.update(state="no adapter", msg="no Wi-Fi adapter here can listen (monitor mode) - e.g. a stick with MediaTek MT7612U / MT7921AU")
            return False
        name = "mwmon0"
        if not os.path.exists(f"/sys/class/net/{name}"):
            code, _o, err = _run(["iw", "phy", a["phy"], "interface", "add", name, "type", "monitor"], 8)
            if code != 0:
                WGUARD.update(state="not possible", msg=_perm_hint(err.strip() or "monitor mode not possible")[:160]); return False
        _run(["ip", "link", "set", name, "up"], 8)
        if not a["up"] or (a["iface"] not in (DUAL.get("up"), DUAL.get("ap"), WIFI.get("iface"))):
            ch = None                                         # the stick is free: listen on the channel of the own Wi-Fi
            code, out, _e = _run(["iw", "dev", DUAL.get("ap") or WIFI.get("iface") or "wlan0", "info"], 5)
            m = re.search(r"channel (\d+)", out or "")
            if m:
                ch = m.group(1); _run(["iw", "dev", name, "set", "channel", ch], 5)
        try:
            s_ = socket.socket(socket.AF_PACKET, socket.SOCK_RAW, socket.htons(3))
            s_.bind((name, 0)); s_.settimeout(1.0)
        except (OSError, AttributeError) as e:
            WGUARD.update(state="not possible", msg=str(e)[:160]); return False
        self.sock, self.mon = s_, name
        WGUARD.update(state="listening", iface=a["iface"], phy=a["phy"], msg="")
        log_event("sys", f"Wi-Fi guard: listening with {a['iface']} ({a['chip']})")
        return True

    def close(self):
        if self.sock is not None:
            try:
                self.sock.close()
            except OSError:
                pass
        self.sock = None
        if self.mon:
            _run(["iw", "dev", self.mon, "del"], 8); self.mon = ""
        WGUARD["state"] = "off"

    def own_bssids(self):
        own = set()
        for i in (DUAL.get("ap"), DUAL.get("up"), WIFI.get("iface")):
            if i:
                m = _rd(f"/sys/class/net/{i}/address")
                if m:
                    own.add(m.lower())
                code, out, _e = _run(["iw", "dev", i, "link"], 4)
                mm = re.search(r"Connected to ([0-9a-f:]{17})", out or "")
                if mm:
                    own.add(mm.group(1).lower())
        return own

    def loop(self):
        while True:                                     # 2.95.33: an error must not end the jamming detection for good
            try:
                self._loop()
            except Exception as e:
                log_event("sys", f"Wi-Fi guard error (restarted): {type(e).__name__}: {e}"[:200])
                time.sleep(30)

    def _loop(self):
        time.sleep(20)
        minute_t = time.time(); dea = dall = 0; seen = {}; own = set(); own_t = 0.0; mine = set()
        while True:
            beat("wifiguard", 600, "Wi-Fi guard")
            if not self.want():
                if self.sock is not None:
                    self.close()
                time.sleep(5); continue
            if self.sock is None:
                if not self.open():
                    time.sleep(120); continue
            now = time.time()
            if now - own_t > 60:
                own = self.own_bssids(); own_t = now; mine = set(CFG.get("presence_macs") or [])
                d_ = datetime.now().strftime("%Y%m%d")
                if _PRESENCE_SALT["day"] != d_:
                    _PRESENCE_SALT.update(day=d_, salt=os.urandom(16)); seen.clear()
            try:
                pkt = self.sock.recv(4096)
            except OSError as e:
                if "timed out" not in str(e):
                    WGUARD.update(state="error", msg=str(e)[:120]); self.close(); time.sleep(30); continue
                pkt = b""
            if len(pkt) > 8:
                rl = pkt[2] | (pkt[3] << 8)
                f = pkt[rl:]
                if len(f) >= 16:
                    fc = f[0]; typ = (fc >> 2) & 3; sub = (fc >> 4) & 15
                    WGUARD["frames"] += 1
                    a2 = f[10:16].hex(":")
                    if typ == 0 and sub in (10, 12) and len(f) >= 22:          # disassociation / deauthentication
                        dall += 1
                        if f[16:22].hex(":") in own or a2 in own or f[4:10].hex(":") in own:
                            dea += 1
                    elif typ == 0 and sub == 4 and CFG.get("wifi_count"):    # probe request: only counted, never stored
                        import hashlib
                        seen[hashlib.sha256(_PRESENCE_SALT["salt"] + f[10:16]).hexdigest()[:12]] = now
                    if mine and a2 in mine:
                        TOOLS["presence"]["last"] = now
            if now - minute_t >= 60:
                minute_t = now
                WGUARD["deauth_min"] = (WGUARD["deauth_min"] + [[int(now), dea, dall]])[-120:]
                WGUARD["deauth_now"], WGUARD["all_now"] = dea, dall
                if CFG.get("wifi_count"):
                    for k in [k for k, t_ in seen.items() if now - t_ > 300]:
                        seen.pop(k, None)
                    WGUARD["count_now"] = len(seen)
                    WGUARD["count_hist"] = (WGUARD["count_hist"] + [[int(now), len(seen)]])[-288:]
                else:
                    seen.clear(); WGUARD["count_now"] = None
                if CFG.get("wifi_guard") and (dea >= int(CFG.get("wifi_guard_thr", 20)) or dall >= 300) and (not WGUARD["last_alarm"] or now - WGUARD["last_alarm"] > 1800):
                    WGUARD["last_alarm"] = now
                    txt = trf("Wi-Fi jamming: {n} disconnect frames in one minute ({all} in total on the channel)", n=dea, all=dall)
                    WGUARD["alarms"] = ([{"t": now, "n": dea, "all": dall}] + WGUARD["alarms"])[:20]
                    log_event("tamper", txt)
                    w = WATCH_REF.get("w")
                    if w is not None:
                        w.notifier.alert("{name}: " + tr("Wi-Fi jamming attack"), txt, getattr(w, "frame_out", None))
                dea = dall = 0
                presence_eval()


def dual_state():
    hs = STATE.get("hotspot") or {}; w = STATE.get("wifi") or {}
    return {"on": DUAL["on"], "ap": DUAL["ap"], "up": DUAL["up"], "adapters": DUAL["adapters"], "msg": DUAL["msg"], "log": DUAL["log"][:12],
            "sig": DUAL["sig"][-120:], "unstable": DUAL["unstable"], "offline_since": DUAL["offline_since"], "iso_msg": DUAL["iso_msg"],
            "repeater": bool(DUAL["on"] and hs.get("on") and w.get("connected")), "hotspot": {"on": hs.get("on"), "ssid": hs.get("ssid"), "clients": hs.get("clients")},
            "uplink": {"ssid": w.get("ssid"), "dbm": w.get("dbm"), "pct": w.get("pct"), "connected": w.get("connected")},
            "online": (STATE.get("net") or {}).get("online"),
            "cfg": {k: CFG.get(k) for k in ("wifi_repeater", "wifi_swap", "wifi_guard", "wifi_guard_thr", "wifi_count", "wifi_presence", "net_inet_notify", "net_noinet")},
            "guard": {k: WGUARD[k] for k in ("state", "iface", "msg", "deauth_min", "deauth_now", "all_now", "frames", "alarms", "count_now", "count_hist")}}


def dual_set(key, value):
    if key in ("wifi_repeater", "wifi_swap"):
        CFG[key] = bool(value); save_settings(); DUAL["choice"] = None; dual_roles()
        if key == "wifi_repeater" and value:
            log_event("sys", "Repeater switched on by hand")
        if STATE["hotspot"].get("on"):
            hotspot_switch_later(True, 0.5)
        return True, ""
    if key in ("wifi_guard", "wifi_count", "wifi_presence", "net_inet_notify"):
        CFG[key] = bool(value); save_settings(); return True, ""
    if key == "wifi_guard_thr":
        try:
            CFG[key] = int(min(500, max(5, int(value)))); save_settings(); return True, ""
        except (TypeError, ValueError):
            return False, "bad value"
    return False, "unknown setting"


def noinet_set(mac, on):
    mac = str(mac or "").lower()
    if not re.fullmatch(r"[0-9a-f]{2}(:[0-9a-f]{2}){5}", mac):
        return False, "bad address"
    L = [m for m in (CFG.get("net_noinet") or []) if m != mac]
    if on:
        L.append(mac)
    CFG["net_noinet"] = L[-30:]; save_settings()
    ok = noinet_apply(force=True)
    return ok, "" if ok else DUAL["iso_msg"]


# ----------------------------------------------------------------------------
# Network automatic: known networks first (e.g. the phone hotspot = internet + push messages), otherwise the own Wi-Fi.
#   start / connection lost: wait auto_wait seconds for a known network, then switch the own Wi-Fi on
#   own Wi-Fi on: every auto_retry minutes look for known networks again - only when no device is connected to the Pi
#   switching by hand (hotspot switch, camping profile) pauses the automatic until the network mode is chosen again
# Timers use time.monotonic(): the clock may jump when it is taken from the phone.
# ----------------------------------------------------------------------------
NETAUTO = {"paused": False, "status": "off"}
NETAUTO_SEARCH = 45.0                                   # seconds the own Wi-Fi stays off while known networks are tried


def netauto_pause():
    if CFG["net_mode"] == "auto" and not NETAUTO["paused"]:
        NETAUTO["paused"] = True
        log_event("sys", "Network automatic paused (switched by hand) - choose the network mode again to resume")


class NetAuto:
    def __init__(self):
        self.lost_since = None; self.next_retry = None
        threading.Thread(target=self.loop, daemon=True).start()

    def _set(self, status):
        if status != NETAUTO["status"]:
            NETAUTO["status"] = status
        STATE["netauto"] = status

    def wait_connected(self, seconds):
        end = time.monotonic() + seconds
        while time.monotonic() < end:
            time.sleep(1.0)
            w = STATE["wifi"] or {}
            if w.get("connected") and not STATE["hotspot"].get("on"):
                return w.get("ssid") or "?"
        return ""

    def step(self):
        if CFG["net_mode"] != "auto":
            self.lost_since = None; self.next_retry = None; self._set("off"); return
        if wifi_backend() != "nm":
            self._set("needs NetworkManager"); return
        if NETAUTO["paused"]:
            self._set("paused (switched by hand)"); return
        if WIFI["busy"] or WIFI.get("hs_busy"):
            return
        now = time.monotonic()
        hs, w = STATE["hotspot"] or {}, STATE["wifi"] or {}
        if DUAL["on"]:
            self.lost_since = None; self.next_retry = None
            if not hs.get("on"):
                ok, err = hotspot_set(True, persist=False); hotspot_refresh()
                self._set("own Wi-Fi on" if ok else "own Wi-Fi failed: " + err[:100]); return
            self._set(f"own Wi-Fi on + internet from «{w.get('ssid') or '?'}»" if w.get("connected")
                      else "own Wi-Fi on - the second adapter looks for known networks")
            return
        retry = max(0.0, float(CFG["auto_retry"])) * 60.0
        if hs.get("on"):
            self.lost_since = None
            if retry <= 0:
                self._set("own Wi-Fi on"); return
            if self.next_retry is None:
                self.next_retry = now + retry
            if now < self.next_retry:
                self._set(f"own Wi-Fi on - next search in {max(1, int((self.next_retry - now) / 60 + 0.99))} min"); return
            if hs.get("clients", 0) > 0:
                self.next_retry = now + min(60.0, retry)
                self._set("own Wi-Fi on - search postponed (a device is connected)"); return
            self._set("searching known networks …")
            log_event("sys", "Network automatic: own Wi-Fi off for a moment, looking for known networks")
            hotspot_set(False, persist=False); hotspot_refresh()
            ssid = self.wait_connected(NETAUTO_SEARCH)
            if ssid:
                self.next_retry = None
                log_event("sys", f"Network automatic: connected with «{ssid}»")
                self._set(f"connected with «{ssid}»")
            else:
                hotspot_set(True, persist=False); hotspot_refresh()
                self.next_retry = time.monotonic() + retry
                log_event("sys", "Network automatic: no known network - own Wi-Fi on again")
            return
        if w.get("connected"):
            self.lost_since = None; self.next_retry = None
            self._set(f"connected with «{w.get('ssid') or '?'}»"); return
        if self.lost_since is None:
            self.lost_since = now
        left = float(CFG["auto_wait"]) - (now - self.lost_since)
        if left > 0:
            self._set(f"no known network - own Wi-Fi in {int(left + 0.99)} s"); return
        log_event("sys", "Network automatic: no known network - switching the own Wi-Fi on")
        ok, err = hotspot_set(True, persist=False); hotspot_refresh()       # state at once, not 2 s later
        self.lost_since = None; self.next_retry = time.monotonic() + retry
        self._set("own Wi-Fi on" if ok else "own Wi-Fi failed: " + err[:100])

    def loop(self):
        while True:
            time.sleep(2.0)
            try:
                self.step()
            except Exception as e:
                self._set("error: " + str(e)[:100])


# ----------------------------------------------------------------------------
# Patrol: pendulum over waypoints  (1-2-3-2-1-2-3 ...)
# 2.98.30: «kluge Runde» - the stops come from kopf_patrol_plan() (part 162): the places of «Platz einrichten» with a
# longer stay at the tent and the access, hardly a stop at ignored directions; without places the waypoints. It runs only
# when «Patrouille» is on (aufr, decision Daniel - before also by itself in Wachsam / Voll), pauses while following and gives way to every
# mover with a higher rank (kopf_may). Battery low / deep night: it stays at the most important direction.
# ----------------------------------------------------------------------------
class Patrol:
    def __init__(self):
        self.paused_until = 0
        threading.Thread(target=self.loop, daemon=True).start()

    def _go_on(self):
        return not STATE["tracking"] and not servo_hold() and kopf_may("round") and bool(kopf_patrol_plan()[0])

    def move_to(self, pan, tilt):
        """drive pan and tilt together (straight line) at patrol_speed %/s; returns False if interrupted.
        2.98.35: through the motion planner (072, ramps) - no own ramp any more"""
        return servo_goto(pan, tilt, "round", speed=CFG["patrol_speed"], stop=lambda: not self._go_on())

    def loop(self):
        announced = ""
        while True:
            try:
                plan, why = kopf_patrol_plan()
            except Exception:
                plan, why = [], "off"
            if not plan:
                STATE["patrol_status"] = KOPF["status"] or why
                KOPF["round_on"] = False; announced = ""
                time.sleep(0.3); continue
            if servo_blocked():                           # 2.98.35: Not-Aus / fault / lock (072)
                STATE["patrol_status"] = "paused (servos stopped)"; KOPF["round_on"] = False
                time.sleep(0.3); continue
            if STATE["tracking"]:
                STATE["patrol_status"] = "paused (tracking person)"; KOPF["round_on"] = False
                time.sleep(0.2); continue
            if servo_hold():
                STATE["patrol_status"] = "paused (manual control)"; KOPF["round_on"] = False
                time.sleep(0.2); continue
            if not kopf_may("round"):
                STATE["patrol_status"] = "paused (the head is busy)"; KOPF["round_on"] = False
                time.sleep(0.3); continue
            KOPF["round_on"] = True
            sig = ";".join(f"{p[0]:.0f}/{p[1]:.0f}" for p in plan)
            if announced != sig:
                log_event("patrol", (f"Smart round over {len(plan)} directions: " if any(p[3] for p in plan) else f"Patrol started over {len(plan)} waypoints (pan/tilt): ")
                          + ", ".join((f"{p[3]} {p[2]:.0f}s" if p[3] else f"{p[0]:.0f}/{p[1]:.0f}") for p in plan))
                announced = sig
            # pendulum 1-2-3-2-1 (no doubled end points) or round trip 1-2-3-1-2-3
            path = plan if CFG["patrol_mode"] == "loop" or len(plan) < 3 else plan + plan[-2:0:-1]
            for i, wp in enumerate(path):
                STATE["patrol_status"] = f"moving to waypoint {i + 1}/{len(path)} ({wp[0]:.0f}/{wp[1]:.0f})"
                STATE["patrol_moving"] = True
                ok = self.move_to(wp[0], wp[1])
                STATE["patrol_moving"] = False
                if not ok:
                    break
                STATE["patrol_status"] = (why + " (" + wp[3] + ")") if why else f"dwelling at {(wp[3] + ' ') if wp[3] else ''}{wp[0]:.0f}/{wp[1]:.0f}"
                t_end = time.time() + wp[2]
                while time.time() < t_end:
                    if not self._go_on():
                        break
                    time.sleep(0.05)
                if not self._go_on() or len(plan) == 1:
                    break
# ----------------------------------------------------------------------------
# 2.98.30 (Wunsch Daniel): the pan / tilt head moves by itself - but always only ONE mover at a time. Who may move it:
#   1. by hand (joystick, buttons, reference scan, timelapse, wake-up alarm - servo_hold())
#   2. alarm / follow (410 follows a person or movement; «turn to the alarm» in Voll; the sabotage look-around)
#   3. walk test (the head follows the walker, 415)
#   4. quick look at the valuables (every 10-30 min)
#   5. the round (patrol / «kluge Runde» in Wachsam and Voll, part 160)
#   6. parking (Aus: the camera looks away)
# kopf_may(who) says whether nobody with a higher rank holds the head. The automatic moves (4-6, alarm turn) also wait
# while the simulator is busy with a task (simtask_busy, one lock - 141 / 147).
# The places come from «Platz einrichten» (place_items(), part 3XX) when it exists, otherwise from the waypoints.
# Angles: always via servo_half("pan") - the pan servo may turn 180 / 270 / 360°. A positional servo never passes its
# end stop (cable): with 360° every direction has exactly one place in 0 … 100 %, the head goes the allowed way there.
# Continuous rotation servos («360° endless», servo_kind = continuous): the position is only ESTIMATED from speed x time
# (Hardware.loop, part 080) - «set the middle» once the head looks straight ahead; shown as «estimated» everywhere.
# ----------------------------------------------------------------------------
for _k, _v in {"kopf_on": True, "kopf_round": True, "kopf_round_dwell": 8.0, "kopf_alarm": True, "kopf_return": True, "kopf_return_s": 20.0,
               "kopf_park": True, "kopf_park_pan": 50.0, "kopf_park_tilt": 5.0, "kopf_parked": False, "kopf_unpark": [],
               "kopf_glance": True, "kopf_glance_min": 15.0, "kopf_save": True, "kopf_night_from": 1.0, "kopf_night_to": 5.0,
               "kopf_walk": True, "kopf_wild": "auto", "kopf_wild_photo_s": 15.0, "kopf_tamper_look": True,
               "servo_kind": "positional", "cont_dps": 120.0, "cont_set_mid": False, "cont_est": 50.0}.items():
    CFG.setdefault(_k, _v)
    DEFAULTS.setdefault(_k, _v)
KOPF = {"started": False, "home": None, "home_t": 0.0, "home_pos": None, "back": None, "alarm": None, "turn_req": None,
        "turn_t": 0.0, "glance": "", "glance_next": 0.0, "glance_last": None, "round_on": False, "tamper": False,
        "armed_was": None, "noise_was": False, "noise_log": 0.0, "track_was": False, "wl_n": 0, "wild_photo_t": 0.0,
        "wild_photos": 0, "status": "", "val_cool": {}, "save_why": ""}
KOPF_PRIO = ("manual", "alarm", "walktest", "glance", "round", "park")
KOPF_WEIGHT = {"tent": 3.0, "access": 3.0, "valuable": 2.0, "public_path": 1.0, "ignore": 0.05}


# ---- angles (180 / 270 / 360° pan servos) ----------------------------------------------------------------------------
def kopf_pct_per_deg(axis="pan"):
    return 100.0 / (2.0 * servo_half(axis))


def kopf_pan_add(cur, ddeg):
    """the pan in % after turning ddeg degrees (+ = right) from cur %. A 360° servo: wrapped into its one turn (the allowed way,
    never over the end stop); smaller servos: up to their limit."""
    half = servo_half("pan")
    deg = (float(cur) - 50.0) / 50.0 * half + float(ddeg)
    if half >= 180.0:
        deg = (deg + 180.0) % 360.0 - 180.0
    (lo, hi), _t = Hardware.limits()
    return max(lo, min(hi, 50.0 + deg / half * 50.0))


def kopf_tilt_add(cur, ddeg):
    _p, (lo, hi) = Hardware.limits()
    return max(lo, min(hi, float(cur) + float(ddeg) * kopf_pct_per_deg("tilt")))


def kopf_pic_to_pan(cx, cy):
    """a point of the picture (0..1) -> (pan, tilt) in % where the head must look to have it in the middle"""
    hf, vf = cam_fov()
    p0, t0 = servo_pos()                                 # 2.98.35: the picture comes from the real position (072)
    return kopf_pan_add(p0, (cx - 0.5) * hf), kopf_tilt_add(t0, -(cy - 0.5) * vf)


def servo_estimated():
    """continuous rotation servo: the pan position is only an estimate"""
    return CFG.get("servo_kind") == "continuous" and not CFG.get("sim_on")


# ---- the places (Platz einrichten) or the waypoints ------------------------------------------------------------------
def kopf_items():
    """[{kind, pan, tilt, w_pan, h_tilt, name}] from place_items() (part 3XX «Platz einrichten») - [] while it does not exist"""
    c = KOPF.get("_items")
    if c and time.time() - c[0] < 2.0:
        return list(c[1])
    f = globals().get("place_items")
    if not callable(f):
        return []
    out = []
    try:
        for it in (f() or [])[:60]:
            if not isinstance(it, dict) or it.get("kind") not in KOPF_WEIGHT:
                continue
            out.append({"kind": it["kind"], "pan": max(0.0, min(100.0, float(it.get("pan", 50)))), "tilt": max(0.0, min(100.0, float(it.get("tilt", 50)))),
                        "w_pan": max(0.0, float(it.get("w_pan") or 0)), "h_tilt": max(0.0, float(it.get("h_tilt") or 0)),
                        "name": str(it.get("name") or tr(it["kind"]))[:40]})
    except Exception:
        return []
    KOPF["_items"] = (time.time(), out)
    return list(out)


def kopf_stops():
    """the directions of the round: [(pan, tilt, dwell s, name, weight)] sorted left -> right"""
    its = [i for i in kopf_items()]
    if its and CFG.get("kopf_on") and CFG.get("kopf_round"):
        base = max(1.0, float(CFG.get("kopf_round_dwell") or 8.0))
        st = [(i["pan"], i["tilt"], round(max(0.3, base * KOPF_WEIGHT[i["kind"]] / 3.0), 1), i["name"], KOPF_WEIGHT[i["kind"]]) for i in its]
        return sorted(st, key=lambda s: s[0])
    return [(w[0], w[1], float(CFG["patrol_dwell"]), wp_name(w), 1.0) for w in WAYPOINTS if wp_patrol(w)]   # 2.98.35: taught points (076)


def kopf_best():
    """the most important direction (tent / access first, then valuables …) - None without places"""
    its = [i for i in kopf_items() if i["kind"] != "ignore"]
    if its:
        b = max(its, key=lambda i: KOPF_WEIGHT[i["kind"]])
        return (b["pan"], b["tilt"], b["name"])
    return None


def kopf_ignored(pan, tilt):
    """does this direction lie in an «ignore» place (branches, road)?"""
    for i in kopf_items():
        if i["kind"] == "ignore" and abs(pan - i["pan"]) <= max(3.0, i["w_pan"] / 2.0) and abs(tilt - i["tilt"]) <= max(3.0, i["h_tilt"] / 2.0 or 50.0):
            return True
    return False


# ---- saving: battery low or deep night -------------------------------------------------------------------------------
def kopf_save_active():
    if not (CFG.get("kopf_on") and CFG.get("kopf_save")):
        return ""
    try:
        if batt_save_active():
            return "battery low"
    except NameError:
        pass
    a, b = float(CFG.get("kopf_night_from", 1)), float(CFG.get("kopf_night_to", 5))
    now = datetime.now(); h = now.hour + now.minute / 60.0
    if a != b and ((a < b and a <= h < b) or (a > b and (h >= a or h < b))):
        return "deep night"
    return ""


# ---- wildlife --------------------------------------------------------------------------------------------------------
def kopf_wild_active():
    if not CFG.get("kopf_on"):
        return False
    m = CFG.get("kopf_wild") or "auto"
    if m == "auto":
        return CFG.get("use_case") == "wild" or CFG.get("mode") == "wild"
    return m == "on"


def kopf_motion_gain():
    """410: following movement - slowly in the wildlife mode (the animal is not scared, the picture stays calm)"""
    return 0.45 if kopf_wild_active() else 1.0


def kopf_wild_quiet():
    """the wildlife mode: movement without a person (an animal) gives no pre-alarm, no siren and no light; persons still do"""
    if not kopf_wild_active() or STATE.get("persons"):
        return False
    return True                                          # wildlife watching: movement without a person is no alarm


_light_alarm_base = light_alarm


def light_alarm():                                   # wildlife: the light stays off while an animal is followed
    if kopf_wild_quiet():
        return
    _light_alarm_base()


def kopf_game_hand():
    """aufr (decision Daniel): a round of «Team gegen MoveEye» runs in the simulator (countdown / play) - the players at
    MoveEye steer the head, so MoveEye does not follow and moves the head by itself only after the round (nothing is
    switched off: «Folgen» is on again by itself afterwards). From the game state of the simulator (SIMGAME, 340)."""
    if not CFG.get("sim_on"):
        on = False
    else:
        try:
            g = sim_game()                                 # fetched fresh in the background every 2.5 s at most
        except Exception:
            g = SIMGAME.get("g") if "SIMGAME" in globals() else None
        on = bool(g) and g.get("mode") == "mwhand" and g.get("round") in ("play", "countdown")
    if on != KOPF.get("game_was", False):
        KOPF["game_was"] = on
        log_event("servo", "Game «Team gegen MoveEye»: following paused - the players steer the head" if on
                  else "Game round over: following and the automatic head movement go on")
    return on


def kopf_track_blocked():
    """410 track(): parked (Aus, privacy) or a game round where people steer the head - the head does not follow
    (except «KI zielt» / «KI-Autopilot» of the guards, part 542)"""
    return (bool(CFG.get("kopf_parked")) and bool(CFG.get("kopf_park")) and bool(CFG.get("kopf_on"))) or (kopf_game_hand() and not kihilfe_follow())


# ---- who holds the head ----------------------------------------------------------------------------------------------
def kopf_claims():
    c = set()
    try:
        if servo_hold() or REFSCAN.get("busy"):
            c.add("manual")
    except NameError:
        pass
    if (STATE.get("tracking") and not kopf_track_blocked()) or KOPF["alarm"] or KOPF["tamper"] or KOPF["back"]:
        c.add("alarm")                                   # (parked: following is blocked, it does not count)
    if walktest_on():
        c.add("walktest")
    if KOPF["glance"]:
        c.add("glance")
    if KOPF["round_on"]:
        c.add("round")
    if CFG.get("kopf_parked"):
        c.add("park")
    return c


def kopf_owner():
    c = kopf_claims()
    return next((p for p in KOPF_PRIO if p in c), "")


def kopf_may(who, sim_lock=True):
    """True when nobody with a higher rank holds the head (and, for the automatic moves, the simulator task lock is free)"""
    c = kopf_claims()
    for p in KOPF_PRIO:
        if p == who:
            break
        if p in c:
            return False
    if sim_lock and who not in ("manual",):
        try:
            if simtask_busy("protection test"):
                return False
        except NameError:
            pass
    if who != "manual" and KOPF.get("game_was") and kopf_game_hand():
        return False                                     # aufr: game round «Team gegen MoveEye» - only the players move the head
    return True


def kopf_move(pan, tilt, who, speed=None, stop=None):
    """drive smoothly to pan / tilt (%) at speed %/s; False when someone with a higher rank comes or stop() says so.
    2.98.35: through the motion planner (072) - ramps, limits, Not-Aus; no own ramp any more"""
    sp = float(speed or CFG.get("patrol_speed") or 30.0)

    def brk():
        return not kopf_may(who, sim_lock=who not in ("alarm",)) or (stop is not None and stop())
    return servo_goto(pan, tilt, who, speed=sp, stop=brk)


# ---- the round (called by the patrol, part 160) ----------------------------------------------------------------------
def kopf_patrol_plan():
    """(stops, why): what the patrol drives now. [] = it does not run (why = the status).
    aufr (decision Daniel): the round runs only when «Patrouille» is on - «kluge Runde» (kopf_round) only chooses the stops
    (places of «Platz einrichten», longer at the tent); without «Patrouille» the head stays at its home position."""
    if not CFG["patrol"]:
        return [], "off"
    stops = kopf_stops()
    sv = kopf_save_active()
    if sv and stops:
        b = kopf_best()
        st = (b[0], b[1], 30.0, b[2], 3.0) if b else max(stops, key=lambda s: s[4])
        KOPF["save_why"] = sv
        return [st], "saving: stays at the most important direction"
    KOPF["save_why"] = ""
    if len(stops) < 2:
        return [], "need 2+ waypoints" if CFG["patrol"] else "off"
    return stops, ""


# ---- the camera loop gives each picture (410) ------------------------------------------------------------------------
def kopf_frame(w, candidates, person_boxes, warm_boxes, present, frame, pw, ph, t0):
    if not KOPF["started"]:
        KOPF["started"] = True
        threading.Thread(target=_kopf_loop, daemon=True, name="kopf").start()
    if not CFG.get("kopf_on"):
        return
    if kopf_wild_active() and STATE.get("track_what") == "motion":
        KOPF["wild_t"] = time.time()
    # wildlife: a photo now and then while an animal is followed (not in the simulation: nothing goes into the recordings)
    if kopf_wild_active() and STATE.get("track_what") == "motion" and t0 - KOPF["wild_photo_t"] >= max(3.0, float(CFG.get("kopf_wild_photo_s") or 15)):
        KOPF["wild_photo_t"] = t0
        if CFG.get("sim_on"):
            KOPF["wild_photos"] += 1
            log_event("rec", "Wildlife: photo of the animal (simulation - not saved)")
        else:
            try:
                os.makedirs(CFG["record_dir"], exist_ok=True)
                name = f"wild_{datetime.now().strftime('%Y%m%d_%H%M%S')}.jpg"
                cv2.imwrite(os.path.join(CFG["record_dir"], name), frame, [cv2.IMWRITE_JPEG_QUALITY, 90])
                gps_tag_jpg(os.path.join(CFG["record_dir"], name))
                KOPF["wild_photos"] += 1
                log_event("rec", f"Wildlife: photo of the animal saved: {name}")
            except Exception as e:
                log_event("rec", f"Wildlife photo: {e}"[:160])
    # Voll: turn to the alarm (movement at the edge of the picture, a warm spot of the thermal camera)
    if not (CFG.get("kopf_alarm") and CFG.get("armed") and STATE.get("arm_state") == "armed" and protect_level() == "full"):
        return
    if (STATE.get("tracking") or KOPF["turn_req"] or t0 - KOPF["turn_t"] < 4.0 or t0 - KOPF.get("tamper_t", 0.0) < 15.0
            or t0 - float(w.mt.get("bg_reset", 0.0) or 0.0) < 3.0 or not kopf_may("alarm")):
        return
    req = None
    for bx, by, bw, bh in (warm_boxes or []):
        cx, cy = bx + bw / 2.0, by + bh / 2.0
        if abs(cx - 0.5) > 0.12 or abs(cy - 0.5) > 0.15:
            req = (cx, cy, "warm spot of the thermal camera"); break
    if req is None and "prealarm" in present:
        best = None
        for t in candidates or []:
            if (t.lost or t.is_vehicle or len(t.speeds) < 3 or t0 - t.born < 1.5 or t.box[2] * t.box[3] < 0.002 * pw * ph
                    or t.box[2] * t.box[3] > 0.15 * pw * ph):
                continue
            cx = (t.box[0] + t.box[2] / 2.0) / pw; cy = (t.box[1] + t.box[3] / 2.0) / ph
            if cx < 0.18 or cx > 0.82:
                if best is None or abs(cx - 0.5) > abs(best[0] - 0.5):
                    best = (cx, cy)
        if best:
            req = (best[0], best[1], "movement at the edge of the picture")
    if req is None:
        return
    pan, tilt = kopf_pic_to_pan(req[0], req[1])
    if kopf_ignored(pan, tilt):
        return                                            # branches / road: no turn
    KOPF["turn_req"] = (pan, tilt, req[2]); KOPF["turn_t"] = t0


# ---- the background loop ---------------------------------------------------------------------------------------------
def _kopf_loop():
    while True:
        time.sleep(0.25)
        try:
            _kopf_tick()
            STATE["kopf"] = dict(kopf_state(), text=kopf_text())
        except Exception as e:
            log_event("servo", f"Automatic head movement: {type(e).__name__}: {e}"[:200])
            time.sleep(2)


def _kopf_status(s):
    KOPF["status"] = s


def _kopf_tick():
    now = time.time()
    kopf_game_hand()                                     # aufr: notices the start / end of a round «Team gegen MoveEye»
    armed = bool(CFG.get("armed"))
    pos = (round(float(CFG["pan"]), 1), round(float(CFG["tilt"]), 1))
    on = bool(CFG.get("kopf_on"))
    # ---- Aus: park / back home when switched on ----
    if KOPF["armed_was"] is None:
        KOPF["armed_was"] = armed
    if armed != KOPF["armed_was"]:
        KOPF["armed_was"] = armed
        if not armed and on and CFG.get("kopf_park") and not walktest_on():
            CFG["kopf_unpark"] = list(KOPF["home"] or pos)
            CFG["kopf_parked"] = True; KOPF["back"] = None; KOPF["alarm"] = None
            log_event("servo", "Protection off: the camera looks away (privacy)")
            save_settings()
        elif armed:
            _kopf_val_reset()
            KOPF["glance_next"] = now + 120.0
            if CFG.get("kopf_parked"):
                CFG["kopf_parked"] = False
                u = CFG.get("kopf_unpark") or []
                if len(u) == 2:
                    KOPF["back"] = {"pos": (float(u[0]), float(u[1])), "since": 0.0, "why": "protection on"}
                log_event("servo", "Protection on: the camera looks back to its home position")
                save_settings()
    if CFG.get("kopf_parked"):
        if not (on and CFG.get("kopf_park")):
            CFG["kopf_parked"] = False
        elif manual_active() and not REFSCAN.get("busy"):
            CFG["kopf_parked"] = False
            log_event("servo", "Privacy ended: the camera was moved by hand")
        else:
            tgt = servo_park_target() or (50.0, 50.0)      # 2.98.35: a taught point may be the parking position (076)
            if abs(pos[0] - tgt[0]) > 0.6 or abs(pos[1] - tgt[1]) > 0.6:
                if kopf_may("park"):
                    _kopf_status("parking - the camera looks away (privacy)")
                    kopf_move(tgt[0], tgt[1], "park")
            _kopf_status("parked - the camera looks away (privacy)")
            return
    if KOPF["status"].startswith("park"):
        _kopf_status("")
    if not on:
        KOPF.update(back=None, alarm=None, turn_req=None); _kopf_status("")
        return
    tracking = bool(STATE.get("tracking"))
    if manual_active() and (KOPF["back"] or KOPF["alarm"]):
        KOPF["back"] = None; KOPF["alarm"] = None          # moved by hand: the hand decides where home is
    # ---- home: where the head stands still when nobody moves it ----
    if KOPF["home"] is None:
        KOPF["home"] = pos
    if KOPF["home_pos"] != pos:
        KOPF["home_pos"] = pos; KOPF["home_t"] = now
    if not kopf_claims() and now - KOPF["home_t"] > 8.0:
        KOPF["home"] = pos
    hpt = teach_point_by_name(CFG.get("kopf_home_point") or "")    # 2.98.35: a taught point as the home position (076)
    if hpt:
        KOPF["home"] = (round(hpt[0], 1), round(hpt[1], 1))
    # ---- following started (410): remember where to come back ----
    if tracking and not KOPF["track_was"] and not KOPF["back"] and KOPF["home"] and not KOPF["round_on"]:
        KOPF["back"] = {"pos": KOPF["home"], "since": 0.0, "why": "after following"}
    KOPF["track_was"] = tracking
    # ---- walk test: where the walker was lost ----
    _kopf_walk_tick(now)
    # ---- Voll: noise (one microphone has no direction: only with an access place) ----
    _kopf_noise_tick(now)
    # ---- the overview camera steers the head (same rank as the alarm) ----
    _kopf_ov_tick(now)
    # ---- Voll: the turn the camera loop asked for ----
    rq = KOPF["turn_req"]
    if rq:
        KOPF["turn_req"] = None
        if not tracking and kopf_may("alarm"):
            home = KOPF["home"] or pos
            KOPF["alarm"] = {"t": now, "why": rq[2]}
            if not KOPF["back"]:
                KOPF["back"] = {"pos": home, "since": 0.0, "why": "after the alarm"}
            log_event("servo", f"Turning to the alarm ({rq[2]}) - pan {rq[0]:.0f} % / tilt {rq[1]:.0f} %")
            _kopf_status("turned to the alarm")
            kopf_move(rq[0], rq[1], "alarm", speed=max(60.0, float(CFG.get("patrol_speed") or 30) * 2))
            KOPF["alarm"]["t"] = time.time()
    al = KOPF["alarm"]
    if al and not tracking and time.time() - al["t"] > 6.0:          # then «back» waits kopf_return_s
        KOPF["alarm"] = None
    elif al and tracking:
        al["t"] = time.time()
    # ---- back home after following / the alarm ----
    bk = KOPF["back"]
    if bk:
        if tracking or KOPF["alarm"]:
            bk["since"] = time.time()
        elif KOPF["round_on"] or not CFG.get("kopf_return"):
            KOPF["back"] = None                          # the round goes on by itself / not wanted
        elif time.time() - bk["since"] > (2.0 if bk["why"] == "protection on" else float(CFG.get("kopf_return_s") or 20)):
            if servo_hold() or REFSCAN.get("busy"):
                KOPF["back"] = None                      # somebody took the head by hand
            else:
                _kopf_status("back to the home position")
                p = bk["pos"]
                KOPF["back"] = None
                log_event("servo", f"Back to the home position ({bk['why']}): pan {p[0]:.0f} % / tilt {p[1]:.0f} %")
                KOPF["alarm"] = {"t": time.time(), "why": "back"}       # holds the rank while driving
                try:
                    kopf_move(p[0], p[1], "alarm")
                finally:
                    KOPF["alarm"] = None
                KOPF["home"] = (round(float(CFG["pan"]), 1), round(float(CFG["tilt"]), 1)); KOPF["home_t"] = time.time()
    # ---- quick look at the valuables ----
    _kopf_glance_tick(now)
    own = kopf_owner()
    if KOPF["glance"]:
        _kopf_status("quick look at the valuables")
    elif KOPF["alarm"] and KOPF["alarm"].get("why") != "back":
        _kopf_status("turned to the alarm")
    elif own == "round" and KOPF["save_why"]:
        _kopf_status("saving: stays at the most important direction")
    elif KOPF.get("game_was"):
        _kopf_status("game round: the players steer the head - following paused")
    else:
        _kopf_status("")


def _kopf_noise_tick(now):
    a = globals().get("AUDIO")
    noisy = bool(a is not None and getattr(a, "noise_alerted", False))
    rise = noisy and not KOPF["noise_was"]
    KOPF["noise_was"] = noisy
    if not rise or not (CFG.get("kopf_alarm") and is_armed() and protect_level() == "full") or STATE.get("tracking"):
        return
    acc = [i for i in kopf_items() if i["kind"] == "access"]
    if not acc:
        if now - KOPF["noise_log"] > 600:
            KOPF["noise_log"] = now
            log_event("servo", "Noise: no direction known (one microphone, no access in «Platz einrichten») - the head stays")
        return
    i = min(acc, key=lambda i: abs(i["pan"] - CFG["pan"]))
    if abs(i["pan"] - CFG["pan"]) > 2 or abs(i["tilt"] - CFG["tilt"]) > 2:
        KOPF["turn_req"] = (i["pan"], i["tilt"], "noise - looking at the access «%s»" % i["name"])


# ---- walk test: the head follows, where it lost the walker (415) -----------------------------------------------------
def kopf_walk_follow():
    try:
        head = live_has_head()
    except Exception:
        head = False
    return bool(CFG.get("kopf_on") and CFG.get("kopf_walk") and head)


def _kopf_walk_tick(now):
    if not WALK.get("on") or not WALK.get("follow"):
        KOPF["wl_n"] = 0
        return
    hits = WALK["hits"]
    n = len(hits)
    if not n:
        return
    rel = now - WALK["t0"]
    seen = n - KOPF["wl_n"]
    if seen >= 3 and rel - hits[-1][0] > 3.0:
        hp = (WALK.get("hp") or [(CFG["pan"], CFG["tilt"])])[-1]
        lost = {"t": hits[-1][0], "nx": hits[-1][1], "ny": hits[-1][2], "m": hits[-1][3], "pan": hp[0], "tilt": hp[1]}
        WALK.setdefault("lost", []).append(lost)
        KOPF["wl_n"] = n
        log_event("sys", "Walk test: the head lost you" + (f" at about {dist_round(lost['m'])} m" if lost["m"] else "")
                  + f" (pan {lost['pan']:.0f} %)")


def kopf_walk_where(nx, pan, ref_pan):
    """a point of a picture taken at pan -> the same direction in the picture taken at ref_pan (0..1, may lie outside)"""
    hf, _vf = cam_fov()
    return nx + (float(pan) - float(ref_pan)) / kopf_pct_per_deg("pan") / max(1.0, hf)


def kopf_walk_lost_text(res, lang=None):
    L = res.get("lost") or []
    if not L:
        return []
    parts = []
    for x in L[:5]:
        side = tr("left", lang) if x["pan"] < 45 else (tr("right", lang) if x["pan"] > 55 else tr("in the middle", lang))
        parts.append((trf("about {m} m", lang, m=dist_round(x["m"])) + ", " if x.get("m") else "") + side + f" ({x['pan']:.0f} %)")
    return [trf("The head lost you {n}x: {where}. There the camera hardly sees you - try a better place or more light.", lang,
                n=len(L), where="; ".join(parts))]


# ---- quick look at the valuables -------------------------------------------------------------------------------------
def _kopf_val_dir():
    return os.path.join(DATA_DIR, "kopfauto")


def _kopf_val_reset():
    """armed now: the own references are taken anew at the first look («as you left it»)"""
    shutil.rmtree(_kopf_val_dir(), ignore_errors=True)


def kopf_valuables():
    """[{name, pan, tilt, box (x, y, w, h of the picture), src: place | refscan, pos (refscan position)}]"""
    out = []
    hf, vf = cam_fov()
    for i in kopf_items():
        if i["kind"] != "valuable":
            continue
        bw = min(0.9, max(0.08, (i["w_pan"] / kopf_pct_per_deg("pan")) / max(1.0, hf))) if i["w_pan"] else 0.3
        bh = min(0.9, max(0.08, (i["h_tilt"] / kopf_pct_per_deg("tilt")) / max(1.0, vf))) if i["h_tilt"] else 0.3
        out.append({"name": i["name"], "pan": i["pan"], "tilt": i["tilt"], "box": (0.5 - bw / 2, 0.5 - bh / 2, bw, bh), "src": "place"})
    if out:
        return out
    try:
        meta = refscan_meta() or {}
    except NameError:
        meta = {}
    pos = {int(p["i"]): p for p in meta.get("positions") or []}
    for it in meta.get("watch") or []:
        p = pos.get(int(it.get("pos", -1)))
        if p:
            out.append({"name": it["name"], "pan": p["pan"], "tilt": p["tilt"], "box": (it["x"], it["y"], it["w"], it["h"]),
                        "src": "refscan", "pos": int(p["i"]), "file": p["file"], "kind": meta.get("_kind", "day")})
    return out


def _kopf_glance_tick(now):
    if not (CFG.get("kopf_glance") and CFG.get("armed") and STATE.get("arm_state") == "armed") or KOPF["glance"]:
        if not CFG.get("armed"):
            KOPF["glance_next"] = 0.0
        return
    every = max(5.0, min(120.0, float(CFG.get("kopf_glance_min") or 15))) * 60.0 * (2.0 if kopf_save_active() else 1.0)
    if not KOPF["glance_next"]:
        KOPF["glance_next"] = now + every
    if now < KOPF["glance_next"]:
        return
    if STATE.get("tracking") or STATE.get("persons") or not kopf_may("glance") or WATCH_REF.get("w") is None:
        KOPF["glance_next"] = now + 30.0
        return
    vals = kopf_valuables()
    KOPF["glance_next"] = now + every
    if not vals:
        return
    KOPF["glance"] = "starting"
    threading.Thread(target=_kopf_glance_run, args=(vals,), daemon=True, name="kopf-glance").start()


def kopf_glance_now():
    """for tests and the button: look at the valuables now"""
    if KOPF["glance"]:
        return False, "already looking"
    vals = kopf_valuables()
    if not vals:
        return False, "no valuables (Platz einrichten or reference scan)"
    KOPF["glance"] = "starting"
    threading.Thread(target=_kopf_glance_run, args=(vals,), daemon=True, name="kopf-glance").start()
    return True, ""


def _kopf_glance_abort():
    return bool(STATE.get("tracking") or KOPF["turn_req"] or servo_hold() or REFSCAN.get("busy"))


def _kopf_glance_run(vals):
    w = WATCH_REF.get("w")
    old = (float(CFG["pan"]), float(CFG["tilt"]))
    res = {"t": time.time(), "items": [], "gone": []}
    end = time.time() + 20.0                             # started by hand: wait a moment until the head is free
    while time.time() < end and (_kopf_glance_abort() or not kopf_may("glance")):
        time.sleep(0.3)
    old = (float(CFG["pan"]), float(CFG["tilt"]))
    try:
        _kopf_status("quick look at the valuables")
        log_event("servo", "Quick look at the valuables: " + ", ".join(v["name"] for v in vals))
        groups = {}
        for v in vals:
            groups.setdefault((round(v["pan"], 1), round(v["tilt"], 1)), []).append(v)
        for (pn, tl), items in groups.items():
            KOPF["glance"] = items[0]["name"]
            if _kopf_glance_abort() or not kopf_move(pn, tl, "glance", speed=max(40.0, float(CFG.get("patrol_speed") or 30)), stop=_kopf_glance_abort):
                res["aborted"] = True; break
            for v in items:
                g = _kopf_val_check(w, v)
                if g is None:
                    continue
                res["items"].append({"name": v["name"], "gone": g[0], "score": g[1], "ref": g[2]})
                if g[0]:
                    time.sleep(1.5)                     # a second look: somebody walking past is no theft
                    g2 = _kopf_val_check(w, v)
                    if g2 is not None and g2[0]:
                        res["gone"].append(v["name"]); _kopf_val_alarm(w, v, g2[3])
    finally:
        KOPF["glance_last"] = res
        if not _kopf_glance_abort():
            kopf_move(old[0], old[1], "glance", stop=_kopf_glance_abort)
        KOPF["glance"] = ""
        log_event("servo", "Quick look at the valuables done: " + (", ".join(f"{x['name']} {'MISSING' if x['gone'] else 'ok'}" for x in res["items"]) or "no picture")
                  + (" (interrupted)" if res.get("aborted") else ""))


def _kopf_val_check(w, v):
    """(gone, score, which reference, marked picture) or None (no picture). Reuses the comparison of the reference scan."""
    cur = _refscan_grab(w, _refscan_settle(), 2)
    if cur is None:
        return None
    kind = "night" if refscan_is_dark() else "day"
    ref = None; which = "own"
    if v["src"] == "refscan":
        ref = cv2.imread(refscan_dir(REFSCAN_KINDS.get(v.get("kind", "day"), "ref"), v["file"])); which = "reference scan"
    else:
        os.makedirs(_kopf_val_dir(), exist_ok=True)
        fn = os.path.join(_kopf_val_dir(), "val_%s_%s.jpg" % (re.sub(r"[^A-Za-z0-9]+", "_", v["name"])[:30] or "x", kind))
        ref = cv2.imread(fn)
        if ref is None:
            cv2.imwrite(fn, cur, [cv2.IMWRITE_JPEG_QUALITY, 90])
            return (False, 0.0, "reference taken now", cur)
    if ref is None:
        return None
    if cur.shape != ref.shape:
        cur = cv2.resize(cur, (ref.shape[1], ref.shape[0]))
    ch, _sh, dmap = refscan_compare_images(ref, cur)
    x, y, bw, bh = v["box"]
    gone, sc = _refscan_watch_check({"x": x, "y": y, "w": bw, "h": bh}, dmap, ch)
    img = _refscan_mark_watch(_refscan_mark(cur, ch), [{"x": x, "y": y, "w": bw, "h": bh, "name": v["name"], "gone": gone}])
    return (gone, sc, which, img)


def _kopf_val_alarm(w, v, img):
    now = time.time()
    if now - KOPF["val_cool"].get(v["name"], 0.0) < 1800 or not is_armed():
        return
    KOPF["val_cool"][v["name"]] = now
    txt = trf("Guarded thing missing: {names}", names=v["name"]) + " (" + tr("quick look of the head") + ")"
    log_event("alarm", "Quick look: guarded thing missing: " + v["name"])
    push_alert("refscan", txt)
    try:
        w.notifier.alert("{name}: " + tr("Quick look at the valuables"), txt, img)
    except Exception:
        pass


# ---- sabotage: covered or turned? (060 TamperGuard.alarm) ------------------------------------------------------------
def kopf_tamper_wanted():
    try:
        head = live_has_head()
    except Exception:
        head = False
    return bool(CFG.get("kopf_on") and CFG.get("kopf_tamper_look") and head and not KOPF["tamper"] and not servo_hold())


def _kopf_gray(w, settle):
    time.sleep(settle)
    end = time.time() + 8.0; t_ = time.time()
    while time.time() < end:
        w.raw_until = time.time() + 10
        fr = w.frame_raw
        if fr is not None and float(getattr(w, "_last_t0", 0) or 0) > t_:
            g = cv2.cvtColor(fr, cv2.COLOR_BGR2GRAY) if fr.ndim == 3 else fr
            return cv2.resize(g, (80, 60), interpolation=cv2.INTER_AREA).astype(np.float32)
        time.sleep(0.05)
    return None


def kopf_tamper_look(what, ref):
    """the head looks left and right: dark everywhere = covered; the old view found elsewhere = turned (by how much).
    Returns a short text for the push (already translated) or ''."""
    w = WATCH_REF.get("w")
    if w is None or ref is None:
        return ""
    KOPF["tamper"] = True
    p0, q0 = float(CFG["pan"]), float(CFG["tilt"])
    hf, _vf = cam_fov()
    looks = []
    ref_e = cv2.magnitude(cv2.Sobel(ref, cv2.CV_32F, 1, 0), cv2.Sobel(ref, cv2.CV_32F, 0, 1))
    try:
        settle = 1.0 + (1.5 if CFG.get("sim_on") else 0.0)
        for f in (-1.0, -0.5, 0.5, 1.0):
            ddeg = f * hf * 0.9
            p = kopf_pan_add(p0, ddeg)
            if abs(p - p0) < 1.0:
                continue
            if not servo_goto(p, q0, "alarm", timeout=8.0):      # 2.98.35: the planner drives, wait until it stands
                break
            g = _kopf_gray(w, settle)
            if g is None:
                continue
            tpl = ref[12:48, 16:64].astype(np.float32)
            sc, sh = 0.0, 0.0
            try:
                r = cv2.matchTemplate(g, tpl, cv2.TM_CCOEFF_NORMED)
                _a, sc, _b, loc = cv2.minMaxLoc(r)
                sh = (loc[0] - 16) / 80.0 * hf             # where the old middle is in this picture
            except cv2.error:
                pass
            e = cv2.magnitude(cv2.Sobel(g, cv2.CV_32F, 1, 0), cv2.Sobel(g, cv2.CV_32F, 0, 1))
            flat = float(g.std()) < 7 and float(e.mean()) < 0.25 * max(1e-3, float(ref_e.mean())) if ref_e is not None else False
            looks.append({"ddeg": (p - p0) / kopf_pct_per_deg("pan"), "dark": (float(g.mean()) < 18 and float(g.std()) < 7) or flat, "sc": float(sc), "sh": sh})
    finally:
        servo_goto(p0, q0, "alarm", timeout=8.0)
        KOPF["tamper"] = False; KOPF["tamper_t"] = time.time()
    if not looks:
        return ""
    if all(x["dark"] for x in looks):
        return tr("the head looked left and right: dark everywhere - the lens is covered")
    best = max(looks, key=lambda x: x["sc"])
    if best["sc"] > 0.55:
        deg = best["ddeg"] + best["sh"]
        side = tr("right") if deg > 0 else tr("left")
        return trf("the head looked around: the old view is now about {deg}° to the {side} - the device was turned", deg=int(round(abs(deg))), side=side)
    if what == "covered":
        return tr("the head looked left and right: the other directions are visible - something stands right in front of the camera")
    return tr("the head looked left and right: the old view was not found - turned a lot, or the place changed")


# ---- state for the pages ---------------------------------------------------------------------------------------------
def kopf_state(lang=None):
    gl = KOPF["glance_last"]
    return {"on": bool(CFG.get("kopf_on")), "owner": kopf_owner(), "status": tr(KOPF["status"], lang) if KOPF["status"] else "",
            "parked": bool(CFG.get("kopf_parked")), "save": kopf_save_active(), "wild": kopf_wild_active(), "wild_photos": KOPF["wild_photos"],
            "glance": KOPF["glance"], "glance_next": int(KOPF["glance_next"]) if KOPF["glance_next"] else 0,
            "glance_last": gl, "estimated": servo_estimated(), "cont_est": round(float(CFG.get("cont_est", 50)), 1),
            "items": len(kopf_items()), "home": KOPF["home"]}


def kopf_text(lang=None):
    """one line for the live page / the window (empty when nothing special)"""
    s = kopf_state(lang)
    out = []
    if s["status"]:
        out.append(s["status"])
    if s["save"]:
        out.append(tr("saving: " + s["save"], lang))
    if s["wild"]:
        out.append(tr("wildlife mode", lang))
    if s["estimated"]:
        out.append(tr("position only estimated (continuous servo)", lang))
    return " · ".join(out)


# ---- «Übersicht lenkt den Kopf»: a fixed wide-angle extra camera (440) steers the head ------------------------------
# Its motion boxes -> a direction: box centre x -> angle in the overview (its field of view, cam_fov_h(spec) of the other
# part or kopf_ov_fov) + where the overview looks (kopf_ov_offset, degrees from the head's middle = pan 50 %). When that
# direction is outside the picture of the head, the head turns there (same rank as «turn to the alarm») and the AI of the
# main camera checks what it is. «Kalibrieren»: point the head at something that moves in the overview, then switch
# «kopf_ov_calib» on (or POST /api/kopf {"do": "ov_calib", "x": 0..1} for a tap on the overview picture).
for _k, _v in {"kopf_ov": "", "kopf_ov_on": True, "kopf_ov_offset": 0.0, "kopf_ov_fov": 102.0, "kopf_ov_calib": False}.items():
    CFG.setdefault(_k, _v)
    DEFAULTS.setdefault(_k, _v)


def kopf_ov_cam():
    sp = str(CFG.get("kopf_ov") or "")
    if not sp:
        return None
    return next((c for c in CAMS if str(c.spec) == sp), None)


def kopf_ov_fov():
    f = globals().get("cam_fov_h")
    if callable(f):
        try:
            v = float(f(CFG.get("kopf_ov")))
            if 10.0 <= v <= 360.0:
                return v
        except Exception:
            pass
    return max(10.0, min(360.0, float(CFG.get("kopf_ov_fov") or 102.0)))


def kopf_ov_deg(cx):
    """x of the overview picture (0..1) -> degrees from the head's middle (pan 50 %), + = right"""
    return float(CFG.get("kopf_ov_offset") or 0.0) + (float(cx) - 0.5) * kopf_ov_fov()


def kopf_ov_target(c):
    """(cx, size) of the biggest moving box of the overview, or None"""
    wh = getattr(c, "wh", None)
    if not wh or not c.motion or c.streak < 2 or not c.boxes:
        return None
    x, y, w, h = max(c.boxes, key=lambda b: b[2] * b[3])
    if w * h > 0.3 * wh[0] * wh[1]:
        return None                                       # half the picture «moves»: light, wind
    return ((x + w / 2.0) / wh[0], w * h / float(wh[0] * wh[1]))


def kopf_ov_calibrate(cx=None, who="web"):
    """the head looks at the thing; cx = where it is in the overview (None: the one moving box there)"""
    c = kopf_ov_cam()
    if c is None:
        return False, "no overview camera chosen"
    if cx is None:
        t = kopf_ov_target(c)
        if t is None:
            return False, "the overview sees no movement right now"
        cx = t[0]
    head = (float(CFG["pan"]) - 50.0) / 50.0 * servo_half("pan")
    CFG["kopf_ov_offset"] = round(head - (float(cx) - 0.5) * kopf_ov_fov(), 1)
    save_settings()
    log_event("servo", f"Overview calibrated ({who}): it looks {CFG['kopf_ov_offset']:+.0f}° from the middle of the head")
    return True, ""


def _kopf_ov_tick(now):
    if CFG.get("kopf_ov_calib"):
        CFG["kopf_ov_calib"] = False
        ok, err = kopf_ov_calibrate(None, "switch")
        if not ok:
            log_event("servo", "Overview: calibration not possible - " + err)
        save_settings()
    if not (CFG.get("kopf_on") and CFG.get("kopf_ov_on") and CFG.get("armed") and STATE.get("arm_state") == "armed"):
        return
    c = kopf_ov_cam()
    if c is None or STATE.get("tracking") or KOPF["turn_req"] or now - KOPF.get("ov_t", 0.0) < 6.0 or not kopf_may("alarm"):
        return
    t = kopf_ov_target(c)
    if t is None:
        return
    pan = kopf_pan_add(50.0, kopf_ov_deg(t[0]))
    hf, _vf = cam_fov()
    if abs(pan - CFG["pan"]) < hf * 0.35 * kopf_pct_per_deg("pan") or kopf_ignored(pan, CFG["tilt"]):
        return                                            # already in the picture of the head / an ignored direction
    KOPF["ov_t"] = now
    KOPF["turn_req"] = (pan, float(CFG["tilt"]), "movement seen by the overview camera")
# ----------------------------------------------------------------------------
# Plan Daniel 30.10.2026 (docs/Gehaeuse_Variante2_Weitwinkel.md, «Simulator-Einbindung der Weitwinkel-Kamera»):
#  - The simulator (3D-4.17, weitwinkel.gd) has ONE wide camera (sim:1, 102° x 67°) with a mount: scene (mast, as before),
#    base (lower part of the device, fixed), head_front / head_rear (turns with the pan, rear = yaw offset 180°).
#    /info cameras[1] and the reply to every POST /state («wide») tell the mount, tilt_deg, yaw_offset, pan_follow,
#    tilt_follow, fov_h / fov_v, on_head.
#  - On the device (base / head_*): «Übersicht lenkt den Kopf» (162: kopf_ov) is set to sim:1 by itself - only when the
#    mount changes (or at the first contact), so a choice by hand stays. Mast = not part of the device: not by itself
#    (as before); when it was set by itself, it is cleared again.
#  - Head mounts: the direction of a box = where the head REALLY is (the simulated head, else servo_pos) + yaw offset +
#    the angle in the picture (instead of the fixed kopf_ov_offset). While the head turns (and a short settle time after),
#    the extra camera on the head ignores its movement (the same signals the main camera uses: SRV moving, SERVO_MOVE,
#    a change of the position) - 440 asks weit_cam_turning().
#  - Rear mount: movement behind -> the head turns there (162 _kopf_ov_tick, same rank as «turn to the alarm»), then the
#    AI of the main camera checks.
#  - Second infrared LED 120° on PCA9685 channel 4 («IR-Licht breit (Kanal 4)»): on / off together with the infrared
#    light (070 lights_tick); the simulator gets lights.ir_wide.
# ----------------------------------------------------------------------------
for _k, _v in {"light_ir_wide": False, "kopf_ov_simauto": False}.items():
    CFG.setdefault(_k, _v)
    DEFAULTS.setdefault(_k, _v)
WEIT = {"mount": None, "seen": False, "hd": None, "hd_t": 0.0, "pt": None, "pt_t": 0.0}
WEIT_DEVICE_MOUNTS = ("base", "head_front", "head_rear")
WEIT_IR_CH = 4                                            # PCA9685 channel of the wide infrared LED (white 2, IR 3 by convention)


# ---- what the simulator says about its wide camera -------------------------------------------------------------------
def weit_sim_cam():
    """cameras[1] of the simulator (dict) or None"""
    if not CFG.get("sim_on"):
        return None
    try:
        return next((c for c in (SIM.get("info") or {}).get("cameras") or [] if str(c.get("id")) == "1"), None)
    except (AttributeError, TypeError):
        return None


def weit_mount():
    c = weit_sim_cam()
    return str(c.get("mount") or "scene") if c else ""


def weit_on_device():
    return weit_mount() in WEIT_DEVICE_MOUNTS


def weit_from_sim(w):
    """350: the reply to POST /state carries «wide» - a new mount is known at once (no new /info needed)"""
    if not isinstance(w, dict) or not CFG.get("sim_on"):
        return
    c = weit_sim_cam()
    if c is not None:
        for k in ("mount", "tilt_deg", "yaw_offset", "pan_follow", "tilt_follow", "on_head", "fov_h", "fov_v", "pan_limit"):
            if k in w:
                c[k] = w[k]
    weit_auto()


def weit_auto():
    """«Übersicht lenkt den Kopf» by itself when the wide camera is on the device - only at a change of the mount"""
    m = weit_mount()
    if not m or m == WEIT["mount"]:
        return
    first = WEIT["mount"] is None
    WEIT["mount"] = m
    cur = str(CFG.get("kopf_ov") or "")
    changed = False
    if m in WEIT_DEVICE_MOUNTS:
        if cur in ("", "sim:1") and "sim:1" in (CFG.get("extra_cams") or []):
            if cur != "sim:1" or not CFG.get("kopf_ov_simauto"):
                log_event("servo", f"Simulator: the wide camera sits on the device ({m}) - it steers the head as overview")
            CFG["kopf_ov"] = "sim:1"; CFG["kopf_ov_simauto"] = True; changed = True
    elif cur == "sim:1" and CFG.get("kopf_ov_simauto"):
        CFG["kopf_ov"] = ""; CFG["kopf_ov_simauto"] = False; changed = True
        if not first:
            log_event("servo", "Simulator: the wide camera is on the mast again - no longer the overview of the head")
    if changed:
        save_settings()


def weit_ov_geom():
    """(yaw_offset, on_head) when the overview is the simulator's wide camera on the device, else None"""
    if str(CFG.get("kopf_ov") or "") != "sim:1":
        return None
    c = weit_sim_cam()
    if not c or str(c.get("mount") or "scene") not in WEIT_DEVICE_MOUNTS:
        return None
    try:
        return float(c.get("yaw_offset") or 0.0), bool(c.get("on_head"))
    except (TypeError, ValueError):
        return None


def weit_head_deg():
    """where the head really looks (degrees, + = right): the simulated head, else the planned position"""
    h = SIM.get("head") if CFG.get("sim_on") else None
    if isinstance(h, list) and h:
        try:
            return float(h[0])
        except (TypeError, ValueError):
            pass
    return servo_pos_deg()[0]


_kopf_ov_deg_162 = kopf_ov_deg


def kopf_ov_deg(cx):                                      # + 163: the wide camera on the device (base: fixed, head: turns)
    g = weit_ov_geom()
    if g is None:
        return _kopf_ov_deg_162(cx)
    d = g[0] + (float(cx) - 0.5) * kopf_ov_fov() + (weit_head_deg() if g[1] else 0.0)
    return (d + 180.0) % 360.0 - 180.0


# ---- the camera on the head moves itself: no movement while it turns ------------------------------------------------
def weit_cam_turning(spec):
    """440: True while an extra camera that sits on the head turns (and a short settle time after) - the whole picture
    «moves» then. Same signals as the main camera (410 foreground): SRV moving, SERVO_MOVE, a change of the position;
    in the simulation also the simulated head (it follows a moment later)."""
    try:
        if not cam_on_head(spec):
            return False
    except NameError:
        return False
    now = time.time()
    settle = 1.2 if CFG.get("sim_on") else 0.8
    pt = (round(float(CFG["pan"]), 1), round(float(CFG["tilt"]), 1))
    if pt != WEIT["pt"]:
        WEIT["pt"] = pt; WEIT["pt_t"] = now
    h = SIM.get("head") if CFG.get("sim_on") else None
    if isinstance(h, list) and len(h) >= 2:
        hd = (round(float(h[0]), 1), round(float(h[1]), 1))
        if hd != WEIT["hd"]:
            WEIT["hd"] = hd; WEIT["hd_t"] = now
    moving = bool(SRV.get("moving")) or now - float(SERVO_MOVE.get("t") or 0.0) < settle
    return moving or now - WEIT["pt_t"] < settle or now - WEIT["hd_t"] < settle


# ---- the wide infrared light on channel 4 -----------------------------------------------------------------------------
def weit_ir_ch_free():
    """channel 4 is not taken by the white / infrared light or a servo"""
    used = {str(CFG.get("light_white_out") or ""), str(CFG.get("light_ir_out") or "")}
    return f"pca:{WEIT_IR_CH}" not in used and WEIT_IR_CH not in (int(CFG.get("pca_pan_ch", 0)), int(CFG.get("pca_tilt_ch", 1)))


_lights_tick_070 = lights_tick


def lights_tick():                                        # + 163: the wide infrared light follows the infrared light
    prev = bool((STATE.get("lights") or {}).get("ir_wide"))
    res = _lights_tick_070()
    on = bool(res.get("ir")) and bool(CFG.get("light_ir_wide"))
    if on != prev:
        log_event("relay", f"Wide infrared light {'ON' if on else 'OFF'}")
    res["ir_wide"] = on
    STATE["lights"] = dict(STATE.get("lights") or {}, ir_wide=on)
    return res


_hw_lights_070 = Hardware._lights


def _weit_hw_lights(self, wanted):
    _hw_lights_070(self, wanted)
    if self.pca is None:
        return
    on = bool((STATE.get("lights") or {}).get("ir_wide")) and weit_ir_ch_free()
    if getattr(self, "_weit_ir", None) != on:
        try:
            self.pca.switch(WEIT_IR_CH, on); self._weit_ir = on
        except Exception as e:
            log_event("servo", f"Light error (channel {WEIT_IR_CH}): {e}")


# wraps: Hardware._lights
Hardware._lights = _weit_hw_lights
_light_out_pairs_070 = light_out_pairs


def light_out_pairs(name):                                # + 163: channel 4 belongs to the wide infrared light when it is on
    p = _light_out_pairs_070(name)
    if CFG.get("light_ir_wide"):
        p = [x for x in p if x[0] != f"pca:{WEIT_IR_CH}" or x[0] == CFG.get(f"light_{name}_out")]
    return p


def weit_state(lang=None):
    """for pages: the wide camera of the simulator (mount, overview, its extra camera number)"""
    c = weit_sim_cam()
    if not c or "mount" not in c:
        return None
    n = next((x.idx for x in CAMS if str(x.spec) == "sim:1"), None)
    return {"mount": str(c.get("mount")), "on_head": bool(c.get("on_head")), "tilt": c.get("tilt_deg"), "n": n,
            "ov": str(CFG.get("kopf_ov") or "") == "sim:1", "ov_on": bool(CFG.get("kopf_ov_on")), "fov": [c.get("fov_h"), c.get("fov_v")]}
# ----------------------------------------------------------------------------
# AI person detector (SSD MobileNet V2, COCO class 1 = person)
# ----------------------------------------------------------------------------
AI_MODEL = {"busy": False, "msg": "", "pct": 0}
AI_TGZ_URLS = ("https://storage.googleapis.com/download.tensorflow.org/models/object_detection/ssd_mobilenet_v2_coco_2018_03_29.tar.gz",
               "https://download.tensorflow.org/models/object_detection/ssd_mobilenet_v2_coco_2018_03_29.tar.gz")
AI_PBTXT_URL = "https://raw.githubusercontent.com/opencv/opencv_extra/master/testdata/dnn/ssd_mobilenet_v2_coco_2018_03_29.pbtxt"


def ai_model_dirs():
    return [os.path.dirname(os.path.abspath(__file__)), os.path.join(DATA_DIR, "models")]


def ai_model_paths():
    """(pb, pbtxt) of the first folder that has both files - next to the program or in the data folder."""
    for d in ai_model_dirs():
        pb, pbtxt = os.path.join(d, AIDetector.PB), os.path.join(d, AIDetector.PBTXT)
        if os.path.isfile(pb) and os.path.isfile(pbtxt):
            return pb, pbtxt
    return None, None


def _short_net_err(e):
    """A short, readable reason for a failed download."""
    r = getattr(e, "reason", None) or e
    t = str(r)
    if "CERTIFICATE_VERIFY_FAILED" in t:
        return "certificate not valid (check the clock of the Pi)" if "expired" in t or "not yet valid" in t else "certificate not valid"
    if isinstance(r, TimeoutError) or "timed out" in t:
        return "no answer (internet slow or missing)"
    if "Name or service not known" in t or "getaddrinfo" in t or "Temporary failure in name resolution" in t:
        return "no internet (name not found)"
    if "Connection refused" in t or "Network is unreachable" in t:
        return "no internet connection"
    if getattr(e, "code", None):
        return f"server answered {e.code}"
    return t[:80]


def ai_model_download():
    """Fetch the AI model in the background (about 70 MB), check that OpenCV can read it, switch the AI on."""
    if AI_MODEL["busy"]:
        return False, "already running"
    if DEMO["on"]:
        return False, "not in the demo"
    AI_MODEL.update(busy=True, msg="downloading", pct=0)

    def run():
        import tarfile
        dst = os.path.join(DATA_DIR, "models"); os.makedirs(dst, exist_ok=True)
        tgz = os.path.join(dst, "model.tar.gz.part"); pb_tmp = os.path.join(dst, AIDetector.PB + ".part"); tx_tmp = os.path.join(dst, AIDetector.PBTXT + ".part")
        try:
            errs = []
            for url in AI_TGZ_URLS:                               # first address that works (certificates are always checked)
                try:
                    req = urllib.request.Request(url, headers={"User-Agent": "MotionWatch/" + APP_VERSION})
                    with urllib.request.urlopen(req, timeout=60) as r, open(tgz, "wb") as f:
                        total = int(r.headers.get("Content-Length") or 0); got = 0
                        while True:
                            b = r.read(256 * 1024)
                            if not b:
                                break
                            f.write(b); got += len(b)
                            AI_MODEL["pct"] = int(got * 90 / total) if total else min(89, got // (800 * 1024))
                    errs = []; break
                except Exception as e:
                    errs.append(_short_net_err(e))
            if errs:
                raise RuntimeError(errs[0])
            with tarfile.open(tgz, "r:gz") as t:                 # only the one file, written by us (no paths from the archive)
                m = next((x for x in t.getmembers() if x.isfile() and x.name.endswith("/" + AIDetector.PB)), None)
                if m is None:
                    raise RuntimeError("model file missing in the archive")
                src = t.extractfile(m)
                with open(pb_tmp, "wb") as f:
                    shutil.copyfileobj(src, f)
            req = urllib.request.Request(AI_PBTXT_URL, headers={"User-Agent": "MotionWatch/" + APP_VERSION})
            with urllib.request.urlopen(req, timeout=60) as r:
                txt = r.read(5 * 1024 * 1024)
            if b"node" not in txt[:4096]:
                raise RuntimeError("the description file is not valid")
            with open(tx_tmp, "wb") as f:
                f.write(txt)
            AI_MODEL["pct"] = 95
            try:
                cv2.dnn.readNetFromTensorflow(pb_tmp, tx_tmp)    # raises if the files are damaged
            except cv2.error:
                raise RuntimeError("the model files are damaged - try again")
            os.replace(pb_tmp, os.path.join(dst, AIDetector.PB)); os.replace(tx_tmp, os.path.join(dst, AIDetector.PBTXT))
            CFG["ai_enabled"] = True; save_settings()
            w = WATCH_REF["w"]
            if w is not None:
                w.ai = AIDetector()
            AI_MODEL.update(msg="ready", pct=100)
            log_event("ai", "AI model downloaded and switched on")
        except Exception as e:
            AI_MODEL.update(msg=f"failed: {tr(str(e))}"[:120], pct=0)
            log_event("ai", f"AI model download failed: {e}"[:200])
        finally:
            AI_MODEL["busy"] = False
            for p_ in (tgz, pb_tmp, tx_tmp):
                try:
                    os.remove(p_)
                except OSError:
                    pass
    threading.Thread(target=run, daemon=True, name="ai-model").start()
    return True, ""


# ----------------------------------------------------------------------------
# Animal species: a second AI model (image classifier, ONNX) looks at the animals the first AI finds (COCO only knows
#   "dog", "cat", "bear" ... - a fox is often a "dog"). Files: <data>/models/species/<name>.onnx and <name>.txt with one
#   label per line in the order of the model's outputs, optionally "english;Deutsch" (e.g. "red fox;Fuchs").
# ----------------------------------------------------------------------------
SPECIES = {"net": None, "model": "", "labels": set(), "names": [], "msg": "off", "cache": [], "busy": False, "t": 0.0, "last": None}


def species_dir():
    return os.path.join(DATA_DIR, "models", "species")


def species_models():
    try:
        return sorted(f for f in os.listdir(species_dir()) if f.lower().endswith(".onnx") and REC_NAME_RE.match(f))[:20]
    except OSError:
        return []


def species_load():
    m = str(CFG["species_model"] or "")
    if SPECIES["model"] == m and (SPECIES["net"] is not None or not m):
        return SPECIES["net"]
    SPECIES.update(net=None, model=m, names=[], cache=[])
    if not m:
        SPECIES["msg"] = "no model chosen"; return None
    path = os.path.join(species_dir(), m)
    try:
        net = cv2.dnn.readNetFromONNX(path)
        with open(os.path.splitext(path)[0] + ".txt", encoding="utf-8") as f:
            rows = [ln.strip() for ln in f if ln.strip()]
    except (cv2.error, OSError) as e:
        SPECIES["msg"] = f"load error: {e}"[:120]; log_event("ai", f"Animal species model: {SPECIES['msg']}"); return None
    names = []
    for r in rows:
        en, _, de = r.partition(";")
        en = en.strip()[:40]; names.append(en)
        if de.strip():
            DE.setdefault(en, de.strip()[:40])
    SPECIES.update(net=net, names=names, labels=set(names), msg=f"ready · {len(names)} species")
    log_event("ai", f"Animal species model {m} loaded ({len(names)} species)")
    return net


def species_classify(crop):
    """(label, certainty) for one picture of an animal, or None."""
    net = species_load()
    if net is None or crop is None or crop.size == 0:
        return None
    n = int(CFG["species_size"]); img = cv2.cvtColor(cv2.resize(crop, (n, n), interpolation=cv2.INTER_AREA), cv2.COLOR_BGR2RGB).astype(np.float32) / 255.0
    mode = CFG["species_norm"]
    if mode == "imagenet":
        img = (img - np.array([0.485, 0.456, 0.406], np.float32)) / np.array([0.229, 0.224, 0.225], np.float32)
    elif mode == "-11":
        img = img * 2.0 - 1.0
    net.setInput(img.transpose(2, 0, 1)[None])
    out = net.forward().reshape(-1).astype(np.float64)
    if out.size != len(SPECIES["names"]):
        SPECIES["msg"] = f"the label file has {len(SPECIES['names'])} lines, the model {out.size} outputs"; return None
    if out.min() < 0 or abs(out.sum() - 1.0) > 0.01:          # raw scores -> probabilities
        e = np.exp(out - out.max()); out = e / e.sum()
    i = int(out.argmax())
    return SPECIES["names"][i], float(out[i])


def species_update(objs, frame, pw, ph, t0):
    """Called by the camera loop: the biggest animal is classified in the background (at most every 2 s)."""
    SPECIES["cache"] = [c for c in SPECIES["cache"] if t0 - c[3] < 6]
    if not CFG["species_on"] or not CFG["species_model"] or SPECIES["busy"] or t0 - SPECIES["t"] < 2.0:
        return
    an = [o for o in objs if COCO_LABELS.get(o[5]) in ANIMALS]
    if not an:
        return
    o = max(an, key=lambda b: b[2] * b[3]); H, W = frame.shape[:2]; sx, sy = W / float(pw), H / float(ph)
    x, y, w, h = o[0] * sx, o[1] * sy, o[2] * sx, o[3] * sy
    m = 0.15
    crop = frame[max(0, int(y - h * m)):min(H, int(y + h * (1 + m))), max(0, int(x - w * m)):min(W, int(x + w * (1 + m)))].copy()
    SPECIES["busy"] = True; SPECIES["t"] = t0

    def run():
        try:
            r = species_classify(crop)
            if r and r[1] >= float(CFG["species_conf"]):
                SPECIES["cache"].append((o[:4], r[0], r[1], time.time()))
                if not SPECIES["last"] or SPECIES["last"][0] != r[0] or time.time() - SPECIES["last"][2] > 60:
                    log_event("ai", f"Animal species: {r[0]} {int(r[1] * 100)} % (first AI: {COCO_LABELS.get(o[5])})")
                SPECIES["last"] = (r[0], r[1], time.time())
        except Exception as e:
            SPECIES["msg"] = f"error: {e}"[:120]
        finally:
            SPECIES["busy"] = False
    threading.Thread(target=run, daemon=True, name="species").start()


def species_for(box):
    """The species found for a box of the first AI (overlap), or None."""
    best = None
    for b, lab, conf, _t in SPECIES["cache"]:
        if iou(box, b) > 0.3 and (best is None or conf > best[1]):
            best = (lab, conf)
    return best


def species_install(url):
    """Download a model (.onnx, its labels .txt next to it - or a .zip with both) into the species folder."""
    if not (isinstance(url, str) and re.match(r"^https://[^\s]{4,400}$", url)):
        return False, "address must start with https://"
    os.makedirs(species_dir(), exist_ok=True)
    name = re.sub(r"[^A-Za-z0-9_.\-]", "_", url.rsplit("/", 1)[-1].split("?")[0])[:80] or "model.onnx"

    def get(u, dst, limit=400 * 1024 * 1024):
        req = urllib.request.Request(u, headers={"User-Agent": "MotionWatch/" + APP_VERSION})
        with urllib.request.urlopen(req, timeout=60) as r, open(dst + ".part", "wb") as f:
            n = 0
            for chunk in iter(lambda: r.read(1 << 20), b""):
                n += len(chunk)
                if n > limit:
                    raise ValueError("file too big")
                f.write(chunk)
        os.replace(dst + ".part", dst)
    try:
        if name.lower().endswith(".zip"):
            tmp = os.path.join(species_dir(), name); get(url, tmp)
            with zipfile.ZipFile(tmp) as z:
                for zi in z.infolist():
                    bn = os.path.basename(zi.filename)
                    if bn.lower().endswith((".onnx", ".txt")) and REC_NAME_RE.match(bn):
                        with z.open(zi) as src, open(os.path.join(species_dir(), bn), "wb") as dst:
                            shutil.copyfileobj(src, dst)
            os.remove(tmp)
        elif name.lower().endswith(".onnx"):
            get(url, os.path.join(species_dir(), name))
            try:
                get(url[:url.lower().rfind(".onnx")] + ".txt", os.path.join(species_dir(), name[:-5] + ".txt"), 2 * 1024 * 1024)
            except Exception:
                pass
        else:
            return False, "the address must end with .onnx or .zip"
    except Exception as e:
        return False, _short_net_err(e) if "_short_net_err" in globals() else str(e)[:120]
    ms = species_models()
    if ms and not CFG["species_model"]:
        CFG["species_model"] = ms[0]; save_settings()
    log_event("ai", f"Animal species model installed from {url[:80]}")
    return True, ""


# ---- Alarm-Rückblick (2.95.53): about twice a second, while somebody / an animal is in the picture, where the head looked and
# where in the picture each one was. Round an alarm (15 s before, 20 s after) this is kept as a track - the 3D simulator plays
# it back (Simulator → Alarm-Rückblick). Small: a few kB per alarm, the last 30 are kept. ----
TRACKLOG = deque(maxlen=400)
ALARM_TRACKS = deque(maxlen=30)
_ATR = {"open": None, "t": 0.0, "loaded": False}


def _atr_file():
    return os.path.join(DATA_DIR, "alarm_tracks.json")


def alarm_tracks_load():
    if _ATR["loaded"]:
        return
    _ATR["loaded"] = True
    try:
        with open(_atr_file()) as f:
            for t in json.load(f)[-30:]:
                if isinstance(t, dict) and isinstance(t.get("samples"), list):
                    ALARM_TRACKS.append(t)
    except (OSError, ValueError):
        pass


def _atr_save():
    try:
        tmp = _atr_file() + ".tmp"
        with open(tmp, "w") as f:
            json.dump(list(ALARM_TRACKS), f)
        os.replace(tmp, _atr_file())
    except OSError:
        pass


def alarm_track_sample(persons, animals, pw, ph):
    """from the detection loop: persons = tracks (t.box), animals = AI objects (x, y, w, h, conf, cls)"""
    now = time.time()
    if now - _ATR["t"] < 0.45 or (not persons and not animals):
        return
    _ATR["t"] = now
    hp, ht = servo_half("pan"), servo_half("tilt")
    objs = []
    for t in persons[:6]:
        x, y, w, h = t.box[:4]
        objs.append({"k": "person", "x": round((x + w / 2.0) / pw, 3), "y": round((y + h / 2.0) / ph, 3), "h": round(h / ph, 3)})
    for o in animals[:4]:
        x, y, w, h = o[:4]
        objs.append({"k": COCO_LABELS.get(o[5], "animal"), "x": round((x + w / 2.0) / pw, 3), "y": round((y + h / 2.0) / ph, 3), "h": round(h / ph, 3)})
    smp = {"t": round(now, 2), "pan": round((CFG["pan"] - 50) / 50 * hp, 1), "tilt": round((CFG["tilt"] - 50) / 50 * ht, 1), "objs": objs}
    TRACKLOG.append(smp)
    o_ = _ATR["open"]
    if o_ is not None:
        if now < o_["until"]:
            o_["samples"].append(smp)
        else:
            _ATR["open"] = None
            _atr_save()


def alarm_track_begin(kind, stamp, snap=None):
    """an alarm: keep the last 15 s and the next 20 s"""
    alarm_tracks_load()
    now = time.time()
    if _ATR["open"] is not None and now < _ATR["open"]["until"]:
        _ATR["open"]["until"] = now + 20.0
        return
    tr_ = {"id": stamp, "t": now, "kind": kind, "snap": os.path.basename(snap) if snap else "", "sim": bool(CFG.get("sim_on")),
           "samples": [s_ for s_ in TRACKLOG if now - s_["t"] <= 15.0], "until": now + 20.0}
    ALARM_TRACKS.append(tr_)
    _ATR["open"] = tr_


def alarm_tracks_list():
    alarm_tracks_load()
    out = []
    for t in list(ALARM_TRACKS)[::-1]:
        sm = t.get("samples") or []
        out.append({"id": t["id"], "t": t["t"], "kind": t.get("kind", "person"), "n": len(sm), "sec": round(sm[-1]["t"] - sm[0]["t"], 1) if len(sm) > 1 else 0,
                    "sim": t.get("sim", False)})
    return out


# ---- AI helper (2.95.53): a PC in the same network does the AI for the Pi. The simulator starts MoveEye on the PC with
# --helper; the Pi finds it through the simulator (address + pairing code) or by hand. The Pi sends a small picture, the PC
# answers with the boxes. No answer -> the Pi does it itself again. Only pictures go to the PC, nothing is stored there. ----
HELPER_PORT = 5057
HELPER = {"url": "", "code": "", "src": "", "ok": False, "ms": 0, "rtt": 0, "n": 0, "fails": 0, "next_try": 0.0, "msg": "",
          "busy": False, "res": None, "res_t": 0.0, "name": "", "last_ok": 0.0, "served": 0, "serve_ms": 0, "serve_from": ""}
HELPER_LOCK = threading.Lock()


def helper_target():
    if CFG.get("helper_url"):
        return CFG["helper_url"].rstrip("/"), CFG.get("helper_code") or "", "manual"
    if HELPER.get("auto_url"):
        return HELPER["auto_url"], HELPER.get("auto_code") or "", "simulator"
    return "", "", ""


def helper_ready():
    if not CFG.get("helper_use") or DEMO["on"]:
        return False
    u, _c, _s = helper_target()
    return bool(u) and HELPER["ok"]


def _helper_post(url, code, jpg, conf, oconf, timeout=2.5):
    rq = urllib.request.Request(url + f"/helper/detect?conf={conf:.2f}&oconf={oconf:.2f}", data=jpg, method="POST",
                                headers={"Content-Type": "image/jpeg", "X-Helper-Code": code, "User-Agent": "MotionWatch"})
    with _SIM_OPENER.open(rq, timeout=timeout) as r:
        return json.loads(r.read(200000))


def helper_detect(frame):
    """send the picture in the background, return the newest answer (boxes in the coordinates of this picture)"""
    u, code, _src = helper_target()
    if not u:
        return None
    if not HELPER["busy"]:
        h, w = frame.shape[:2]
        sc = min(1.0, 640.0 / max(1, w))
        small = cv2.resize(frame, (int(w * sc), int(h * sc))) if sc < 1.0 else frame
        ok, buf = cv2.imencode(".jpg", small, [cv2.IMWRITE_JPEG_QUALITY, 80])
        if ok:
            HELPER["busy"] = True

            def work(jpg=buf.tobytes(), sc=sc, u=u, code=code):
                t0 = time.time()
                try:
                    d = _helper_post(u, code, jpg, float(CFG["ai_conf"]), float(CFG["object_conf"]))
                    if not d.get("ok"):
                        raise ValueError(str(d.get("error") or "no answer"))
                    k = 1.0 / sc
                    boxes = [(int(b[0] * k), int(b[1] * k), int(b[2] * k), int(b[3] * k), float(b[4])) for b in d.get("boxes", [])]
                    objs = [(int(b[0] * k), int(b[1] * k), int(b[2] * k), int(b[3] * k), float(b[4]), int(b[5])) for b in d.get("objects", [])]
                    HELPER.update(res=(boxes, objs), res_t=time.time(), ms=int(d.get("ms") or 0), rtt=int((time.time() - t0) * 1000),
                                  n=HELPER["n"] + 1, fails=0, last_ok=time.time(), msg="")
                except Exception as e:
                    HELPER["fails"] += 1; HELPER["msg"] = str(e)[:80]
                    if HELPER["fails"] >= 3:
                        HELPER.update(ok=False, next_try=time.time() + 30, res=None)
                        log_event("ai", "AI helper not reachable - the Pi does the AI itself again")
                finally:
                    HELPER["busy"] = False
            threading.Thread(target=work, daemon=True, name="aihelper").start()
    if HELPER["res"] is not None and time.time() - HELPER["res_t"] < 3.0:
        return HELPER["res"]
    return None if time.time() - HELPER["last_ok"] > 3.0 else HELPER["res"]


def helper_tick():
    """every 10 s: find the helper through the simulator, check it (hello) - from the health thread"""
    if DEMO["on"]:
        return
    prev_ = TUN.get("prev_url") or CFG.get("tunnel_prev_url") or ""
    if (CFG["sim_url"].startswith("http://127.0.0.1:18765") and prev_ and time.time() - (TUN["last"] or START) > 180):
        CFG["sim_url"] = prev_; TUN["prev_url"] = ""; CFG["tunnel_prev_url"] = ""; save_settings()   # 2.95.55: also after a restart      # 2.95.54: the tunnel is gone - the old address again
        log_event("sys", "Tunnel of the simulator gone for 3 minutes - back to the normal address")
    _tun_reclaim()
    if CFG.get("sim_on") and not CFG.get("helper_url"):
        hi = None
        if not HELPER["ok"] or time.time() - HELPER.get("info_t", 0) > 60:
            try:
                hi = json.loads(_sim_get("/info", 3.0)[0]).get("helper"); HELPER["info_t"] = time.time()
            except Exception:
                hi = None
        if isinstance(hi, dict) and hi.get("port"):
            host = re.sub(r"^https?://", "", sim_base()).split("/")[0].rsplit(":", 1)[0]
            port = int(hi["port"])
            if sim_base().startswith("http://127.0.0.1:18765"):
                port = 15057                                # 2.95.54: the simulator came through the tunnel - the helper too
            HELPER["auto_url"] = f"http://{host}:{port}"; HELPER["auto_code"] = str(hi.get("code") or "")
    u, code, src = helper_target()
    HELPER["src"] = src
    if not u or not CFG.get("helper_use"):
        if HELPER["ok"]:
            HELPER["ok"] = False
        return
    if HELPER["ok"] and time.time() - HELPER["last_ok"] < 20:
        return
    if time.time() < HELPER["next_try"]:
        return
    try:
        with _SIM_OPENER.open(urllib.request.Request(u + "/helper/hello", headers={"X-Helper-Code": code, "User-Agent": "MotionWatch"}), timeout=3) as r:
            d = json.loads(r.read(20000))
        if not d.get("helper"):
            raise ValueError("not a MoveEye helper")
        if not d.get("paired"):
            raise ValueError("pairing code wrong")
        if not d.get("model"):
            raise ValueError("the PC is still loading its AI model")
        was = HELPER["ok"]
        HELPER.update(ok=True, fails=0, msg="", name=str(d.get("name") or "")[:40], last_ok=time.time(), gpu=str(d.get("accel") or ""),
                      model=str(d.get("model_name") or "")[:40])
        if not was:
            log_event("ai", f"AI helper found: {HELPER['name']} ({u}) - the PC does the AI now")
    except Exception as e:
        HELPER.update(ok=False, msg=str(e)[:80], next_try=time.time() + 20)


def helper_state():
    u, code, src = helper_target()
    return {"use": bool(CFG.get("helper_use")), "url": u, "src": src, "ok": HELPER["ok"], "name": HELPER["name"], "ms": HELPER["ms"],
            "rtt": HELPER["rtt"], "n": HELPER["n"], "msg": HELPER["msg"], "manual_url": CFG.get("helper_url") or "",
            "serve": bool(CFG.get("helper_serve")), "my_code": CFG.get("helper_my_code") if CFG.get("helper_serve") else "",
            "served": HELPER["served"], "serve_ms": HELPER["serve_ms"], "serve_from": HELPER["serve_from"], "accel": HELPER.get("gpu", ""),
            "model": HELPER.get("model", ""), "serve_model": helper_model_name() if CFG.get("helper_serve") else ""}


# ---- KI-Prüfung mit Simulator-Bildern (2.95.53): the 3D simulator makes pictures with a person or an animal (day, dusk,
# night with infrared, rain, fog; near and far) and knows where it is. MoveEye runs its AI (or the PC helper) on each and
# counts what it found, what it missed and false persons. The pictures can be downloaded as training pictures (ZIP). ----
DSET = {"busy": False, "msg": "", "pct": 0, "res": [], "sum": None, "imgs": {}, "t": 0.0}
DSET_ANIMALS = {"bird", "cat", "dog", "horse", "sheep", "cow", "elephant", "bear", "zebra", "giraffe", "animal"}


def _iou(a, b):
    ax, ay, aw, ah = a; bx, by, bw, bh = b
    ix = max(0.0, min(ax + aw, bx + bw) - max(ax, bx)); iy = max(0.0, min(ay + ah, by + bh) - max(ay, by))
    inter = ix * iy
    return inter / max(1e-6, aw * ah + bw * bh - inter)


def _dset_detect(jpg):
    """the AI on one picture: the PC helper if there is one, else here"""
    if helper_ready():
        u, code, _s = helper_target()
        d = _helper_post(u, code, jpg, float(CFG["ai_conf"]), float(CFG["object_conf"]), timeout=6.0)
        if d.get("ok"):
            return d, "PC"
    ai = getattr(WATCH_REF.get("w"), "ai", None)
    if ai is not None and ai.kind == "yolo" and ai.net is not None:     # part 195: the own model is checked, not the standard
        img = cv2.imdecode(np.frombuffer(jpg, np.uint8), cv2.IMREAD_COLOR); t0 = time.time()
        bx, ob = ai.infer(img, float(CFG["ai_conf"]), float(CFG["object_conf"]))
        return {"ok": True, "boxes": [list(b) for b in bx], "objects": [list(o) for o in ob], "ms": int((time.time() - t0) * 1000)}, "Pi · " + tr("Own (MoveEye model)")
    return helper_run(jpg, float(CFG["ai_conf"]), float(CFG["object_conf"])), "Pi"


def dset_run(n):
    if DSET["busy"]:
        return False, "already running"
    if not helper_ready() and not ai_model_paths()[0] and getattr(getattr(WATCH_REF.get("w"), "ai", None), "kind", "") != "yolo":
        return False, "no AI model - load it in the AI settings first (or use the PC helper)"
    DSET.update(busy=True, msg="the simulator makes the pictures …", pct=0, res=[], sum=None, imgs={}, t=time.time())

    def work():
        try:
            if n == "game":                                  # 2.95.75: the pictures the game collected (MoveEye missed the player)
                r = sim_control({"action": "dataset", "op": "game"})
                if not isinstance(r, dict) or not r.get("ok"):
                    raise ValueError("not supported - update the simulator")
                if int(r.get("total") or 0) <= 0:
                    raise ValueError("no missed pictures from the game yet - play a round with MoveEye first")
            else:
                r = sim_control({"action": "dataset", "op": "start", "n": int(n)})
            if not isinstance(r, dict) or not r.get("ok"):
                raise ValueError("not supported - update the simulator")
            t0 = time.time()
            while n != "game" and time.time() - t0 < 900:
                time.sleep(2.0)
                g = sim_control({"action": "dataset", "op": "get"})
                DSET["pct"] = int(60 * int(g.get("done", 0)) / max(1, int(g.get("total", n))))
                DSET["msg"] = "simulator: " + str(g.get("msg") or "")
                if not g.get("busy"):
                    break
            items = (sim_control({"action": "dataset", "op": "list"}) or {}).get("items") or []
            res = []
            for k_, it in enumerate(items):
                jpg, _h = _sim_get(f"/dataset/{int(it['i'])}.jpg", 8.0)
                DSET["imgs"][int(it["i"])] = jpg
                d, where = _dset_detect(jpg)
                img = cv2.imdecode(np.frombuffer(jpg, np.uint8), cv2.IMREAD_COLOR)
                h, w = img.shape[:2]
                tb = [float(x) for x in it["box"]]
                pers = [[b[0] / w, b[1] / h, b[2] / w, b[3] / h, b[4]] for b in d.get("boxes", [])]
                objs = [[o[0] / w, o[1] / h, o[2] / w, o[3] / h, o[4], COCO_LABELS.get(o[5], "?")] for o in d.get("objects", [])]
                kind = str(it["kind"])
                found, as_ = False, ""
                if kind == "person":
                    best = max([(_iou(tb, b[:4]), b) for b in pers], default=(0, None), key=lambda x: x[0])
                    found = best[0] >= 0.25
                    as_ = "person" if found else ""
                else:
                    best = max([(_iou(tb, o[:4]), o) for o in objs if o[5] in DSET_ANIMALS], default=(0, None), key=lambda x: x[0])
                    found = best[0] >= 0.2
                    as_ = best[1][5] if found else ""
                false_p = sum(1 for b in pers if _iou(tb, b[:4]) < 0.1) if kind == "person" else len(pers)   # a person where there is none
                res.append({"i": int(it["i"]), "kind": kind, "cond": it["cond"], "dist": it["dist"], "found": found, "as": as_,
                            "false": int(false_p), "ms": int(d.get("ms") or 0), "where": where, "box": tb})
                DSET["pct"] = 60 + int(40 * (k_ + 1) / max(1, len(items)))
                DSET["msg"] = f"AI checks picture {k_ + 1} of {len(items)}"
            DSET["res"] = res
            def grp(key):
                o = {}
                for r_ in res:
                    g_ = o.setdefault(r_[key], [0, 0])
                    g_[0] += 1; g_[1] += 1 if r_["found"] else 0
                return {k: {"n": v[0], "found": v[1], "pct": int(100 * v[1] / max(1, v[0]))} for k, v in o.items()}
            near = [r_ for r_ in res if r_["dist"] < 8]; far = [r_ for r_ in res if r_["dist"] >= 8]
            DSET["sum"] = {"n": len(res), "found": sum(1 for r_ in res if r_["found"]), "false": sum(r_["false"] for r_ in res),
                           "by_cond": grp("cond"), "by_kind": grp("kind"),
                           "near": int(100 * sum(1 for r_ in near if r_["found"]) / max(1, len(near))), "far": int(100 * sum(1 for r_ in far if r_["found"]) / max(1, len(far))),
                           "ms": int(sum(r_["ms"] for r_ in res) / max(1, len(res))), "where": res[0]["where"] if res else ""}
            DSET["msg"] = "done"
            log_event("ai", f"AI test with simulator pictures: {DSET['sum']['found']} of {len(res)} found, {DSET['sum']['false']} false persons")
        except Exception as e:
            DSET["msg"] = "error: " + str(e)[:120]
        finally:
            DSET["busy"] = False; DSET["pct"] = 100 if DSET["sum"] else DSET["pct"]
    threading.Thread(target=work, daemon=True, name="dset").start()
    return True, ""


def dset_zip():
    """the pictures with their boxes for training (YOLO format: class x_center y_center width height, 0..1)"""
    import io
    bio = io.BytesIO()
    cls = {"person": 0}
    with zipfile.ZipFile(bio, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("README.txt", "MoveEye - training pictures from the 3D simulator\nimages/*.jpg + labels/*.txt (YOLO: class cx cy w h, 0..1)\n"
                   "classes: 0 person, 1 animal\nmeta.json: kind, condition, distance, found by the AI\n")
        meta = []
        for r_ in DSET["res"]:
            jpg = DSET["imgs"].get(r_["i"])
            if not jpg:
                continue
            nm = f"sim_{r_['i']:03d}"
            z.writestr(f"images/{nm}.jpg", jpg)
            x, y, w, h = r_["box"]
            z.writestr(f"labels/{nm}.txt", f"{cls.get(r_['kind'], 1)} {x + w / 2:.4f} {y + h / 2:.4f} {w:.4f} {h:.4f}\n")
            meta.append(dict(r_, file=nm + ".jpg"))
        z.writestr("meta.json", json.dumps(meta, indent=1))
    return bio.getvalue()


def dset_state():
    return dict({k: DSET[k] for k in ("busy", "msg", "pct", "sum")}, res=DSET["res"][-80:])


# ---- Tunnel (2.95.54): a simulator behind a firewall that lets nothing in (a PC / virtual machine without admin rights)
# connects OUT to the Pi (port 8766) and keeps a few connections open. MoveEye then talks to it through them as if it
# ran here: 127.0.0.1:18765 = the simulator, 127.0.0.1:15057 = the AI helper on that PC. Paired with a 6-digit code. ----
import socket as _socket
TUN_PORT = 8766
TUN_LOCAL = {18765: 8765, 15057: 5057}
TUN = {"pool": deque(), "lock": threading.Lock(), "last": 0.0, "peer": "", "srv": False, "open": 0, "prev_url": "", "bytes": 0,
       "listen": "", "try": None}


def tunnel_code():
    if not CFG.get("tunnel_code"):
        CFG["tunnel_code"] = "%06d" % secrets.randbelow(1000000); save_settings()
    return CFG["tunnel_code"]


def tunnel_active():
    return time.time() - TUN["last"] < 45 and len(TUN["pool"]) + TUN["open"] > 0


def _tun_pipe(a, b):
    def one(x, y):
        try:
            while True:
                d_ = x.recv(65536)
                if not d_:
                    break
                y.sendall(d_); TUN["bytes"] += len(d_)
        except OSError:
            pass
        finally:
            for z in (x, y):
                try:
                    z.shutdown(_socket.SHUT_RDWR)
                except OSError:
                    pass
    TUN["open"] += 1
    TUN.setdefault("pipes", set()).add(b)                # 2.98.26: the simulator side, to close it when a newer simulator comes
    t1 = threading.Thread(target=one, args=(a, b), daemon=True); t2 = threading.Thread(target=one, args=(b, a), daemon=True)
    t1.start(); t2.start()

    def done():
        t1.join(); t2.join()
        TUN["open"] -= 1
        TUN.get("pipes", set()).discard(b)
        for z in (a, b):
            try:
                z.close()
            except OSError:
                pass
    threading.Thread(target=done, daemon=True).start()


TUN_MAX_AGE = 100.0               # 2.95.101: an idle connection older than this is dead (a router forgot it); the simulator renews its own


def _tun_take():
    """an idle connection of the simulator (dead ones are dropped). 2.95.101: the newest first - the old ones are the ones a
    router may have forgotten, and the simulator (3D-3.75) renews them after 40-55 s anyway"""
    import select
    t0 = time.time()
    while time.time() - t0 < 4.0:
        with TUN["lock"]:
            ct = TUN["pool"].pop() if TUN["pool"] else None
        if ct is None:
            time.sleep(0.1); continue
        c, born = ct
        if time.time() - born > TUN_MAX_AGE:
            try:
                c.close()
            except OSError:
                pass
            continue
        try:
            r, _w, _x = select.select([c], [], [], 0)
            if r and not c.recv(1, _socket.MSG_PEEK):
                c.close(); continue                      # closed by the simulator
        except OSError:
            continue
        return c
    return None


def _tun_instance_ok(inst, peer):
    """2.98.26 (Daniel: «das Bild springt zwischen zwei Ansichten»): two simulator windows were open (an old one after an update,
    or started twice) and both sent their lines - MoveEye took lines of both, so the picture jumped between the two. Each
    simulator (3D-4.8) names itself «start time-process»: the newest one wins, the lines of the older one are refused."""
    try:
        t_new = int(str(inst).split("-")[0])
    except ValueError:
        return True
    cur = TUN.get("inst") or ""
    if inst == cur:
        return True
    try:
        t_cur = int(cur.split("-")[0]) if cur else 0
    except ValueError:
        t_cur = 0
    if t_new >= t_cur:
        if cur:
            TUN["dupe"] = {"t": time.time(), "peer": peer}
            log_event("sys", f"Tunnel: a newer simulator window connected ({peer}) - the lines of the older one are closed. "
                             "Two simulators were open: close the old window.")
            TUN["inst"] = inst
            tunnel_flush()
            for z in list(TUN.get("pipes", ())):        # running streams of the old window: closed, they reconnect to the new one
                try:
                    z.shutdown(_socket.SHUT_RDWR)
                except OSError:
                    pass
        TUN["inst"] = inst
        return True
    TUN["dupe"] = {"t": time.time(), "peer": peer}
    if time.time() - TUN.get("dupe_log", 0.0) > 600:
        TUN["dupe_log"] = time.time()
        log_event("sys", f"Tunnel: a second, older simulator window ({peer}) is refused - please close it")
    return False


def tunnel_flush():
    """2.98.11: close every idle line of the tunnel. After an update of the simulator on Windows the old lines may stay
    open (the new process inherits them) but nobody answers on them any more: MoveEye waited on them until they were
    100 s old. The simulator opens fresh ones at once."""
    with TUN["lock"]:
        old = list(TUN["pool"]); TUN["pool"].clear()
    for c, _b in old:
        try:
            c.close()
        except OSError:
            pass
    if old:
        log_event("sys", f"Tunnel: {len(old)} old lines closed - the simulator opens new ones")


def tunnel_start():
    """the listener for the simulator (whole network) and the two local doors (only this Pi)"""
    if TUN["srv"] or DEMO["on"]:
        return
    TUN["srv"] = True
    tunnel_code()

    def accept_sim():
        srv = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM); srv.setsockopt(_socket.SOL_SOCKET, _socket.SO_REUSEADDR, 1)
        try:
            srv.bind(("0.0.0.0", TUN_PORT)); srv.listen(32); TUN["listen"] = "ok"
        except OSError as e:
            TUN["listen"] = str(e)[:80]
            log_event("sys", f"Tunnel for the simulator could not start (port {TUN_PORT}): {e}"); return
        while True:
            c, addr = srv.accept()
            try:
                c.settimeout(6.0)
                line = b""
                while not line.endswith(b"\n") and len(line) < 100:
                    ch = c.recv(1)
                    if not ch:
                        break
                    line += ch
                parts = line.decode("ascii", "replace").split()
                good = bool(CFG.get("tunnel_on")) and len(parts) in (2, 3) and parts[0] == "MWTUN1" and secrets.compare_digest(parts[1], tunnel_code())
                if good and len(parts) == 3 and not _tun_instance_ok(parts[2], addr[0]):
                    c.sendall(b"NO\n"); c.close(); continue    # 2.98.26: an older simulator window (two are open) is refused
                if parts and parts[0] == "MWTUN1":           # 2.95.66: only a simulator counts (not the own simulator search)
                    TUN["try"] = {"peer": addr[0], "t": time.time(), "ok": good}     # 2.95.60: shown on the page (wrong code?)
                if not good:
                    c.sendall(b"NO\n"); c.close(); continue
                c.sendall(b"OK\n"); c.settimeout(None)
                c.setsockopt(_socket.SOL_SOCKET, _socket.SO_KEEPALIVE, 1)
                with TUN["lock"]:
                    TUN["pool"].append((c, time.time()))
                    while len(TUN["pool"]) > 12 or (TUN["pool"] and time.time() - TUN["pool"][0][1] > TUN_MAX_AGE):
                        try:
                            TUN["pool"].popleft()[0].close()
                        except OSError:
                            pass
                was = tunnel_active()
                TUN["last"] = time.time(); TUN["peer"] = addr[0]
                if not was:
                    log_event("sys", f"Simulator connected through the tunnel from {addr[0]}")
                    if not CFG["sim_url"].startswith("http://127.0.0.1:18765"):
                        TUN["prev_url"] = CFG["tunnel_prev_url"] = CFG["sim_url"]; CFG["sim_url"] = "http://127.0.0.1:18765"; save_settings()
            except OSError:
                try:
                    c.close()
                except OSError:
                    pass

    def door(lport, rport):
        srv = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM); srv.setsockopt(_socket.SOL_SOCKET, _socket.SO_REUSEADDR, 1)
        try:
            srv.bind(("127.0.0.1", lport)); srv.listen(32)
        except OSError:
            return
        while True:
            cl, _a = srv.accept()
            def handle(cl=cl):
                c = _tun_take()
                if c is None:
                    cl.close(); return
                try:
                    c.sendall(f"GO {rport}\n".encode())
                except OSError:
                    cl.close(); c.close(); return
                TUN["last"] = time.time()
                _tun_pipe(cl, c)
            threading.Thread(target=handle, daemon=True).start()
    threading.Thread(target=accept_sim, daemon=True, name="tunnel").start()
    for lp, rp in TUN_LOCAL.items():
        threading.Thread(target=door, args=(lp, rp), daemon=True, name=f"tunnel{lp}").start()


_TUN_RECLAIM = {"t": 0.0}


def _tun_reclaim():
    """2.95.68: the tunnel runs, but the address was set to the direct one again (automatic search, card tapped) and that one
    does not answer (firewall) - back to the tunnel, otherwise the picture stays black for good"""
    if not tunnel_active() or CFG["sim_url"].startswith("http://127.0.0.1:18765"):
        _TUN_RECLAIM["t"] = 0.0; return
    if SIM["ok"] and time.time() - SIM["t"] < 5:
        _TUN_RECLAIM["t"] = 0.0; return            # the direct address works - leave it
    if not _TUN_RECLAIM["t"]:
        _TUN_RECLAIM["t"] = time.time(); return
    if time.time() - _TUN_RECLAIM["t"] < 8:
        return
    _TUN_RECLAIM["t"] = 0.0
    TUN["prev_url"] = CFG["tunnel_prev_url"] = CFG["sim_url"]; CFG["sim_url"] = "http://127.0.0.1:18765"; save_settings()
    log_event("sys", "Simulator does not answer directly, but the tunnel runs - back to the tunnel")
    w = WATCH_REF.get("w")
    if CFG.get("sim_on") and w is not None and str(CFG["source"]).startswith("sim:"):
        w._open_gen += 1; w._start_opener(CFG["source"])


def tunnel_state():
    from urllib.parse import urlparse
    return {"on": bool(CFG.get("tunnel_on")), "code": tunnel_code() if CFG.get("tunnel_on") else "", "port": TUN_PORT, "active": tunnel_active(),
            "peer": TUN["peer"], "idle": len(TUN["pool"]), "open": TUN["open"], "mb": round(TUN["bytes"] / 1e6, 1),
            "listen": TUN["listen"], "try": ({"peer": TUN["try"]["peer"], "ago": int(time.time() - TUN["try"]["t"]), "ok": TUN["try"]["ok"]} if TUN["try"] else None),
            "sim_port": _tun_direct_port(),
            "dupe": bool(TUN.get("dupe") and time.time() - TUN["dupe"]["t"] < 30)}


def _tun_direct_port():
    """the port MoveEye uses for the simulator without the tunnel (while the tunnel runs: the address from before)"""
    from urllib.parse import urlparse
    u = CFG.get("sim_url") or ""
    if u.startswith("http://127.0.0.1:18765"):
        u = TUN.get("prev_url") or CFG.get("tunnel_prev_url") or ""
    try:
        return int(urlparse(u).port or 8765) if u else 8765
    except ValueError:
        return 8765


# --- the helper side (on the PC) ---
# 2.98.x (KI-Daten aufräumen): the helper uses the own trained MoveEye model (ki_modell.yml, «Eigenes Modell
# herunterladen» on this PC or the two files in <data>/models) when it is there, else the standard model (SSD).
# A newer own model (downloaded later) is picked up by itself (the manifest file is watched).
HELPER_NET = {"net": None, "accel": "CPU", "lock": threading.Lock(), "srv": None, "kind": "ssd", "meta": None, "key": None, "own_why": ""}


def _helper_own_key():
    _o, js = own_ai_paths()
    try:
        return (js, os.path.getmtime(js)) if js else None
    except OSError:
        return None


def _helper_net():
    key = _helper_own_key()
    if HELPER_NET["net"] is not None and key != HELPER_NET["key"]:
        HELPER_NET["net"] = None                          # the own model came, changed or went: load again
    if HELPER_NET["net"] is None:
        net, kind, meta = None, "ssd", None
        if key:
            net, meta, why = own_ai_load()
            HELPER_NET["own_why"] = why
            if net is not None:
                kind = "own"
            else:
                log_event("ai", f"AI helper: own model not used ({why}) - the standard model (SSD) runs")
        if net is None:
            pb, pbtxt = ai_model_paths()
            if not pb:
                if not AI_MODEL["busy"]:
                    ai_model_download()
                return None
            net = cv2.dnn.readNetFromTensorflow(pb, pbtxt)
        try:                                            # a graphics card with CUDA makes it much faster
            if hasattr(cv2, "cuda") and cv2.cuda.getCudaEnabledDeviceCount() > 0:
                net.setPreferableBackend(cv2.dnn.DNN_BACKEND_CUDA); net.setPreferableTarget(cv2.dnn.DNN_TARGET_CUDA)
                HELPER_NET["accel"] = "CUDA"
        except Exception:
            pass
        HELPER_NET.update(net=net, kind=kind, meta=meta, key=key)
        log_event("ai", "AI helper uses " + (own_ai_name(meta) if kind == "own" else "SSD MobileNet V2"))
    return HELPER_NET["net"]


def helper_model_name():
    """which model the helper on this PC uses (or would use)"""
    if HELPER_NET["net"] is not None:
        return own_ai_name(HELPER_NET["meta"]) if HELPER_NET["kind"] == "own" else "SSD MobileNet V2"
    return "MoveEye model" if own_ai_paths()[0] else ("SSD MobileNet V2" if ai_model_paths()[0] else "")


def helper_run(jpg, conf, oconf):
    img = cv2.imdecode(np.frombuffer(jpg, np.uint8), cv2.IMREAD_COLOR)
    if img is None:
        raise ValueError("no picture")
    net = _helper_net()
    if net is None:
        raise ValueError("AI model is loading")
    t0 = time.time()
    h, w = img.shape[:2]
    boxes, objects = [], []
    if HELPER_NET["kind"] == "own":                   # the own YOLO model: same answer as SSD (classes mapped to COCO ids)
        with HELPER_NET["lock"]:
            pb_, ob_ = own_ai_detect(net, HELPER_NET["meta"], img, conf, oconf)
        boxes = [[int(b[0]), int(b[1]), int(b[2]), int(b[3]), round(float(b[4]), 3)] for b in pb_]
        objects = [[int(o[0]), int(o[1]), int(o[2]), int(o[3]), round(float(o[4]), 3), int(o[5])] for o in ob_]
    else:
        with HELPER_NET["lock"]:
            net.setInput(cv2.dnn.blobFromImage(img, size=(300, 300), swapRB=True, crop=False))
            det = net.forward()
        for i in range(det.shape[2]):
            cls, cf = int(det[0, 0, i, 1]), float(det[0, 0, i, 2])
            if cls < 1 or cf < (conf if cls == 1 else oconf):
                continue
            x1, y1, x2, y2 = (det[0, 0, i, 3:7] * np.array([w, h, w, h])).astype(int)
            x1, y1 = max(0, x1), max(0, y1); x2, y2 = min(w - 1, x2), min(h - 1, y2)
            if x2 > x1 and y2 > y1:
                (boxes.append([int(x1), int(y1), int(x2 - x1), int(y2 - y1), round(cf, 3)]) if cls == 1
                 else objects.append([int(x1), int(y1), int(x2 - x1), int(y2 - y1), round(cf, 3), cls]))
    ms = int((time.time() - t0) * 1000)
    HELPER["served"] += 1; HELPER["serve_ms"] = ms
    return {"ok": True, "boxes": boxes, "objects": objects, "ms": ms, "model": helper_model_name()}


def helper_server_start():
    """a small separate web server for the helper (port 5057, whole network) - the page of MoveEye on the PC stays local"""
    if HELPER_NET["srv"] is not None:
        return
    if not CFG.get("helper_my_code"):
        CFG["helper_my_code"] = "%06d" % secrets.randbelow(1000000); save_settings()
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

    class H(BaseHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def _js(self, obj, code=200):
            b = json.dumps(obj).encode()
            self.send_response(code); self.send_header("Content-Type", "application/json"); self.send_header("Content-Length", str(len(b)))
            self.end_headers(); self.wfile.write(b)

        def _paired(self):
            return secrets.compare_digest(str(self.headers.get("X-Helper-Code") or ""), str(CFG.get("helper_my_code") or "x"))

        def do_GET(self):
            if self.path.startswith("/helper/hello"):
                local = self.client_address[0] in ("127.0.0.1", "::1")
                d = {"helper": 1, "name": CFG.get("device_name") or __import__("socket").gethostname(), "ver": APP_VERSION, "paired": self._paired(),
                     "model": bool(ai_model_paths()[0] or own_ai_paths()[0]), "model_name": helper_model_name(), "accel": HELPER_NET["accel"], "served": HELPER["served"], "ms": HELPER["serve_ms"]}
                if local:                                   # the simulator on this PC passes the code on to the Pi
                    d.update(code=CFG.get("helper_my_code"), port=HELPER_PORT, loading=AI_MODEL.get("busy"), pct=AI_MODEL.get("pct"))
                    if not ai_model_paths()[0] and not own_ai_paths()[0] and not AI_MODEL["busy"]:
                        ai_model_download()
                return self._js(d)
            self._js({"error": "not found"}, 404)

        def do_POST(self):
            if not self.path.startswith("/helper/detect"):
                return self._js({"error": "not found"}, 404)
            if not self._paired():
                return self._js({"ok": False, "error": "pairing code wrong"}, 403)
            n = int(self.headers.get("Content-Length") or 0)
            if n <= 0 or n > 3 << 20:
                return self._js({"ok": False, "error": "picture too big"}, 413)
            jpg = self.rfile.read(n)
            q = dict(x.split("=", 1) for x in (self.path.split("?", 1)[1].split("&") if "?" in self.path else []) if "=" in x)
            try:
                HELPER["serve_from"] = self.client_address[0]
                res = helper_run(jpg, float(q.get("conf", 0.5)), float(q.get("oconf", 0.5)))
            except Exception as e:
                return self._js({"ok": False, "error": str(e)[:80]}, 503)
            self._js(res)

    try:
        srv = ThreadingHTTPServer(("0.0.0.0", HELPER_PORT), H)
    except OSError as e:
        log_event("ai", f"AI helper could not start (port {HELPER_PORT}): {e}")
        return
    srv.daemon_threads = True
    HELPER_NET["srv"] = srv
    threading.Thread(target=srv.serve_forever, daemon=True, name="helpersrv").start()
    log_event("ai", f"AI helper for other MoveEye ready (port {HELPER_PORT}, pairing code {CFG['helper_my_code']})")


class AIDetector:
    PB, PBTXT = "frozen_inference_graph.pb", "ssd_mobilenet_v2_coco.pbtxt"

    def __init__(self, force_ssd=False):
        self.net = None
        self.kind = "ssd"        # "ssd" or "yolo" (own MoveEye model, part 195)
        self.meta = None         # manifest of the own model
        self.boxes = []          # last persons, in processing-frame coordinates
        self.objects = []        # last non-person objects (x, y, w, h, conf, cls)
        self.frame_counter = 0
        STATE["ai_model_note"] = ""
        if CFG.get("ai_model") == "own" and not force_ssd:
            net, meta, why = own_ai_load()
            if net is not None:
                self.net, self.kind, self.meta = net, "yolo", meta
                STATE["ai_status"] = "ready"; STATE["ai_model"] = own_ai_name(meta)
                log_event("ai", f"AI model {STATE['ai_model']} loaded ({', '.join(meta['classes'])}, {meta['input']} px)")
                return
            STATE["ai_model_note"] = why
            log_event("ai", f"Own AI model not used ({why}) - the standard model (SSD) runs instead")
        STATE["ai_model"] = "SSD MobileNet V2"
        pb, pbtxt = ai_model_paths()
        if pb:
            try:
                self.net = cv2.dnn.readNetFromTensorflow(pb, pbtxt)
                STATE["ai_status"] = "ready"
                log_event("ai", "AI model SSD MobileNet V2 loaded")
            except Exception as e:
                STATE["ai_status"] = "load error"
                log_event("ai", f"AI model could not be loaded: {e}")
        else:
            CFG["ai_enabled"] = False
            STATE["ai_status"] = "no model files"
            log_event("ai", "AI off: model files not found - «Download AI model» in the self-check or the AI settings")

    def infer(self, img, conf_p, conf_o):
        """One run of the network on a picture: (persons [(x, y, w, h, conf)], objects [(x, y, w, h, conf, coco_cls)]) in
        picture coordinates. SSD and the own YOLO model give the same form (the own classes are mapped to COCO ids)."""
        h, w = img.shape[:2]
        if self.kind == "yolo":
            return own_ai_detect(self.net, self.meta, img, conf_p, conf_o)
        self.net.setInput(cv2.dnn.blobFromImage(img, size=(300, 300), swapRB=True, crop=False))
        det = self.net.forward()
        boxes, objects = [], []
        for i in range(det.shape[2]):
            cls, conf = int(det[0, 0, i, 1]), float(det[0, 0, i, 2])
            need = conf_p if cls == 1 else conf_o
            if cls < 1 or conf < need:
                continue
            x1, y1, x2, y2 = (det[0, 0, i, 3:7] * np.array([w, h, w, h])).astype(int)
            x1, y1 = max(0, x1), max(0, y1); x2, y2 = min(w - 1, x2), min(h - 1, y2)
            if x2 > x1 and y2 > y1:
                if cls == 1:
                    boxes.append((int(x1), int(y1), int(x2 - x1), int(y2 - y1), conf))
                else:
                    objects.append((int(x1), int(y1), int(x2 - x1), int(y2 - y1), conf, cls))
        return boxes, objects

    def detect(self, frame):
        """Run every N frames; returns list of (x, y, w, h, conf) persons."""
        if DEMO["on"]:
            self.boxes, self.objects = demo_ai(frame); STATE["ai_status"] = "demo"
            return self.boxes
        hp = helper_ready()                                 # 2.95.53: a PC does the AI (faster, the Pi stays cool)
        if (self.net is None and not hp) or not CFG["ai_enabled"]:
            STATE["ai_status"] = "off" if (self.net or hp) else STATE["ai_status"]
            self.boxes = []; self.objects = []
            return self.boxes
        if hp:
            got = helper_detect(frame)
            if got is not None:
                self.boxes, self.objects = got
                STATE["ai_persons"] = len(self.boxes)
                STATE["ai_status"] = f"PC · {HELPER['ms']} ms"
                return self.boxes
            if self.net is None:
                return self.boxes
        self.frame_counter += 1
        if self.frame_counter % (max(1, int(CFG["ai_every"])) * batt_save_ai_k()) != 0:     # 2.98.13: battery saver (105)
            return self.boxes
        # at most a few times per second and slower when the Pi gets hot: the AI is the biggest load (power, heat)
        gap = max(0.3, 2.0 * (STATE.get("ai_ms") or 0) / 1000.0)
        ct = STATE.get("cpu_temp") or 0
        gap *= 4.0 if ct >= 80 else 2.0 if ct >= 75 else 1.0
        if CFG.get("sim_on") and sim_eco_now():
            gap *= 2.0
        gap *= batt_save_ai_k()                                     # simulation with CPU saving: the AI only half as often
        if time.time() - getattr(self, "_last_run", 0.0) < gap:
            return self.boxes
        self._last_run = time.time()
        t0 = time.time()
        h, w = frame.shape[:2]
        try:
            boxes, objects = self.infer(frame, CFG["ai_conf"], CFG["object_conf"])
        except Exception as e:
            if self.kind != "yolo":
                raise
            STATE["ai_model_note"] = f"error while running: {e}"[:120]     # own model fails on this Pi: back to the standard
            log_event("ai", f"Own AI model failed ({str(e)[:120]}) - the standard model (SSD) runs instead")
            note = STATE["ai_model_note"]; self.__init__(force_ssd=True); STATE["ai_model_note"] = note
            return self.boxes
        # 2.98.13: «KI-Lupe» - something small moves (a person far away, 20-30 pixels in the 300 x 300 picture of the AI):
        # look at that part once more, enlarged. Far persons were found by the AI only rarely before.
        if CFG.get("ai_zoom", True):
            for hb in sorted(getattr(self, "hints", []), key=lambda b: -b[2] * b[3])[:1]:
                if any(iou(hb, b[:4]) > 0.1 for b in boxes):
                    continue
                side = int(min(min(w, h), max(110, 3.2 * hb[3])))
                cx, cy = hb[0] + hb[2] // 2, hb[1] + hb[3] // 2
                x0 = max(0, min(w - side, cx - side // 2)); y0 = max(0, min(h - side, cy - side // 2))
                crop = frame[y0:y0 + side, x0:x0 + side]
                if crop.size == 0:
                    continue
                for a1, b1, bw, bh, conf in self.infer(crop, CFG["ai_conf"], 2.0)[0]:      # only persons
                    bx = (x0 + a1, y0 + b1, max(1, bw), max(1, bh), conf)
                    if bx[3] >= 0.6 * side and side > 0.8 * min(w, h):
                        continue                               # the whole crop as one «person»: not trusted
                    if not any(iou(bx[:4], b[:4]) > 0.3 for b in boxes):
                        boxes.append(bx); STATE["ai_zoom_hits"] = STATE.get("ai_zoom_hits", 0) + 1
        self.boxes = boxes; self.objects = objects
        STATE["ai_ms"] = int((time.time() - t0) * 1000)
        STATE["ai_status"] = f"running · {STATE['ai_ms']} ms"
        STATE["ai_persons"] = len(boxes)
        return boxes


