# ----------------------------------------------------------------------------
# Relays: each one Off / On / Auto. Auto = on while its trigger is in view (+ hold time)
# ----------------------------------------------------------------------------
TRIGGERS = (["person", "motion", "prealarm", "warm", "noise", "remote", "animal", "cat", "dog", "bird", "car", "truck", "bicycle", "motorcycle", "bus"]
            + sorted(set(COCO_LABELS.values()) - {"person", "cat", "dog", "bird", "car", "truck", "bicycle", "motorcycle", "bus"}))
ANIMALS = {COCO_LABELS[i] for i in range(16, 26)}
TRIGGER_EN = {"motion": "motion (anything)", "prealarm": "pre-alarm (any movement)", "warm": "warm body (thermal camera)",
              "noise": "noise (microphone)", "animal": "animal (any)",
               "remote": "remote access (somebody watches from outside)"}
RELAY_NOTE = ("Auto: the relay switches on while its trigger is in view and stays on for the hold time. "
              "Animal and object triggers (e.g. cat) need the AI model. "
              "Pre-alarm switches on at the first movement in the picture, long before a person is confirmed. "
              "Remote access switches on while somebody watches over Tailscale - also when disarmed (e.g. a small warning lamp).")


def tr_trigger(key, lang=None):
    return tr(TRIGGER_EN.get(key, key), lang)


def _clean_relay(r, i, used):
    """Validate one relay loaded from the settings file. Returns None if no GPIO is left."""
    out = {"name": f"Relay {i + 1}", "gpio": None, "mode": "off", "trigger": "person", "hold": 5.0, "active_low": False}
    if isinstance(r.get("name"), str) and r["name"].strip():
        out["name"] = r["name"].strip()[:24]
    g = r.get("gpio")
    if isinstance(g, int) and 2 <= g <= 27 and g not in GPIO_RESERVED and g not in used:
        out["gpio"] = g
    else:
        out["gpio"] = next((x for x in FREE_GPIOS if x not in used and x not in GPIO_RESERVED), None)
    if out["gpio"] is None:
        return None
    if r.get("mode") in ("off", "on", "auto"):
        out["mode"] = r["mode"]
    if r.get("trigger") in TRIGGERS:
        out["trigger"] = r["trigger"]
    try:
        h = float(r.get("hold", 5.0))
        if math.isfinite(h):
            out["hold"] = max(0.5, min(600.0, h))
    except (TypeError, ValueError):
        pass
    out["active_low"] = bool(r.get("active_low", False))
    return out


def relay_update(idx, field, value):
    """Validated change of one relay setting (desktop + web). Returns (ok, error_message)."""
    if not (isinstance(idx, int) and 0 <= idx < len(RELAYS)):
        return False, "unknown relay"
    r = RELAYS[idx]
    if field == "name":
        v = str(value).strip()[:24] or f"Relay {idx + 1}"
    elif field == "gpio":
        try:
            v = int(float(value))
        except (TypeError, ValueError):
            return False, "GPIO must be a number"
        if not 2 <= v <= 27:
            return False, "GPIO must be between 2 and 27"
        if v in GPIO_RESERVED:
            return False, f"GPIO {v} is used by a servo"
        if v in thermal_gpios():
            return False, f"GPIO {v} is used by the thermal camera"
        if f"gpio:{v}" in (CFG["light_white_out"], CFG["light_ir_out"]):
            return False, f"GPIO {v} is used by a light"
        if any(i != idx and o["gpio"] == v for i, o in enumerate(RELAYS)):
            return False, f"GPIO {v} is already used by another relay"
    elif field == "mode":
        if value not in ("off", "on", "auto"):
            return False, "mode must be off / on / auto"
        v = value
    elif field == "trigger":
        if value not in TRIGGERS:
            return False, "unknown trigger"
        v = value
    elif field == "hold":
        try:
            v = float(value)
        except (TypeError, ValueError):
            return False, "hold time must be a number"
        if not math.isfinite(v):
            return False, "hold time must be a number"
        v = max(0.5, min(600.0, v))
    elif field == "active_low":
        v = bool(value)
    else:
        return False, "unknown field"
    if r.get(field) == v:
        return True, ""
    with LOCK:
        r[field] = v
    if field in ("mode", "trigger", "gpio"):
        log_event("servo", f"{r['name']}: {field} -> {v}")
    save_settings()
    return True, ""


def relay_add():
    if len(RELAYS) >= MAX_RELAYS:
        return False, f"maximum {MAX_RELAYS} relays"
    used = {r["gpio"] for r in RELAYS}
    gpio = next((g for g in FREE_GPIOS if g not in used and g not in GPIO_RESERVED), None)
    if gpio is None:
        return False, "no free GPIO left"
    new = {"name": f"Relay {len(RELAYS) + 1}", "gpio": gpio, "mode": "off", "trigger": "cat", "hold": 10.0, "active_low": False}
    with LOCK:
        RELAYS.append(new)
    log_event("servo", f"{new['name']} added on GPIO{gpio}")
    save_settings()
    return True, ""


def relay_remove(idx):
    if not (isinstance(idx, int) and 0 <= idx < len(RELAYS)):
        return False, "unknown relay"
    with LOCK:
        r = RELAYS.pop(idx)
    log_event("servo", f"{r['name']} (GPIO{r['gpio']}) removed")
    save_settings()
    return True, ""


class RelayManager:
    """Decides every frame which relay is on: mode On / Off, or Auto = trigger in view (+ hold time)."""
    def __init__(self):
        self.last_seen = {}; self.was_on = {}

    def update(self, present):
        now = time.time()
        with LOCK:
            relays = list(RELAYS)
        if STATE.get("remote"):
            present = set(present) | {"remote"}
        states, out = [], []
        for r in relays:
            k = id(r)
            if PAUSING["on"]:
                on = False
            elif r["mode"] == "on":
                on = True
            elif r["mode"] == "auto":
                if not CFG["relays_on"] or (not is_armed() and r["trigger"] != "remote"):
                    on = False
                else:
                    if r["trigger"] in present:
                        self.last_seen[k] = now
                    on = now - self.last_seen.get(k, 0.0) < r["hold"]
            else:
                on = False
            if on != self.was_on.get(k, False):
                why = tr_trigger(r["trigger"], "en") if r["mode"] == "auto" else r["mode"]
                log_event("servo", f"{r['name']} (GPIO{r['gpio']}) {'ON' if on else 'OFF'} ({why})")
            self.was_on[k] = on
            states.append(on); out.append((r["gpio"], on, bool(r["active_low"])))
        STATE["relay_states"] = states
        STATE["relay_out"] = out
        STATE["relay"] = bool(states and states[0])




def class_color(cls):
    """Stable BGR colour per class. Hues avoid red, which is reserved for persons."""
    hsv = np.uint8([[[30 + (int(cls) * 37) % 110, 210, 255]]])
    b, g, r = cv2.cvtColor(hsv, cv2.COLOR_HSV2BGR)[0, 0]
    return int(b), int(g), int(r)


def draw_object(frame, obj, sx, sy):
    """Box + label for a generic detected object. obj = (x, y, w, h, conf, cls) in processing coords."""
    x, y, w, h, conf, cls = obj
    X, Y, BW, BH = int(x * sx), int(y * sy), int(w * sx), int(h * sy)
    col = class_color(cls)
    cv2.rectangle(frame, (X, Y), (X + BW, Y + BH), col, 2)
    sp = species_for((x, y, w, h)) if CFG["species_on"] and SPECIES["cache"] else None
    label = f"{sp[0]} {int(sp[1] * 100)}%" if sp else f"{COCO_LABELS.get(cls, 'object')} {int(conf * 100)}%"
    (tw, th), _ = cv2.getTextSize(label, cv2.FONT_HERSHEY_SIMPLEX, 0.5, 1)
    top = max(0, Y - th - 8)
    cv2.rectangle(frame, (X, top), (X + tw + 6, top + th + 8), col, -1)
    cv2.putText(frame, label, (X + 3, top + th + 2), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 0, 0), 1, cv2.LINE_AA)


def corner_marks(img, box, color):
    """Thin corner brackets around a box: shows where something is without covering it (e.g. the face)."""
    x, y, w, h = box
    L = max(6, int(min(w, h) * 0.22)); t = max(1, img.shape[1] // 640)
    for (cx, cy, dx, dy) in ((x, y, 1, 1), (x + w, y, -1, 1), (x, y + h, 1, -1), (x + w, y + h, -1, -1)):
        cv2.line(img, (cx, cy), (cx + dx * L, cy), color, t, cv2.LINE_AA)
        cv2.line(img, (cx, cy), (cx, cy + dy * L), color, t, cv2.LINE_AA)


def draw_outline(frame, contours, box, sx, sy, color, thickness):
    """Draw the silhouette contours that lie inside `box` (processing coords) onto the full frame."""
    x, y, w, h = box[:4]
    for c in contours:
        cx, cy, cw, ch = cv2.boundingRect(c)
        if cx + cw / 2 >= x and cx + cw / 2 <= x + w and cy + ch / 2 >= y and cy + ch / 2 <= y + h:
            pts = (c.reshape(-1, 2) * np.array([sx, sy])).astype(np.int32)
            cv2.polylines(frame, [pts], True, color, thickness, cv2.LINE_AA)


def merge_boxes(boxes, gap_x=12, gap_y=30):
    """Union boxes that touch or nearly touch (a person often splits into head/torso/legs)."""
    boxes = [list(b[:4]) for b in boxes]
    merged = True
    while merged and len(boxes) > 1:
        merged = False
        out = []
        while boxes:
            a = boxes.pop(0)
            i = 0
            while i < len(boxes):
                b = boxes[i]
                if (a[0] - gap_x < b[0] + b[2] and b[0] - gap_x < a[0] + a[2] and
                        a[1] - gap_y < b[1] + b[3] and b[1] - gap_y < a[1] + a[3]):
                    x1, y1 = min(a[0], b[0]), min(a[1], b[1])
                    x2, y2 = max(a[0] + a[2], b[0] + b[2]), max(a[1] + a[3], b[1] + b[3])
                    a = [x1, y1, x2 - x1, y2 - y1]; boxes.pop(i); merged = True
                else:
                    i += 1
            out.append(a)
        boxes = out
    return [tuple(int(v) for v in b) for b in boxes]


def iou(a, b):
    ax, ay, aw, ah = a[:4]; bx, by, bw, bh = b[:4]
    ix = max(0, min(ax + aw, bx + bw) - max(ax, bx)); iy = max(0, min(ay + ah, by + bh) - max(ay, by))
    inter = ix * iy
    return inter / float(aw * ah + bw * bh - inter + 1e-6)


# ----------------------------------------------------------------------------
# Weather analysis
# ----------------------------------------------------------------------------
class WeatherAnalyzer:
    def __init__(self):
        self.prev_gray = None
        self.rain_hist = deque(maxlen=30)
        self.wind_hist = deque(maxlen=45)

    def rain(self, gray):
        if self.prev_gray is None:
            self.prev_gray = gray
            return 0.0
        diff = cv2.absdiff(gray, self.prev_gray)
        self.prev_gray = gray
        _, th = cv2.threshold(diff, 18, 255, cv2.THRESH_BINARY)
        vk = cv2.getStructuringElement(cv2.MORPH_RECT, (1, 5))
        hk = cv2.getStructuringElement(cv2.MORPH_RECT, (5, 1))
        streaks = cv2.subtract(cv2.morphologyEx(th, cv2.MORPH_OPEN, vk), cv2.morphologyEx(th, cv2.MORPH_OPEN, hk))
        n, _, stats, _ = cv2.connectedComponentsWithStats(streaks, 8)
        if n <= 1:
            score = 0.0
        else:
            areas = stats[1:, cv2.CC_STAT_AREA]
            tiny = np.sum((areas >= 3) & (areas <= 60))
            h, w = gray.shape
            cells = np.zeros((4, 4), np.uint8)
            cx = stats[1:, cv2.CC_STAT_LEFT] * 4 // w; cy = stats[1:, cv2.CC_STAT_TOP] * 4 // h
            cells[np.clip(cy, 0, 3), np.clip(cx, 0, 3)] = 1
            score = min(1.0, tiny / 160.0) * (0.4 + 0.6 * cells.mean())
        self.rain_hist.append(score)
        return float(np.mean(self.rain_hist))

    def wind(self, fg_mask, person_boxes):
        mask = fg_mask.copy()
        for (x, y, w, h) in person_boxes:
            mask[y:y + h, x:x + w] = 0
        n, _, stats, _ = cv2.connectedComponentsWithStats(mask, 8)
        if n <= 1:
            score = 0.0
        else:
            areas = stats[1:, cv2.CC_STAT_AREA]
            small = areas[(areas >= 8) & (areas <= 900)]
            score = min(1.0, small.sum() / float(mask.size) * 25.0 + len(small) / 220.0)
        self.wind_hist.append(score)
        return float(np.mean(self.wind_hist))


# ----------------------------------------------------------------------------
# Auto-tuner
# ----------------------------------------------------------------------------
class AutoTuner:
    def __init__(self):
        self.reset()

    def reset(self):
        self.t_start = time.time(); self.calibrated = False
        self.noise_areas, self.noise_frac = [], []
        self.last_eval = time.time()
        self.new_candidates = self.became_person = self.near_miss = self.walkers = 0
        self.seen_ids = set()
        self.base_min_area = None
        autotune_base_reset()                                   # 2.98.15: the ±20 % range (577)
        STATE["auto_status"] = "calibrating…"
        log_event("auto", "Auto-tune: calibrating - keep the scene empty for a few seconds")

    @staticmethod
    def _set(key, value, why):
        value = autotune_clamp(key, value)                     # 2.98.15: at most ±20 % around the measured values (577)
        value = round(value, 2) if isinstance(CFG[key], float) else int(value)
        if value != CFG[key]:
            old = CFG[key]; CFG[key] = value
            STATE["auto_changes"] += 1
            log_event("auto", f"Auto-tune: {key} {old} -> {value} ({why})")

    def observe(self, fg, tracks, persons, fps):
        if not CFG["auto_tune"]:
            STATE["auto_status"] = "off"; return
        if autotune_paused():                                   # 2.98.14: every measurement / training (312), not only three
            STATE["auto_status"] = "paused (test run)"; return   # 2.97.0: a measurement needs fixed values
        now = time.time()
        if fps > 1:
            self._set("walk_frames", max(4, min(24, round(fps * CFG["walk_seconds"]))), "fps")
        if not self.calibrated:
            n, _, stats, _ = cv2.connectedComponentsWithStats(fg, 8)
            if n > 1:
                self.noise_areas.extend(stats[1:, cv2.CC_STAT_AREA].tolist())
            self.noise_frac.append(np.count_nonzero(fg) / float(fg.size))
            left = CFG["calib_seconds"] - (now - self.t_start)
            STATE["auto_status"] = f"calibrating… {max(0, left):.0f}s"
            if left <= 0:
                self.calibrated = True
                if self.noise_areas:
                    self._set("min_area", max(600, min(4000, float(np.percentile(self.noise_areas, 95)) * 2.5)), "scene noise")
                self.base_min_area = float(CFG["min_area"])
                frac = float(np.mean(self.noise_frac)) if self.noise_frac else 0.0
                if frac > 0.02:
                    self._set("sensitivity", max(10, CFG["sensitivity"] - 20), "noisy scene")
                elif frac < 0.001:
                    self._set("sensitivity", min(90, CFG["sensitivity"] + 10), "very quiet scene")
                autotune_base_set("calibration")                  # 2.98.15: the anchor of the ±20 % (unless the assistant measured)
                STATE["auto_status"] = "tuned"
                log_event("auto", "Auto-tune: calibration done, now adjusting live")
            return
        for t in tracks:
            # 2.98.13: something that walks steadily somewhere is no «false blob» even when it is not a person (yet) - before,
            # every person that was not recognised made the minimum size bigger, until no person was recognised at all
            walker = len(t.speeds) >= 4 and t.steadiness() >= 0.3 and t.speed() >= CFG["walk_min_speed"]
            if not getattr(t, "_seen", False) and not walker and t.age >= 2:
                t._seen = True; self.new_candidates += 1
            elif walker and not getattr(t, "_walker", False):
                t._walker = True; self.walkers += 1
            if t.is_person and not getattr(t, "_counted", False):
                t._counted = True; self.became_person += 1
            if (not t.is_person and not t.is_vehicle and t.age >= CFG["walk_frames"]
                    and CFG["walk_min_speed"] <= t.speed() <= CFG["walk_max_speed"] * fps_k()
                    and 0.3 <= t.steadiness() < CFG["speed_consistency"]):
                self.near_miss += 1
        if now - self.last_eval < 10:
            return
        minutes = (now - self.last_eval) / 60.0
        self.last_eval = now
        false_rate = (self.new_candidates - self.became_person) / minutes
        if not persons:
            if false_rate > 25 and self.walkers == 0:              # 2.98.13: not while somebody walks; at most 2.5 × the calibrated size
                cap = min(8000, 2.5 * (self.base_min_area or CFG["min_area"]))
                self._set("min_area", min(cap, CFG["min_area"] * 1.2), f"{false_rate:.0f} false blobs/min")
            elif false_rate > 12:
                self._set("sensitivity", max(10, CFG["sensitivity"] - 5), "many false blobs")
            elif false_rate < 2 and self.became_person == 0:
                self._set("min_area", max(500, CFG["min_area"] * 0.93), "scene calm, more sensitive")
        if self.near_miss > 20 and self.became_person == 0:
            self._set("speed_consistency", max(0.3, CFG["speed_consistency"] - 0.05), "steady walkers not passing")
        elif self.became_person > 0 and false_rate < 5:
            self._set("speed_consistency", min(0.7, CFG["speed_consistency"] + 0.02), "persons detected, tightening")
        STATE["auto_status"] = f"tuned · {false_rate:.0f} false/min"
        self.new_candidates = self.became_person = self.near_miss = self.walkers = 0


# ----------------------------------------------------------------------------
# Tracker
# ----------------------------------------------------------------------------
def fps_k():
    """2.95.65: the speed limits (pixels per picture) were made for about 12 pictures per second. With fewer pictures
    (power saving, night, a slow simulator) a walking person moves much further from one picture to the next - before it
    then counted as a vehicle and was ignored, or the tracker lost it. Factor 1 … 6 for these limits."""
    fps = float(STATE.get("fps") or 0)
    return max(1.0, min(6.0, 12.0 / fps)) if fps > 0.5 else 1.0


class Track:
    _next = 1

    def __init__(self, box):
        self.id = Track._next; Track._next += 1
        self.box = box
        self.hist = deque(maxlen=40); self.speeds = deque(maxlen=40)
        self.hist.append(self.center())
        self.lost = 0; self.age = 0; self.born = time.time(); self.start = self.center()
        self.is_person = self.is_vehicle = self.ai_confirmed = False

    def center(self):
        x, y, w, h = self.box
        return (x + w / 2.0, y + h / 2.0)

    def update(self, box):
        old = self.center(); self.box = box; c = self.center()
        self.hist.append(c); self.speeds.append(math.hypot(c[0] - old[0], c[1] - old[1]))
        self.lost = 0; self.age += 1

    def speed(self):
        return float(np.mean(self.speeds)) if self.speeds else 0.0

    def steadiness(self):
        if len(self.speeds) < 4:
            return 0.0
        sp = np.array(self.speeds)
        if sp.mean() < 1e-3:
            return 0.0
        cv = sp.std() / sp.mean()
        pts = np.array(self.hist)
        path = np.sum(np.hypot(np.diff(pts[:, 0]), np.diff(pts[:, 1]))) + 1e-6
        net = math.hypot(pts[-1][0] - pts[0][0], pts[-1][1] - pts[0][1])
        return float(max(0.0, 1.0 - cv * 0.6) * (0.3 + 0.7 * net / path))


class Tracker:
    def __init__(self):
        self.tracks = []

    def update(self, boxes, max_dist=60):
        max_dist = max_dist * fps_k()                             # 2.95.65: fewer pictures -> bigger steps between them
        unmatched = list(range(len(boxes)))
        for t in self.tracks:
            best, bd = None, max_dist
            tc = t.center()
            for i in unmatched:
                x, y, w, h = boxes[i]
                d = math.hypot(x + w / 2 - tc[0], y + h / 2 - tc[1])
                if d < bd:
                    best, bd = i, d
            if best is not None:
                t.update(boxes[best]); unmatched.remove(best)
            else:
                t.lost += 1
        for i in unmatched:
            self.tracks.append(Track(boxes[i]))
        self.tracks = [t for t in self.tracks if t.lost < 8]
        return self.tracks


# ----------------------------------------------------------------------------
# «KI-Modell: Standard (SSD) / Eigenes (MoveEye-Modell)». The own model is a small YOLOv8 / YOLO11 detector, trained by
#   the GitHub workflow .github/workflows/ki_modell.yml (ki_training/README.md) and published as a release asset:
#     moveeye_model.onnx   the network (input 1 x 3 x N x N, RGB 0..1, letterbox; output 1 x (4 + nc) x A)
#     moveeye_model.json   its manifest: {"format": "moveeye-model-1", "version", "classes": ["person", "animal", "vehicle"],
#                          "input": 320, "file": "moveeye_model.onnx", "sha256", "size", "conf": {"person": 0.3, ...},
#                          "metrics": {"map50", "map50_95", ...}, "made", "images"}
#   It runs with cv2.dnn.readNetFromONNX (no extra Python packages on the Pi). The classes are mapped to COCO ids so that
#   the rest of MoveEye (relays, deterrence, diary, species) keeps working: person -> the person boxes, animal -> id 92
#   "animal" (new, counts as an animal), vehicle -> 3 "car", any COCO name (dog, cat ...) -> its own id.
#   If the files are missing or the model fails, the standard model (SSD MobileNet V2) runs instead.
# ----------------------------------------------------------------------------
OWN_AI = {"busy": False, "msg": "", "pct": 0}
OWN_AI_ONNX, OWN_AI_JSON = "moveeye_model.onnx", "moveeye_model.json"
OWN_AI_ANIMAL_ID = 92
OWN_AI_WILD = {"animal", "fox", "deer", "boar", "badger", "hare", "hedgehog", "wolf", "marten", "squirrel", "lynx", "chamois", "ibex",
               "roe deer", "wild boar", "rabbit", "mouse", "rat", "raccoon", "goat", "pig"}
COCO_LABELS.setdefault(OWN_AI_ANIMAL_ID, "animal")       # after part 190 (TRIGGERS has "animal" already)
ANIMALS.add("animal")


def own_ai_paths():
    """(onnx, json) of the first folder that has both - next to the program or in <data>/models."""
    for d in ai_model_dirs():
        a, b = os.path.join(d, OWN_AI_ONNX), os.path.join(d, OWN_AI_JSON)
        if os.path.isfile(a) and os.path.isfile(b):
            return a, b
    return None, None


def own_ai_check_manifest(m):
    """The manifest as a clean dict - raises ValueError with a short reason if something does not fit."""
    if not isinstance(m, dict) or m.get("format") != "moveeye-model-1":
        raise ValueError("not a MoveEye model description")
    cl = m.get("classes")
    if not (isinstance(cl, list) and 1 <= len(cl) <= 100 and all(isinstance(c, str) and 0 < len(c) <= 40 for c in cl)):
        raise ValueError("classes missing in the model description")
    n = int(m.get("input") or 0)
    if not (n % 32 == 0 and 160 <= n <= 1280):
        raise ValueError("input size of the model not valid")
    sha = str(m.get("sha256") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", sha):
        raise ValueError("checksum missing in the model description")
    fn = str(m.get("file") or OWN_AI_ONNX)
    if not re.fullmatch(r"[A-Za-z0-9_.\-]{1,80}\.onnx", fn):
        raise ValueError("file name not valid")
    conf = m.get("conf") if isinstance(m.get("conf"), dict) else {}
    out = dict(m, classes=[c.strip().lower() for c in cl], input=n, sha256=sha, file=fn,
               conf={str(k): min(0.9, max(0.05, float(v))) for k, v in conf.items() if isinstance(v, (int, float))},
               version=str(m.get("version") or "?")[:40])
    return out


def own_ai_name(meta):
    return f"MoveEye model {meta.get('version', '?')}" if meta else "SSD MobileNet V2"


def own_ai_classmap(names):
    """[(coco_id or 1 for person, is_person)] per class of the own model; None = class not used."""
    by_name = {v: k for k, v in COCO_LABELS.items()}
    out = []
    for nm in names:
        if nm == "person":
            out.append((1, True))
        elif nm in ("vehicle", "car"):
            out.append((3, False))
        elif nm in by_name:
            out.append((by_name[nm], False))
        elif nm in OWN_AI_WILD:
            out.append((OWN_AI_ANIMAL_ID, False))
        else:
            out.append(None)
    return out


def own_ai_letterbox(img, n):
    """the picture into an n x n square (aspect kept, grey borders like at the training): (square, scale, dx, dy)"""
    h, w = img.shape[:2]; r = min(n / float(w), n / float(h))
    nw, nh = max(1, int(round(w * r))), max(1, int(round(h * r)))
    sq = np.full((n, n, 3), 114, np.uint8); dx, dy = (n - nw) // 2, (n - nh) // 2
    sq[dy:dy + nh, dx:dx + nw] = cv2.resize(img, (nw, nh), interpolation=cv2.INTER_AREA if r < 1 else cv2.INTER_LINEAR)
    return sq, r, dx, dy


def own_ai_decode(out, nc, thr, r, dx, dy, w, h, nms_iou=0.45):
    """YOLOv8 / YOLO11 output 1 x (4 + nc) x A (or 1 x A x (4 + nc)): cx, cy, bw, bh in pixels of the square input and nc class
    scores (already 0..1). thr = minimum score per class. Returns [(x, y, w, h, conf, class)] in picture pixels after NMS per class."""
    a = np.asarray(out, dtype=np.float32)
    while a.ndim > 2 and a.shape[0] == 1:
        a = a[0]
    if a.ndim != 2 or (a.shape[0] != 4 + nc and a.shape[1] != 4 + nc):
        raise ValueError(f"unexpected model output {tuple(np.asarray(out).shape)} for {nc} classes")
    if a.shape[0] == 4 + nc and a.shape[1] != 4 + nc:
        a = a.T                                            # -> A x (4 + nc)
    sc = a[:, 4:4 + nc]
    k = sc.argmax(1); conf = sc[np.arange(sc.shape[0]), k]
    keep = conf >= np.asarray(thr, np.float32)[k]
    if not keep.any():
        return []
    a, k, conf = a[keep], k[keep], conf[keep]
    x1 = np.clip((a[:, 0] - a[:, 2] / 2 - dx) / r, 0, w - 1); y1 = np.clip((a[:, 1] - a[:, 3] / 2 - dy) / r, 0, h - 1)
    x2 = np.clip((a[:, 0] + a[:, 2] / 2 - dx) / r, 0, w - 1); y2 = np.clip((a[:, 1] + a[:, 3] / 2 - dy) / r, 0, h - 1)
    ok = (x2 - x1 >= 1) & (y2 - y1 >= 1)
    x1, y1, x2, y2, k, conf = x1[ok], y1[ok], x2[ok], y2[ok], k[ok], conf[ok]
    if not len(conf):
        return []
    off = k.astype(np.float32) * float(w + h + 10)          # NMS per class: each class moved to its own place
    rects = [[float(x1[i] + off[i]), float(y1[i]), float(x2[i] - x1[i]), float(y2[i] - y1[i])] for i in range(len(conf))]
    idx = cv2.dnn.NMSBoxes(rects, [float(c) for c in conf], 0.0, nms_iou)
    idx = np.asarray(idx).reshape(-1) if len(idx) else []
    res = [(int(x1[i]), int(y1[i]), int(round(x2[i] - x1[i])), int(round(y2[i] - y1[i])), float(conf[i]), int(k[i])) for i in idx]
    return sorted(res, key=lambda b: -b[4])


def own_ai_thresholds(meta, conf_p, conf_o):
    """the sliders keep their meaning: 0.5 = the best threshold found at the training («conf» of the manifest), higher = stricter"""
    th = []
    for nm in meta["classes"]:
        base = float(meta["conf"].get(nm, 0.35))
        th.append(round(min(0.95, max(0.05, base + (float(conf_p if nm == "person" else conf_o) - 0.5))), 3))
    return th


def own_ai_detect(net, meta, img, conf_p, conf_o):
    """(persons, objects) like the SSD part of AIDetector.infer"""
    h, w = img.shape[:2]; n = int(meta["input"])
    sq, r, dx, dy = own_ai_letterbox(img, n)
    net.setInput(cv2.dnn.blobFromImage(sq, 1.0 / 255.0, (n, n), swapRB=True, crop=False))
    out = net.forward()
    cmap = meta.get("_map") or own_ai_classmap(meta["classes"])
    th = own_ai_thresholds(meta, conf_p, conf_o)
    th = [2.0 if cmap[i] is None or (not cmap[i][1] and conf_o > 1.0) else t for i, t in enumerate(th)]    # conf_o > 1: only persons
    boxes, objects = [], []
    for x, y, bw, bh, cf, k in own_ai_decode(out, len(meta["classes"]), th, r, dx, dy, w, h):
        cid, is_p = cmap[k]
        if is_p:
            boxes.append((x, y, bw, bh, cf))
        else:
            objects.append((x, y, bw, bh, cf, cid))
    return boxes, objects


def own_ai_load():
    """(net, manifest, "") or (None, None, reason) - the network is tried once on an empty picture (an OpenCV that cannot
    run the model is found here, not at the first alarm)."""
    onnx, js = own_ai_paths()
    if not onnx:
        return None, None, "own model not downloaded yet"
    try:
        with open(js, encoding="utf-8") as f:
            meta = own_ai_check_manifest(json.load(f))
        net = cv2.dnn.readNetFromONNX(onnx)
        n = meta["input"]
        net.setInput(cv2.dnn.blobFromImage(np.zeros((n, n, 3), np.uint8), 1.0 / 255.0, (n, n), swapRB=True))
        o = net.forward()
        own_ai_decode(o, len(meta["classes"]), [2.0] * len(meta["classes"]), 1.0, 0, 0, n, n)    # shape check
        meta["_map"] = own_ai_classmap(meta["classes"])
        if not any(m and m[1] for m in meta["_map"]):
            raise ValueError("the model has no class «person»")
        return net, meta, ""
    except (OSError, ValueError, TypeError, cv2.error) as e:
        return None, None, f"load error: {str(e).splitlines()[0] if str(e) else e.__class__.__name__}"[:140]


def own_ai_switched():
    """«KI-Modell» changed: load it (in the background - the network needs a moment)"""
    w = WATCH_REF.get("w")
    if w is None:
        return
    def run():
        try:
            w.ai = AIDetector()
            if w.ai.kind == "yolo" and not CFG["ai_enabled"]:
                CFG["ai_enabled"] = True; save_settings()  # chosen by hand: the AI is wanted (it was switched off without a model)
        except Exception as e:
            log_event("ai", f"AI model switch failed: {e}"[:200])
    threading.Thread(target=run, daemon=True, name="ai-switch").start()


def _own_ai_get(url, limit, progress=None):
    """bytes of an https address (certificates checked, size limited) and their sha256"""
    req = urllib.request.Request(url, headers={"User-Agent": "MotionWatch/" + APP_VERSION})
    h = hashlib.sha256(); buf = bytearray()
    with urllib.request.urlopen(req, timeout=60) as r:
        total = int(r.headers.get("Content-Length") or 0)
        if total > limit:
            raise ValueError("file too big")
        for chunk in iter(lambda: r.read(256 * 1024), b""):
            buf += chunk; h.update(chunk)
            if len(buf) > limit:
                raise ValueError("file too big")
            if progress:
                progress(len(buf), total)
    return bytes(buf), h.hexdigest()


class OwnAiKept(Exception):
    """the new model is not installed: the same as the running one, or its evaluation is worse (part 196)"""


def own_ai_download(url=None, only_better=False):
    """Fetch the own model: manifest (moveeye_model.json) from the address in the settings, then the .onnx file next to it;
    the sha256 of the manifest must match. Then switch to it («KI-Modell: Eigenes»).
    only_better: install only when it is new and its evaluation is not worse than the downloaded one (own_ai_not_worse, part 196)."""
    if OWN_AI["busy"]:
        return False, "already running"
    if DEMO["on"]:
        return False, "not in the demo"
    url = str(url or CFG.get("ai_own_url") or DEFAULTS["ai_own_url"]).strip()
    if not (url.startswith("https://") and _http_ok(url)):
        return False, "https://... address of moveeye_model.json expected"
    OWN_AI.update(busy=True, msg="downloading", pct=0)

    def run():
        dst = os.path.join(DATA_DIR, "models"); tmp_o = os.path.join(dst, OWN_AI_ONNX + ".part"); tmp_j = os.path.join(dst, OWN_AI_JSON + ".part")
        try:
            os.makedirs(dst, exist_ok=True)
            raw, _h = _own_ai_get(url, 256 * 1024)
            try:
                meta = own_ai_check_manifest(json.loads(raw.decode("utf-8")))
            except (UnicodeDecodeError, json.JSONDecodeError, TypeError):
                raise RuntimeError("the model description is not valid")
            except ValueError as e:
                raise RuntimeError(str(e))
            if only_better:
                ok_, why_, det_ = own_ai_not_worse(meta, own_ai_current_meta())
                if not ok_:
                    raise OwnAiKept(tr(why_) + (f" ({det_})" if det_ else ""))
            src = meta.get("url") if str(meta.get("url") or "").startswith("https://") else url.rsplit("/", 1)[0] + "/" + meta["file"]
            def prog(got, total):
                OWN_AI["pct"] = int(got * 90 / total) if total else min(89, got // (200 * 1024))
            data, sha = _own_ai_get(src, 80 * 1024 * 1024, prog)
            if sha != meta["sha256"]:
                raise RuntimeError("checksum wrong - the file is damaged or not the right one")
            OWN_AI["pct"] = 95
            with open(tmp_o, "wb") as f:
                f.write(data)
            with open(tmp_j, "wb") as f:
                f.write(raw)
            try:
                net = cv2.dnn.readNetFromONNX(tmp_o)
                n = meta["input"]; net.setInput(cv2.dnn.blobFromImage(np.zeros((n, n, 3), np.uint8), 1.0 / 255.0, (n, n), swapRB=True))
                own_ai_decode(net.forward(), len(meta["classes"]), [2.0] * len(meta["classes"]), 1.0, 0, 0, n, n)
            except (cv2.error, ValueError) as e:
                raise RuntimeError(("this OpenCV cannot run the model: " + str(e).splitlines()[0][:80]) if str(e) else "model damaged")
            os.replace(tmp_o, os.path.join(dst, OWN_AI_ONNX)); os.replace(tmp_j, os.path.join(dst, OWN_AI_JSON))
            CFG["ai_model"] = "own"; CFG["ai_enabled"] = True; save_settings()
            w = WATCH_REF.get("w")
            if w is not None:
                w.ai = AIDetector()
            OWN_AI.update(msg="ready", pct=100)
            log_event("ai", f"Own AI model {meta['version']} downloaded ({len(data) // 1024} kB, sha256 ok) and switched on")
        except OwnAiKept as e:
            OWN_AI.update(msg=(tr("not installed") + ": " + str(e))[:160], pct=0)
            log_event("ai", f"Own AI model: new one not installed ({e})"[:200])
        except Exception as e:
            reason = _short_net_err(e) if isinstance(e, (OSError, urllib.error.URLError)) else str(e)
            OWN_AI.update(msg=f"failed: {tr(reason)}"[:140], pct=0)
            log_event("ai", f"Own AI model download failed: {reason}"[:200])
        finally:
            OWN_AI["busy"] = False
            for p_ in (tmp_o, tmp_j):
                try:
                    os.remove(p_)
                except OSError:
                    pass
    threading.Thread(target=run, daemon=True, name="own-ai").start()
    return True, ""


def own_ai_info(lang=None):
    """for the web page, the window and the self-check"""
    onnx, js = own_ai_paths(); meta = None
    if js:
        try:
            key = (js, os.path.getmtime(js))
            if OWN_AI.get("_mkey") != key:               # read again only when the file changed (the window asks every second)
                with open(js, encoding="utf-8") as f:
                    OWN_AI["_meta"] = own_ai_check_manifest(json.load(f))
                OWN_AI["_mkey"] = key
            meta = OWN_AI.get("_meta")
        except (OSError, ValueError, TypeError):
            meta = None; OWN_AI["_mkey"] = None
    ai = getattr(WATCH_REF.get("w"), "ai", None)
    running = "own" if ai is not None and ai.kind == "yolo" else ("ssd" if ai is not None and ai.net is not None else "")
    m = (meta or {}).get("metrics") or {}
    en = norm_lang(lang or CFG.get("lang") or "en") not in ("de", "rm")
    summ = str((meta or {}).get("summary_en" if en else "summary") or (meta or {}).get("summary") or "")[:400]
    return {"summary": summ, "recall": m.get("recall"), "auto": bool(CFG.get("ai_own_auto", True)),
            "check_msg": tr(OWN_AI.get("check_msg") or "", lang), "checked": CFG.get("ai_own_check_day") or None,
            "choice": CFG.get("ai_model", "ssd"), "running": running, "running_version": ai.meta.get("version") if running == "own" else None, "note": tr(STATE.get("ai_model_note") or "", lang),
            "present": bool(onnx), "version": (meta or {}).get("version"), "classes": (meta or {}).get("classes"),
            "input": (meta or {}).get("input"), "map50": m.get("map50"), "made": (meta or {}).get("made"),
            "busy": OWN_AI["busy"], "pct": OWN_AI["pct"], "msg": OWN_AI["msg"], "url": CFG.get("ai_own_url") or DEFAULTS["ai_own_url"]}


def own_ai_text(lang=None):
    """one line: which model runs (status lines in the window and on the page)"""
    i = own_ai_info(lang)
    run = {"own": tr("MoveEye model", lang) + " " + str(i["running_version"]), "ssd": "SSD MobileNet V2"}.get(i["running"]) or tr("none", lang)
    t = "🧠 " + tr("AI model", lang) + ": " + run
    if i["choice"] == "own" and i["note"]:
        t += " · ⚠ " + tr("own model not used", lang) + " (" + i["note"] + ")"
    if i["present"]:
        t += f" · {tr('downloaded', lang)}: {i['version']}" + (f" · mAP50 {i['map50']:.2f}" if isinstance(i["map50"], (int, float)) else "")
    return t


def own_ai_selftest():
    """self-test: a fake YOLO output (2 classes, 6 anchors) - decoding, letterbox back to the picture, NMS, class mapping"""
    n, nc, A = 320, 3, 6
    o = np.zeros((1, 4 + nc, A), np.float32)
    cand = [(160, 120, 40, 100, 0, 0.9), (162, 121, 42, 98, 0, 0.8),      # one person twice (NMS keeps one)
            (60, 200, 50, 30, 1, 0.7), (61, 200, 50, 30, 0, 0.6),         # an animal and a weaker «person» on the same place (other class: both stay)
            (250, 100, 20, 20, 2, 0.1), (100, 100, 10, 10, 1, 0.2)]       # below the thresholds
    for j, (cx, cy, bw, bh, k, cf) in enumerate(cand):
        o[0, :4, j] = (cx, cy, bw, bh); o[0, 4 + k, j] = cf
    w, h = 640, 480                                        # picture 640 x 480 -> scale 0.5, 40 px border above and below
    _sq, r, dx, dy = own_ai_letterbox(np.zeros((h, w, 3), np.uint8), n)
    assert abs(r - 0.5) < 1e-6 and (dx, dy) == (0, 40), f"letterbox {r} {dx} {dy}"
    got = own_ai_decode(o, nc, [0.5, 0.5, 0.5], r, dx, dy, w, h)
    assert len(got) == 3, f"{len(got)} boxes instead of 3: {got}"
    p = got[0]
    assert p[5] == 0 and abs(p[4] - 0.9) < 1e-6 and abs(p[0] - 280) <= 1 and abs(p[1] - 60) <= 1 and abs(p[2] - 80) <= 1 and abs(p[3] - 200) <= 1, f"person {p}"
    assert sorted(b[5] for b in got) == [0, 0, 1], f"classes {got}"
    got_t = own_ai_decode(o.transpose(0, 2, 1), nc, [0.5, 0.5, 0.5], r, dx, dy, w, h)     # 1 x A x (4 + nc) gives the same
    assert got_t == got, "transposed output"
    cm = own_ai_classmap(["person", "animal", "vehicle", "dog", "fox", "toaster-robot"])
    assert cm[0] == (1, True) and cm[1] == (OWN_AI_ANIMAL_ID, False) and cm[2] == (3, False) and cm[3] == (18, False) and cm[4] == (OWN_AI_ANIMAL_ID, False) and cm[5] is None
    assert COCO_LABELS[OWN_AI_ANIMAL_ID] in ANIMALS
    try:
        own_ai_decode(np.zeros((1, 9, 5), np.float32), nc, [0.5] * 3, 1, 0, 0, w, h); raise AssertionError("wrong shape not found")
    except ValueError:
        pass
    m = own_ai_check_manifest({"format": "moveeye-model-1", "classes": ["person", "animal", "vehicle"], "input": 320, "sha256": "a" * 64, "conf": {"person": 0.3}})
    assert own_ai_thresholds(m, 0.5, 0.6) == [0.3, 0.45, 0.45], own_ai_thresholds(m, 0.5, 0.6)
    own_ai_auto_selftest()                                 # part 196: may a new model replace the running one?
# ----------------------------------------------------------------------------
# «KI trainieren» im Simulator (kitrain.gd) legt ein Trainingspaket auf GitHub und startet das Training (ki_modell.yml).
# Das neue Modell erscheint im Release «ki-modell». Hier: einmal am Tag (und beim Knopf «Eigenes Modell aktualisieren»)
# das Manifest lesen und das Modell nur übernehmen, wenn es neu ist und seine Messung nicht schlechter als die des
# laufenden: mAP50, Trefferquote und «Personen gefunden» (eval.recall_person aus der Auswertung «wo versagt die KI»),
# je mit 0.02 Spielraum (jedes Training misst auf etwas anderen Bildern).
# Nur wenn schon ein eigenes Modell heruntergeladen ist - zum ersten Mal holt man es von Hand.
# ----------------------------------------------------------------------------
_OWNAUTO_CFG = {"ai_own_auto": True, "ai_own_check_day": ""}
for _k, _v in _OWNAUTO_CFG.items():
    CFG.setdefault(_k, _v)
    DEFAULTS.setdefault(_k, _v)
OWN_AI_TOL = 0.02


def own_ai_current_meta():
    """the manifest of the downloaded own model, or None"""
    _o, js = own_ai_paths()
    if not js:
        return None
    try:
        with open(js, encoding="utf-8") as f:
            return own_ai_check_manifest(json.load(f))
    except (OSError, ValueError, TypeError):
        return None


def _own_ai_scores(m):
    """the comparable numbers of a manifest: {"mAP50": .., "recall": .., "persons found": ..} (only those it has)"""
    m = m or {}
    met = m.get("metrics") if isinstance(m.get("metrics"), dict) else {}
    ev = m.get("eval") if isinstance(m.get("eval"), dict) else {}
    out = {}
    for name, v in (("mAP50", met.get("map50")), ("recall", met.get("recall")), ("persons found", ev.get("recall_person"))):
        if isinstance(v, (int, float)) and not isinstance(v, bool) and 0.0 <= float(v) <= 1.0:
            out[name] = float(v)
    return out


def own_ai_not_worse(new, cur):
    """(ok, reason in English for tr(), detail with numbers) - may the new model replace the running one?"""
    if not cur:
        return True, "", ""
    if str(new.get("sha256") or "") and str(new.get("sha256")) == str(cur.get("sha256") or ""):
        return False, "already the newest model", ""
    a, b = _own_ai_scores(new), _own_ai_scores(cur)
    common = [k for k in a if k in b]
    if not common:
        return (False, "the new model has no evaluation", "") if b else (True, "", "")
    worse = [f"{k} {a[k]:.2f} < {b[k]:.2f}" for k in common if a[k] < b[k] - OWN_AI_TOL]
    if worse:
        return False, "its evaluation is worse", ", ".join(worse)
    return True, "", ""


def own_ai_auto_check(force=False):
    """once a day (force: now): look for a new own model and install it only if it is not worse. Returns (started, reason)."""
    if not CFG.get("ai_own_auto", True) and not force:
        return False, "off"
    if not own_ai_paths()[0]:
        return False, "own model not downloaded yet"
    if DEMO["on"] or OWN_AI["busy"]:
        return False, "busy"
    day = datetime.now().strftime("%Y-%m-%d")
    if not force and CFG.get("ai_own_check_day") == day:
        return False, "checked today"
    CFG["ai_own_check_day"] = day
    save_settings()
    ok, err = own_ai_download(only_better=True)
    OWN_AI["check_msg"] = "" if ok else err
    if not ok:
        log_event("ai", f"Own AI model: daily check not possible ({err})"[:200])
    return ok, err


def _own_ai_auto_loop():
    time.sleep(600)                                      # not right at the start (network, camera first)
    while True:
        try:
            own_ai_auto_check()
        except Exception as e:
            log_event("ai", f"Own AI model check: {e}"[:200])
        time.sleep(1800)


def own_ai_long_text(lang=None):
    """own_ai_text + the summary of its evaluation («wo versagt die KI») + the automatic update (for the window)"""
    i = own_ai_info(lang)
    t = own_ai_text(lang)
    if i.get("summary"):
        t += "\n📊 " + i["summary"]
    if i["present"]:
        t += "\n🔄 " + (tr("updates by itself (daily, only if not worse)", lang) if i["auto"] else tr("automatic update off", lang))
        if CFG.get("ai_own_check_day"):
            t += f" · {tr('last check', lang)} {CFG['ai_own_check_day']}"
    if OWN_AI.get("msg") and OWN_AI["msg"] != "ready" and not OWN_AI["busy"]:
        t += "\n" + OWN_AI["msg"]
    return t


def own_ai_auto_selftest():
    """self-test: comparing two manifests"""
    cur = {"sha256": "a" * 64, "metrics": {"map50": 0.70, "recall": 0.60}, "eval": {"recall_person": 0.80}}
    assert own_ai_not_worse({"sha256": "a" * 64}, cur)[0] is False                                   # the same file
    assert own_ai_not_worse({"sha256": "b" * 64, "metrics": {"map50": 0.69, "recall": 0.61}, "eval": {"recall_person": 0.79}}, cur)[0]   # within 0.02
    ok, why, det = own_ai_not_worse({"sha256": "b" * 64, "metrics": {"map50": 0.72, "recall": 0.62}, "eval": {"recall_person": 0.70}}, cur)
    assert not ok and why == "its evaluation is worse" and "persons found" in det, (ok, why, det)
    assert own_ai_not_worse({"sha256": "b" * 64}, cur)[1] == "the new model has no evaluation"
    assert own_ai_not_worse({"sha256": "b" * 64, "metrics": {"map50": 0.5}}, None)[0]                 # nothing installed yet
    assert own_ai_not_worse({"sha256": "b" * 64, "metrics": {"map50": 0.5}}, {"sha256": "c" * 64})[0]   # old model without numbers


threading.Thread(target=_own_ai_auto_loop, daemon=True, name="own-ai-auto").start()
# ----------------------------------------------------------------------------
# Wunsch Daniel (29.10.2026, «KI-Daten aufräumen»):
#   * «Trainingspaket für ein eigenes KI-Modell (YOLO)» (Reiter Simulator und Fenster) hat dieselbe Wahl wie der Simulator:
#     «Vielfalt: normal / hoch» (dataset.gd / kitrain.gd, Name «vielfalt» wie dort).
#   * Die Pakete (Ordner user://trainingsbilder/<Zeit> + ZIP «MW-Trainingsbilder_….zip» auf dem Schreibtisch) liegen auf dem
#     Rechner des Simulators (PC oder Pi). Der Simulator räumt nach jedem neuen Paket selbst auf (kidaten.gd): die neuesten 3
#     bleiben, nichts älter als 30 Tage; das neueste Paket bleibt immer. Der Knopf «Alte KI-Daten löschen» löscht alle
#     ausser dem neuesten. Das KI-Modell (models/moveeye_model.*, frozen_inference_graph.pb) wird nie angefasst.
# ----------------------------------------------------------------------------
KIDATA_VF = ("normal", "hoch")
KIDATA_SIZES = (200, 500, 1000, 2000)


def kidata_export(n, vielfalt=None):
    """a training pack in the simulator; vielfalt "normal" / "hoch" (else the choice of the simulator)"""
    try:
        n = int(n or 500)
    except (TypeError, ValueError):
        n = 500
    q = {"action": "dataset", "op": "export", "n": max(10, min(5000, n))}
    if str(vielfalt or "") in KIDATA_VF:
        q["vielfalt"] = str(vielfalt)
    return sim_control(q)


def kidata_packs(clean=False, lang=None):
    """the packs on the PC of the simulator; clean=True: delete all except the newest. ValueError for an old simulator."""
    r = sim_control({"action": "dataset", "op": "clean" if clean else "packs"})
    if not isinstance(r, dict) or "packs" not in r:
        raise ValueError("not supported - update the simulator")
    if not r.get("ok", True):
        raise ValueError(str(r.get("error") or "busy"))
    if clean:
        log_event("ai", f"Old AI data deleted: {int(r.get('deleted') or 0)} packs, {float(r.get('freed_mb') or 0):.0f} MB")
    r["text"] = kidata_text(r, lang)
    return r


def kidata_text(r, lang=None):
    ps = r.get("packs") or []
    t = (f"📦 {len(ps)} " + tr("training packs", lang) + f" · {float(r.get('total_mb') or 0):.0f} MB") if ps else "📦 " + tr("no training packs", lang)
    if r.get("deleted"):
        t += " · 🧹 " + trf("{n} deleted ({mb} MB)", lang, n=int(r["deleted"]), mb=f"{float(r.get('freed_mb') or 0):.0f}")
    return t


def kidata_tk_build(app, parent):
    """the window (section Simulator): size, «Vielfalt», «Trainingspaket», «Alte KI-Daten löschen» + one status line"""
    ttk.Label(parent, text="📦 " + tr("Training set for an own AI model (YOLO)"), style="Mut.TLabel").pack(anchor="w", pady=(8, 0))
    fr = ttk.Frame(parent); fr.pack(fill="x", pady=(2, 0))
    n_var = tk.StringVar(value="500")
    ttk.Combobox(fr, textvariable=n_var, values=[str(x) for x in KIDATA_SIZES], width=6, state="readonly").pack(side="left", padx=(0, 4))
    vf_names = {"hoch": tr("Variety: high (recommended)"), "normal": tr("Variety: normal")}
    vf_var = tk.StringVar(value=vf_names["hoch"])
    ttk.Combobox(fr, textvariable=vf_var, values=[vf_names["hoch"], vf_names["normal"]], state="readonly", width=24).pack(side="left", fill="x", expand=True)
    lbl = ttk.Label(parent, text="", style="Mut.TLabel", wraplength=330, justify="left")

    def run(fn):
        def work():
            try:
                txt = fn()
            except ValueError as e:
                txt = "⚠ " + tr_err(str(e))
            except Exception:
                txt = "⚠ " + tr_err("simulator not reachable")
            try:
                app.root.after(0, lambda: lbl.config(text=txt))
            except Exception:
                pass
        threading.Thread(target=work, daemon=True, name="kidata").start()

    def export():
        vf = "normal" if vf_var.get() == vf_names["normal"] else "hoch"
        r = kidata_export(n_var.get(), vf)
        return tr("The simulator makes the pictures and saves a ZIP on the desktop of its PC (about 2 s per picture).") + " " + str((r or {}).get("msg") or "")

    def clean():
        if not messagebox.askyesno("MoveEye", tr("Delete all training packs on the PC of the simulator except the newest one? The AI model stays.")):
            return
        run(lambda: kidata_packs(True)["text"])
    bf = ttk.Frame(parent); bf.pack(fill="x", pady=(4, 0))
    ttk.Button(bf, text="📦 " + tr("Make the training pack"), command=lambda: run(export)).pack(side="left", expand=True, fill="x", padx=(0, 4))
    ttk.Button(bf, text="🧹 " + tr("Delete old AI data"), command=clean).pack(side="left", expand=True, fill="x")
    lbl.pack(anchor="w", pady=(4, 0))
    ttk.Label(parent, text=tr("Cleaned up by itself: after every new pack the newest 3 stay, nothing older than 30 days (the newest always stays). The AI model is never deleted."), style="Mut.TLabel", wraplength=330, justify="left").pack(anchor="w")
    run(lambda: kidata_packs(False)["text"])
# ----------------------------------------------------------------------------
# Main detector
# ----------------------------------------------------------------------------
# ----------------------------------------------------------------------------
# Video sources
#   usb:<n>   USB / V4L2 webcams (/dev/video<n>)        pi:<n>   Raspberry Pi CSI cameras (picamera2)
#   url:<id>  network cameras: RTSP / HTTP-MJPEG (IP cams, Wi-Fi cams) saved in the settings
#   auto      first working USB camera (the behaviour of the older versions)
# Every source object offers read() -> (ok, BGR frame) and release(), so the main loop does not care where the picture comes from.
# ----------------------------------------------------------------------------
SRC_RE = re.compile(r"^(auto|demo|usb:\d{1,2}|pi:\d{1,2}|url:[0-9a-f]{8}|senxor:0|sim:\d|sim:thermal)$")
MAX_IP_SOURCES = 16
V4L_SKIP = ("bcm2835-codec", "bcm2835-isp", "rpivid", "pispbe", "rp1-cfe", "hevc", "-decoder", "-encoder")   # Pi internal nodes, no cameras
SOURCES = {"items": [], "time": 0.0, "scanning": False, "hints": []}      # result of the last scan
_SCAN_LOCK = threading.Lock()


def _url_ok(u):
    return isinstance(u, str) and len(u) <= 500 and re.match(r"^(rtsp|rtsps|http|https)://[^\s]+$", u, re.I) is not None


def mask_url(u):
    """rtsp://user:secret@host/x -> rtsp://user:***@host/x  (passwords are never shown or sent to the browser)."""
    return re.sub(r"(://[^/@:\s]+):[^/@\s]*@", r"\1:***@", u or "")


def _clean_ip_sources(lst):
    out, seen = [], set()
    for s in (lst if isinstance(lst, list) else [])[:MAX_IP_SOURCES]:
        if not isinstance(s, dict):
            continue
        sid, url = str(s.get("id", "")), str(s.get("url", "")).strip()
        if not re.fullmatch(r"[0-9a-f]{8}", sid) or sid in seen or not _url_ok(url):
            continue
        seen.add(sid)
        out.append({"id": sid, "name": str(s.get("name") or "").strip()[:40] or "Network camera", "url": url})
    return out


def find_ip_source(sid):
    for s in CFG["ip_sources"]:
        if s["id"] == sid:
            return s
    return None


_ROT = {"90": cv2.ROTATE_90_CLOCKWISE, "180": cv2.ROTATE_180, "270": cv2.ROTATE_90_COUNTERCLOCKWISE}


def cam_orient(frame):
    """Turn / mirror the camera picture as set (camera mounted sideways or upside down). Everything after sees it upright."""
    r = _ROT.get(str(CFG.get("cam_rotate", "0")))
    if r is not None:
        frame = cv2.rotate(frame, r)
    if CFG.get("cam_mirror"):
        frame = cv2.flip(frame, 1)
    return frame


class CvSource:
    """A camera read through OpenCV (USB webcam or network stream)."""
    def __init__(self, cap, size=None):
        self.cap = cap; self.size = size; self.full_fps = None

    def read(self):
        return self.cap.read()

    def set_fps(self, fps):
        """fps=None: full speed again. Many USB cameras can go slower; if not, nothing happens."""
        try:
            if self.full_fps is None:
                self.full_fps = float(self.cap.get(cv2.CAP_PROP_FPS) or 0) or 30.0
            self.cap.set(cv2.CAP_PROP_FPS, float(fps or self.full_fps))
        except Exception:
            pass

    def release(self):
        try:
            self.cap.release()
        except Exception:
            pass


class PiCamSource:
    """Raspberry Pi camera (CSI) through picamera2 / libcamera."""
    def __init__(self, index):
        from picamera2 import Picamera2                     # ImportError -> "not installed" message
        self.cam = Picamera2(index)
        self.cam.configure(self.cam.create_video_configuration(main={"size": (1280, 720), "format": "RGB888"}))
        self.cam.start()
        self.size = (1280, 720)

    def read(self):
        try:
            return True, self.cam.capture_array("main")     # "RGB888" is delivered in B,G,R order = what OpenCV expects
        except Exception:
            return False, None

    def set_fps(self, fps):
        try:
            self.cam.set_controls({"FrameRate": float(fps or 30.0)})
        except Exception:
            pass

    def release(self):
        for fn in ("stop", "close"):
            try:
                getattr(self.cam, fn)()
            except Exception:
                pass


def _v4l_internal(idx):
    """2.98.24: /dev/video<idx> is an internal node of the Raspberry Pi (on a Pi 5 the CSI camera itself shows up as rp1-cfe
    nodes video0 … video7): no USB camera - opening it with OpenCV hangs or blocks the Pi camera."""
    try:
        name = _v4l_name(idx).lower()
    except NameError:
        return False
    return any(b in name for b in V4L_SKIP)


def _pi_cams():
    """numbers of the Raspberry Pi cameras (CSI) that libcamera sees, [] without picamera2"""
    try:
        from picamera2 import Picamera2
        return [int(i.get("Num", n)) for n, i in enumerate(Picamera2.global_camera_info()) if "usb" not in str(i.get("Id", "")).lower()]
    except Exception:
        return []


def _open_usb(idx, raw=False):
    """raw=True for thermal cameras: they have their own small resolution and formats, so nothing is forced on them."""
    if _v4l_internal(idx):
        return None
    for backend, name in ((cv2.CAP_V4L2, "V4L2"), (cv2.CAP_ANY, "default")):
        cap = cv2.VideoCapture(idx, backend)
        if cap.isOpened():
            if not raw:
                cap.set(cv2.CAP_PROP_FOURCC, cv2.VideoWriter_fourcc(*"MJPG"))
                cap.set(cv2.CAP_PROP_FRAME_WIDTH, 1280); cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 720)
            cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)
            ok, frame = cap.read()
            if ok:
                return CvSource(cap, (frame.shape[1], frame.shape[0]))
        cap.release()
    return None


def _open_url(url):
    if url.lower().startswith("rtsp"):
        os.environ.setdefault("OPENCV_FFMPEG_CAPTURE_OPTIONS", "rtsp_transport;tcp")     # TCP is far more reliable over Wi-Fi
    cap = None
    try:                                                    # connect / read time-outs (OpenCV >= 4.5.2)
        cap = cv2.VideoCapture(url, cv2.CAP_FFMPEG, [cv2.CAP_PROP_OPEN_TIMEOUT_MSEC, 8000, cv2.CAP_PROP_READ_TIMEOUT_MSEC, 8000])
    except Exception:
        cap = cv2.VideoCapture(url, cv2.CAP_FFMPEG)
    try:
        cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)
    except Exception:
        pass
    ok, frame = cap.read() if cap.isOpened() else (False, None)
    if not ok:
        cap.release()
        return None
    return CvSource(cap, (frame.shape[1], frame.shape[0]))


def source_label(spec):
    kind, _, arg = spec.partition(":")
    if kind == "usb":
        return f"USB camera {arg}"
    if kind == "pi":
        return f"Pi camera {arg}"
    if kind == "url":
        s = find_ip_source(arg)
        return s["name"] if s else "Network camera"
    if kind == "senxor":
        return "Waveshare Thermal-90 (SPI)"
    if kind == "sim":
        return "Simulator thermal camera" if arg == "thermal" else f"Simulator camera {arg}"
    if spec == "demo":
        return "Demo"
    return "Automatic"


# ----------------------------------------------------------------------------
# Demo mode (--demo): a drawn camping scene where now and then a person, a dog or a bear walks by - the whole program reacts
#   as with a real camera (alarm, recording, diary, deterrence, header). Own settings folder, nothing is changed on the
#   computer: shutting down, Wi-Fi, updates, passwords and the like are switched off. For trying it out / an online demo.
# ----------------------------------------------------------------------------
DEMO = {"on": False, "objs": [], "size": (960, 540)}
DEMO_BLOCK = ("/api/power", "/api/wifi", "/api/hotspot", "/api/password", "/api/settings/import", "/api/pause", "/api/autostart",
              "/api/backup", "/api/fleet", "/api/time", "/api/gps", "/api/bt", "/api/lock", "/api/ai_model", "/api/ext")


class DemoSource:
    def __init__(self):
        W, H = DEMO["size"]
        self.t0 = time.time(); self.fps = 15.0; self.last = 0.0
        bg = np.zeros((H, W, 3), np.float32)
        for y in range(H):                                            # sky
            k = y / (H * 0.55)
            bg[y] = (235 - 60 * k, 200 - 50 * k, 150 - 40 * k)
        hz = int(H * 0.55)
        pts = np.array([[0, hz], [120, hz - 90], [260, hz - 30], [420, hz - 140], [600, hz - 40], [760, hz - 110], [960, hz - 20], [960, hz], [0, hz]], np.int32)
        cv2.fillPoly(bg, [pts], (120, 110, 100))                       # mountains
        bg[hz:] = (60, 120, 70)                                        # meadow
        rng = np.random.default_rng(3)
        for i in range(600):
            x, y = int(rng.integers(0, W)), int(rng.integers(hz, H))
            cv2.line(bg, (x, y), (x + int(rng.integers(-2, 3)), y - int(rng.integers(3, 9))), (40, 100 + int(rng.integers(0, 50)), 50), 1)
        for x in (70, 150, 840, 900):                                  # trees
            cv2.rectangle(bg, (x - 5, hz - 10), (x + 5, hz + 40), (40, 60, 80), -1)
            cv2.fillPoly(bg, [np.array([[x - 40, hz + 5], [x, hz - 110], [x + 40, hz + 5]], np.int32)], (40, 90, 50))
        tent = np.array([[560, hz + 120], [660, hz + 10], [760, hz + 120]], np.int32)   # tent
        cv2.fillPoly(bg, [tent], (60, 140, 230)); cv2.fillPoly(bg, [np.array([[640, hz + 120], [660, hz + 50], [680, hz + 120]], np.int32)], (40, 70, 120))
        self.bg = bg; self.hz = hz

    def set_fps(self, fps):
        self.fps = float(fps) if fps else 15.0

    def _person(self, img, x, y, ph):
        s_ = ph / 100.0; leg = math.sin(ph * 0 + time.time() * 7) * 12 * s_
        c = (60, 50, 60)
        cv2.circle(img, (int(x), int(y - 88 * s_)), int(9 * s_), (170, 190, 220), -1)
        cv2.rectangle(img, (int(x - 10 * s_), int(y - 78 * s_)), (int(x + 10 * s_), int(y - 38 * s_)), (50, 60, 160), -1)
        cv2.line(img, (int(x), int(y - 40 * s_)), (int(x + leg), int(y)), c, max(2, int(7 * s_)))
        cv2.line(img, (int(x), int(y - 40 * s_)), (int(x - leg), int(y)), c, max(2, int(7 * s_)))

    def _animal(self, img, x, y, size, col):
        leg = math.sin(time.time() * 9) * 6 * size
        cv2.ellipse(img, (int(x), int(y - 22 * size)), (int(28 * size), int(13 * size)), 0, 0, 360, col, -1)
        cv2.circle(img, (int(x + 30 * size), int(y - 30 * size)), int(10 * size), col, -1)
        for dx in (-18, 16):
            cv2.line(img, (int(x + dx * size), int(y - 15 * size)), (int(x + dx * size + leg), int(y)), col, max(2, int(4 * size)))

    def read(self):
        wait = 1.0 / max(1.0, self.fps) - (time.time() - self.last)
        if wait > 0:
            time.sleep(wait)
        self.last = time.time()
        t = time.time() - self.t0; W, H = DEMO["size"]
        img = self.bg.copy()
        for i, (cx, cy) in enumerate(((120, 60), (420, 90), (760, 50))):    # clouds drift
            x = int((cx + t * (6 + i * 2)) % (W + 200)) - 100
            cv2.ellipse(img, (x, cy), (70, 22), 0, 0, 360, (245, 245, 245), -1)
        objs = []
        cyc = t % 90.0
        if 12 < cyc < 26:                                               # a person walks past the tent
            k = (cyc - 12) / 14.0; x = -40 + k * (W + 80); y = self.hz + 150
            self._person(img, x, y, 110); objs.append(("person", int(x - 16), int(y - 110), 32, 112))
        if 55 < cyc < 66:                                               # an animal crosses the meadow
            k = (cyc - 55) / 11.0; big = int(t // 90) % 3 == 2
            x = W + 60 - k * (W + 120); y = self.hz + 210
            sz = 2.2 if big else 1.1
            self._animal(img, x, y, sz, (40, 50, 70) if big else (40, 110, 200))
            objs.append(("bear" if big else "dog", int(x - 30 * sz), int(y - 40 * sz), int(72 * sz), int(42 * sz)))
        night = max(0.0, math.sin(t / 600.0 * math.pi)) * 0.0               # (kept bright: a demo should be seen)
        img = np.clip(img * (1 - night) + np.random.default_rng(int(t * 15)).normal(0, 2.0, img.shape), 0, 255).astype(np.uint8)
        DEMO["objs"] = objs
        return True, img

    def release(self):
        pass


def demo_ai(frame):
    """AI results in the demo: what the scene has drawn (in the coordinates of the processing picture)."""
    H, W = frame.shape[:2]; sx, sy = W / DEMO["size"][0], H / DEMO["size"][1]
    ids = {v: k for k, v in COCO_LABELS.items()}
    boxes, objs = [], []
    for lab, x, y, w, h in DEMO["objs"]:
        b = (int(x * sx), int(y * sy), max(2, int(w * sx)), max(2, int(h * sy)))
        if lab == "person":
            boxes.append(b + (0.91,))
        else:
            objs.append(b + (0.86, ids.get(lab, 18)))
    return boxes, objs


def open_source(spec, thermal=False):
    """Open a source (may block for seconds - always call from a background thread). thermal=True opens USB cameras unforced.
    Returns (source or None, resolved id, label, error text)."""
    label = source_label(spec)
    try:
        kind, _, arg = spec.partition(":")
        if spec == "demo" or DEMO["on"]:
            return DemoSource(), "demo", "Demo", ""
        if kind == "sim":                                  # the separate simulation program (simulator connection)
            if arg == "thermal":
                src = SimThermalSource()
                return (src, spec, label, "") if src.ok() else (None, spec, label, "simulator not reachable")
            src = _open_url(sim_base() + f"/cam/{arg}/video.mjpg" + (f"?fps={sim_cam_fps(arg)}" if sim_eco_now() else ""))
            return (src, spec, label, "") if src else (None, spec, label, "simulator not reachable - is it running?")
        if spec == "auto":
            for idx in range(10):
                src = _open_usb(idx)
                if src:
                    return src, f"usb:{idx}", f"USB camera {idx}", ""
            pis = _pi_cams()                                     # 2.98.24: no USB camera -> the Pi camera
            if pis:
                sp_ = f"pi:{pis[0]}"
                if sp_ in CFG.get("extra_cams", []):              # 2.98.31: the main camera has priority (was: both fought)
                    CFG["extra_cams"] = [x for x in CFG["extra_cams"] if x != sp_]; save_settings()
                    log_event("sys", f"{source_label(sp_)}: removed from the extra cameras - it is the main camera")
                    cams_apply(); time.sleep(2.0)
                return PiCamSource(pis[0]), sp_, source_label(sp_), ""
            return None, spec, label, "no working camera found (ls /dev/video*)"
        if kind == "usb" and not thermal and _v4l_internal(int(arg)):
            pis = [n for n in _pi_cams() if f"pi:{n}" not in {c.spec for c in CAMS}]     # 2.98.24: an internal node was chosen
            if pis:
                log_event("sys", f"/dev/video{arg} is not a camera (internal node of the Raspberry Pi) - using the Pi camera {pis[0]}")
                return PiCamSource(pis[0]), f"pi:{pis[0]}", source_label(f"pi:{pis[0]}"), ""
            return None, spec, label, f"/dev/video{arg} is no camera (internal node of the Raspberry Pi) - choose «Raspberry Pi camera»"
        if kind == "usb":
            src = (_open_usb(int(arg), raw=True) or _open_usb(int(arg))) if thermal else _open_usb(int(arg))
            return (src, spec, label, "") if src else (None, spec, label, f"no picture from /dev/video{arg}")
        if kind == "pi":
            if not thermal and spec in CFG.get("extra_cams", []) and CFG.get("source") in (spec, "auto"):
                # 2.98.26: the Pi camera can be open only once - the main camera has priority over an extra camera
                CFG["extra_cams"] = [x for x in CFG["extra_cams"] if x != spec]; save_settings()
                log_event("sys", f"{label}: removed from the extra cameras - it is the main camera now")
                cams_apply(); time.sleep(2.0)
            try:
                return PiCamSource(int(arg)), spec, label, ""
            except Exception as e:
                if any(k in str(e).lower() for k in ("busy", "acquire", "sequence did not complete", "in use")):
                    if any(c.spec == spec for c in CAMS):        # 2.98.27: an extra camera holds it - close that one first
                        cams_apply()
                    time.sleep(3.0)                              # the old picture of the camera is still being closed: once more
                    return PiCamSource(int(arg)), spec, label, ""
                raise
        if kind == "senxor":
            if not thermal:
                return None, spec, label, "the Thermal-90 can only be used as thermal camera"
            return SenxorSource(), spec, label, ""
        if kind == "url":
            s = find_ip_source(arg)
            if not s:
                return None, spec, label, "unknown network camera"
            src = _open_url(s["url"])
            return (src, spec, label, "") if src else (None, spec, label, "no picture from " + mask_url(s["url"]))
        return None, spec, label, "unknown source"
    except ImportError:
        return None, spec, label, "picamera2 not installed (sudo apt install python3-picamera2)"
    except Exception as e:
        return None, spec, label, str(e)[:160]


def _v4l_name(idx):
    try:
        with open(f"/sys/class/video4linux/video{idx}/name") as f:
            return f.read().strip()
    except OSError:
        return ""


def _is_pi():
    try:
        with open("/proc/device-tree/model") as f:
            return "raspberry" in f.read().lower()
    except OSError:
        return False


def scan_sources(active_id=""):
    """Look for every camera that is connected right now (a few seconds). The camera that is in use cannot be opened a
    second time, so it is listed without probing."""
    if not _SCAN_LOCK.acquire(blocking=False):
        return SOURCES["items"]                             # a scan is already running
    SOURCES["scanning"] = True
    try:
        items, hints = [], []
        idxs = sorted({int(re.sub(r"\D", "", p)) for p in glob.glob("/dev/video*") if re.sub(r"\D", "", p)})
        if not idxs and not sys.platform.startswith("linux"):
            idxs = [0, 1, 2, 3]
        for idx in idxs:
            name = _v4l_name(idx)
            if any(b in name.lower() for b in V4L_SKIP):
                continue
            sid = f"usb:{idx}"
            entry = {"id": sid, "kind": "usb", "name": "USB camera: " + (name or f"video{idx}"),
                     "detail": f"/dev/video{idx}", "available": True}
            if sid == active_id:
                entry["detail"] += " · in use"
            else:
                src = _open_usb(idx) or _open_usb(idx, raw=True)     # thermal cameras do not like the forced format
                if src is None:
                    continue                                # metadata node or camera that is busy / not working
                entry["detail"] += f" · {src.size[0]}x{src.size[1]}"; src.release()
            items.append(entry)
        try:
            from picamera2 import Picamera2
            for n, info in enumerate(Picamera2.global_camera_info()):
                if "usb" in str(info.get("Id", "")).lower():
                    continue                                # USB cameras were found above
                num = int(info.get("Num", n))
                items.append({"id": f"pi:{num}", "kind": "pi", "name": "Raspberry Pi camera: " + str(info.get("Model", "camera")),
                              "detail": f"CSI port {num}", "available": True})
        except ImportError:
            if _is_pi():
                hints.append("Raspberry Pi cameras need picamera2:  sudo apt install python3-picamera2  "
                             "(in a virtual environment create it with --system-site-packages)")
        except Exception as e:
            hints.append(f"Pi camera scan failed: {e}")
        SOURCES.update(items=items, hints=hints, time=time.time())
        log_event("sys", f"Camera scan: {len(items)} camera(s) found")
        return items
    finally:
        SOURCES["scanning"] = False
        _SCAN_LOCK.release()


def list_sources():
    """Everything the user can pick: automatic + scanned cameras + saved network cameras."""
    items = [{"id": "auto", "kind": "auto", "name": "Automatic (first working USB camera)", "detail": "", "available": None}]
    items += [dict(i) for i in SOURCES["items"] if i["kind"] != "url"]
    items += [{"id": "url:" + s["id"], "kind": "url", "name": s["name"], "detail": mask_url(s["url"]), "available": None}
              for s in CFG["ip_sources"]]
    ids = {i["id"] for i in items}
    act = STATE["source_id"]
    if act and act not in ids:                              # the running camera is always in the list
        items.insert(1, {"id": act, "kind": act.split(":")[0], "name": STATE["source_label"], "detail": "in use", "available": True})
    return items


def source_info():
    return {"items": list_sources(), "selected": CFG["source"], "active": STATE["source_id"], "label": STATE["source_label"],
            "status": STATE["source_status"], "res": STATE["source_res"], "scanning": SOURCES["scanning"],
            "scanned": SOURCES["time"], "hints": list(SOURCES["hints"])}


def source_select(watch, sid):
    if not isinstance(sid, str) or not SRC_RE.match(sid):
        return False, "unknown source"
    if sid.startswith("url:") and not find_ip_source(sid[4:]):
        return False, "unknown network camera"
    watch.request_source(sid)
    return True, ""


def source_add(name, url):
    """Save a network camera. Returns (ok, error, new id)."""
    url = str(url or "").strip()
    if not _url_ok(url):
        return False, "invalid URL (rtsp:// or http:// expected)", ""
    if len(CFG["ip_sources"]) >= MAX_IP_SOURCES:
        return False, "too many network cameras", ""
    sid = uuid.uuid4().hex[:8]
    name = str(name or "").strip()[:40] or "Network camera"
    CFG["ip_sources"] = CFG["ip_sources"] + [{"id": sid, "name": name, "url": url}]     # re-assign, never mutate (DEFAULTS share the list)
    save_settings(); log_event("sys", f"Network camera added: {name} ({mask_url(url)})")
    return True, "", sid


def source_remove(watch, sid):
    s = find_ip_source(sid) if isinstance(sid, str) else None
    if not s:
        return False, "unknown network camera"
    CFG["ip_sources"] = [x for x in CFG["ip_sources"] if x["id"] != sid]
    save_settings(); log_event("sys", f"Network camera removed: {s['name']}")
    if CFG["source"] == "url:" + sid:
        watch.request_source("auto")
    return True, ""


# ----------------------------------------------------------------------------
# Timelapse: every N minutes the camera drives to a chosen position, waits until the picture is calm and saves a photo.
# An alarm (person seen, recording running, tracking) always has priority: then nothing moves, and the photo is taken
# only after the alarm is over. Photos: <recordings>/timelapse/tl_YYYYmmdd_HHMMSS.jpg   videos: tlv_*.mp4 in the same folder.
# ----------------------------------------------------------------------------
TL_HOLD = {"on": False}                          # True while the camera is parked for a photo: the patrol must not move it
TL_PHOTO_RE = re.compile(r"^tl_(\d{8})_(\d{6})\.jpg$")
TL_VIDEO_RE = re.compile(r"^tlv_[0-9A-Za-z_\-]{1,40}\.mp4$")
_TL_RENDER_LOCK = threading.Lock()


def servo_hold():
    """Something other than tracking is holding the servos (hand control, timelapse position)."""
    return manual_active() or TL_HOLD["on"] or wake_hold() or bool(servo_blocked())      # 2.98.35: Not-Aus / fault (072)


def tl_dir():
    return os.path.join(os.path.abspath(CFG["record_dir"]), "timelapse")


def tl_photos(day=""):
    try:
        names = sorted(n for n in os.listdir(tl_dir()) if TL_PHOTO_RE.match(n) and (not day or n[3:11] == day))
    except OSError:
        names = []
    return names


def tl_overview():
    photos = tl_photos(); days = {}
    for n in photos:
        days[n[3:11]] = days.get(n[3:11], 0) + 1
    videos = []
    try:
        for n in sorted(os.listdir(tl_dir()), reverse=True):
            if TL_VIDEO_RE.match(n):
                st = os.stat(os.path.join(tl_dir(), n))
                videos.append({"name": n, "size": st.st_size, "time": int(st.st_mtime)})
    except OSError:
        pass
    return {"count": len(photos), "latest": photos[-1] if photos else "", "videos": videos[:30],
            "days": [{"day": d, "count": c} for d, c in sorted(days.items(), reverse=True)[:60]],
            "status": STATE["timelapse"], "render": STATE["timelapse_render"], "on": bool(CFG["timelapse_on"])}


def tl_path(name):
    """Absolute path of a timelapse photo / video (guards against path tricks), or None."""
    if not isinstance(name, str) or not (TL_PHOTO_RE.match(name) or TL_VIDEO_RE.match(name)):
        return None
    p = os.path.join(tl_dir(), name)
    return p if os.path.isfile(p) else None


def tl_cleanup():
    limit = CFG["timelapse_max_gb"] * 1024 ** 3
    try:
        files = [(n, os.path.getsize(os.path.join(tl_dir(), n))) for n in os.listdir(tl_dir()) if TL_PHOTO_RE.match(n)
                 and not _read_sidecar("timelapse/" + n).get("fav")]          # starred photos stay
    except OSError:
        return
    files.sort()
    total = sum(sz for _n, sz in files); removed = 0
    while total > limit and len(files) > 1:
        n, sz = files.pop(0)
        try:
            os.remove(os.path.join(tl_dir(), n)); total -= sz; removed += 1
        except OSError:
            break
    if removed:
        log_event("servo", f"Cleanup: {removed} old photo(s) deleted")


class Timelapse:
    """State machine, called once per camera frame with the untouched picture.
       idle -> (interval over, no alarm) -> moving (camera driven to the position, settle time) -> photo -> idle."""
    def __init__(self):
        self.state = "idle"; self.t = 0.0; self.last_shot = 0.0; self.saved = None; self.target = None; self.pending_now = False

    def request_now(self):
        self.pending_now = True

    def _back(self):
        """Drive back to where the camera was - but only if nobody (tracking, hand control) has moved it since."""
        if CFG["timelapse_return"] and self.saved and self.target and abs(CFG["pan"] - self.target[0]) < 1 and abs(CFG["tilt"] - self.target[1]) < 1:
            CFG["pan"], CFG["tilt"] = self.saved

    def _abort(self, why):
        self._back()
        TL_HOLD["on"] = False; self.state = "idle"
        log_event("servo", f"Photo postponed: {why}")

    def update(self, frame, alarm):
        now = time.time()
        if not CFG["timelapse_on"] and not self.pending_now:
            if self.state != "idle":
                self._back(); TL_HOLD["on"] = False; self.state = "idle"
            STATE["timelapse"] = "off"
            return
        busy = alarm or manual_active() or wake_hold()
        if self.state == "idle":
            due = self.pending_now or now - self.last_shot >= CFG["timelapse_interval"] * 60.0
            if not due:
                STATE["timelapse"] = f"next photo in {int(max(1, (self.last_shot + CFG['timelapse_interval'] * 60.0 - now) / 60.0 + 0.5))} min"
                return
            if busy:
                STATE["timelapse"] = "waiting: alarm has priority" if alarm else "waiting: manual control"
                return
            tp = float(max(0.0, min(100.0, CFG["timelapse_pan"]))); tt = float(max(0.0, min(100.0, CFG["timelapse_tilt"])))
            self.saved = (CFG["pan"], CFG["tilt"]); self.target = (tp, tt)
            TL_HOLD["on"] = True
            CFG["pan"], CFG["tilt"] = tp, tt
            self.state = "moving"; self.t = now
            log_event("servo", f"Driving to the photo position (pan {tp:.0f}%, tilt {tt:.0f}%)")
            STATE["timelapse"] = "moving to the photo position"
            return
        # state == "moving": the alarm may start at any time and wins immediately
        if busy:
            self._abort("alarm" if alarm else "manual control")
            STATE["timelapse"] = "waiting: alarm has priority" if alarm else "waiting: manual control"
            return
        if not servo_arrived() or now - max(self.t, SRV["arrive_t"]) < CFG["timelapse_settle"]:     # 2.98.35: ramps (072)
            STATE["timelapse"] = "moving to the photo position"
            return
        self._shoot(frame, now)

    def _shoot(self, frame, now):
        try:
            os.makedirs(tl_dir(), exist_ok=True)
            name = datetime.now().strftime("tl_%Y%m%d_%H%M%S.jpg")
            ok = cv2.imwrite(os.path.join(tl_dir(), name), frame, [cv2.IMWRITE_JPEG_QUALITY, 90])
            if ok:
                gps_tag_jpg(os.path.join(tl_dir(), name))
        except (OSError, cv2.error) as e:
            ok, name = False, ""
            log_event("servo", f"Photo could not be saved: {e}")
        self.last_shot = now; self.pending_now = False
        if ok:
            STATE["timelapse_last"] = name
            log_event("servo", f"Photo saved: {name}")
            tl_cleanup()
        self._back()
        TL_HOLD["on"] = False; self.state = "idle"
        STATE["timelapse"] = "photo saved"


def timelapse_render(day="", fps=None):
    """Make a video from the photos of one day (or all). Runs in the background; progress is in STATE['timelapse_render']."""
    day = day if isinstance(day, str) and re.fullmatch(r"\d{8}", day) else ""
    try:
        fps = max(5.0, min(60.0, float(fps if fps is not None else CFG["timelapse_fps"])))
    except (TypeError, ValueError):
        fps = 25.0
    files = tl_photos(day)[-20000:]
    if len(files) < 2:
        return False, "need at least 2 photos"
    if not _TL_RENDER_LOCK.acquire(blocking=False):
        return False, "a video is already being made"

    def work():
        enc_before = STATE["recording_enc"]
        try:
            first = cv2.imread(os.path.join(tl_dir(), files[0]))
            if first is None:
                STATE["timelapse_render"] = "error: first photo unreadable"; return
            h, w = first.shape[:2]
            name = f"tlv_{day or 'all'}_{datetime.now().strftime('%H%M%S')}.mp4"
            path = os.path.join(tl_dir(), name)
            writer, _codec = open_writer(path, fps, (w, h))
            if writer is None:
                STATE["timelapse_render"] = "error: no video encoder available"; return
            for i, n in enumerate(files):
                img = cv2.imread(os.path.join(tl_dir(), n))
                if img is None:
                    continue
                if img.shape[:2] != (h, w):
                    img = cv2.resize(img, (w, h))
                writer.write(img)
                if hasattr(writer, "q"):
                    while writer.q.qsize() > 30:                 # the ffmpeg pipe drops frames when it is full: wait for it
                        time.sleep(0.01)
                STATE["timelapse_render"] = f"making video {i + 1}/{len(files)}"
            writer.release()
            STATE["timelapse_render"] = "video ready: " + name
            log_event("servo", f"Video made: {name} ({len(files)} photos, {fps:.0f} fps)")
        except Exception as e:
            STATE["timelapse_render"] = "error: " + str(e)[:100]
        finally:
            STATE["recording_enc"] = enc_before
            _TL_RENDER_LOCK.release()
    STATE["timelapse_render"] = "making video 0/" + str(len(files))
    threading.Thread(target=work, daemon=True).start()
    return True, ""


# ----------------------------------------------------------------------------
# Thermal camera: a second camera with the same view. Its picture is coloured and laid over the normal picture
# (blend, or "hot mode": only the warmest areas are shown). Detection always works on the normal picture.
# ----------------------------------------------------------------------------
class ThermalCam:
    """Keeps the chosen thermal source open in the background and always holds its newest picture."""
    def __init__(self):
        self.src = None; self.spec = ""; self.frame = None; self.t = 0.0; self.fails = 0
        self.retry_at = 0.0; self.opening = False; self.cache = (None, None)
        self.bgsub = None; self.bg_shape = None; self.hits = deque(maxlen=5); self.det_t = 0.0; self.boxes = []; self.lo = self.hi = None
        threading.Thread(target=self.loop, daemon=True).start()

    def wanted(self):
        spec = CFG["thermal_source"] if (CFG["thermal_on"] or CFG["thermal_alarm"] or CFG["nightvision"] or CFG["nightvision_auto"]
                                         or thermal_person_active()) else ""
        if spec and spec == STATE["source_id"]:
            return ""                                          # that camera is the main camera already
        return spec

    def _close(self):
        src, self.src, self.frame = self.src, None, None
        if src is not None:
            src.release()

    def _open(self, spec):
        self.opening = True
        try:
            res = open_source(spec, thermal=True)
            if res[0] is None:
                STATE["thermal"] = "no picture: " + res[3]
                log_event("sys", f"Thermal camera '{res[2]}' not available: {res[3]}")
                self.retry_at = time.time() + 5.0
            elif self.wanted() != spec:
                res[0].release()
            else:
                self.src = res[0]; self.spec = spec; self.fails = 0
                size = getattr(res[0], "size", None)
                STATE["thermal_res"] = f"{size[0]}x{size[1]}" if size else ""
                log_event("sys", f"Thermal camera: {res[2]}" + (f" ({STATE['thermal_res']})" if size else ""))
        finally:
            self.opening = False

    def loop(self):
        while True:
            try:
                want = self.wanted()
                if self.src is not None and (want != self.spec):
                    self._close()
                if self.src is None:
                    if not want:
                        STATE["thermal"] = "off" if not (CFG["thermal_on"] or CFG["thermal_alarm"]) else ("same camera as the main picture" if CFG["thermal_source"] else "no thermal camera selected")
                        time.sleep(0.5); continue
                    if time.time() >= self.retry_at and not self.opening:
                        STATE["thermal"] = "connecting…"
                        self._open(want)
                    else:
                        time.sleep(0.3)
                    continue
                ok, fr = self.src.read()
                w_ = WATCH_REF["w"]
                if w_ is not None and w_.eco_slow:
                    time.sleep(max(0.0, 1.0 / max(1.0, float(CFG["eco_fps"])) - 0.05))     # power saving
                if ok and fr is not None:
                    self.frame = fr; self.t = time.time(); self.fails = 0
                    STATE["thermal"] = "connected"
                else:
                    self.fails += 1
                    if self.fails >= 30:
                        STATE["thermal"] = "connection lost - reconnecting"
                        self._close(); self.retry_at = time.time() + 3.0
                    time.sleep(0.05)
            except Exception as e:
                STATE["thermal"] = "error: " + str(e)[:80]
                self._close(); self.retry_at = time.time() + 5.0; time.sleep(1.0)

    main_aspect = 9 / 16.0                           # height / width of the camera picture (set by the overlay)

    @classmethod
    def crop(cls, fr):
        """The part of the (wider) thermal picture that the normal camera sees: zoom + shift (thermal camera settings)."""
        g = cls.sim_geom()
        if g is not None:                            # 2.95.88: simulator - fit by the field of view of both cameras
            return cls.fit(fr, *g)
        z = max(0.3, min(1.0, float(CFG["thermal_zoom"]) / 100.0))
        dx, dy = float(CFG["thermal_dx"]) / 100.0, float(CFG["thermal_dy"]) / 100.0
        if z >= 0.999 and not dx and not dy:
            return fr
        H, W = fr.shape[:2]
        w = W * z; h = min(float(H), w * cls.main_aspect)
        x0 = max(0.0, min(W - w, W * (0.5 + dx) - w / 2)); y0 = max(0.0, min(H - h, H * (0.5 - dy) - h / 2))
        out = fr[int(round(y0)):int(round(y0 + h)), int(round(x0)):int(round(x0 + w))]
        return out if out.size else fr

    @staticmethod
    def sim_geom():
        """In the simulation the field of view of the head camera and of the thermal camera is known (/info): which part
        of the main picture the thermal picture covers (fx, fy; < 1 = it covers less, it is put in the middle). None outside."""
        try:
            if not (CFG.get("sim_on") and str(CFG["thermal_source"]) == "sim:thermal" and str(CFG["source"]).startswith("sim:")):
                return None
            info = SIM.get("info") or {}
            th = info.get("thermal") or {}
            cam = next((c for c in info.get("cameras") or [] if str(c.get("id")) == str(CFG["source"])[4:]), None)
            if not th or not cam or not (th.get("on_head") and cam.get("on_head")):
                return None
            if CFG.get("thermal_align_own"):
                return None                              # 557: the assistant «Wärmebild ausrichten» measured it (zoom / shift)
            fx = math.tan(math.radians(float(th["fov_h"])) / 2) / math.tan(math.radians(float(cam["fov_h"])) / 2)
            fy = fx * (float(th["h"]) / float(th["w"])) / (float(cam["h"]) / float(cam["w"]))
            if th.get("fov_v") and cam.get("fov_v"):     # 557: Thermal-90 has 90° × 67° (the pixels are not square)
                fy = math.tan(math.radians(float(th["fov_v"])) / 2) / math.tan(math.radians(float(cam["fov_v"])) / 2)
            return fx, fy
        except (KeyError, ValueError, TypeError, ZeroDivisionError):
            return None

    @staticmethod
    def fit(fr, fx, fy):
        """The thermal picture as the field of the main picture: bigger field = cut out the middle, smaller = put it in the middle
        and fill the rest with the median (no picture there, so no warm edges)."""
        H, W = fr.shape[:2]
        oW, oH = max(2, int(round(W / fx))), max(2, int(round(H / fy)))
        x0, y0 = (oW - W) // 2, (oH - H) // 2
        fill = np.median(fr.reshape(H * W, -1), axis=0).astype(fr.dtype)
        out = np.empty((oH, oW) + fr.shape[2:], fr.dtype); out[...] = fill
        sx0, sy0 = max(0, -x0), max(0, -y0)
        dx0, dy0 = max(0, x0), max(0, y0)
        w, h = min(W - sx0, oW - dx0), min(H - sy0, oH - dy0)
        out[dy0:dy0 + h, dx0:dx0 + w] = fr[sy0:sy0 + h, sx0:sx0 + w]
        return out

    @staticmethod
    def to_gray8(fr):
        """Any thermal frame -> 8 bit intensity (hot = bright) with the contrast stretched to what is in the picture."""
        if fr.ndim == 3:
            if fr.shape[2] == 1:
                fr = fr[:, :, 0]
            else:
                fr = cv2.cvtColor(fr, cv2.COLOR_BGR2GRAY) if fr.dtype == np.uint8 else fr.mean(axis=2)
        f = fr.astype(np.float32)
        small = f[::max(1, f.shape[0] // 60), ::max(1, f.shape[1] // 80)]
        lo, hi = np.percentile(small, (1, 99))
        if hi - lo < 1e-3:
            return np.zeros(f.shape, np.uint8)
        return np.clip((f - lo) * (255.0 / (hi - lo)), 0, 255).astype(np.uint8)

    @staticmethod
    def is_plain_gray(fr):
        if fr.ndim == 2 or fr.shape[2] == 1:
            return True
        if fr.dtype != np.uint8:
            return True
        s = fr[::8, ::8].astype(np.int16)
        return int(np.abs(s[:, :, 0] - s[:, :, 1]).max()) < 6 and int(np.abs(s[:, :, 1] - s[:, :, 2]).max()) < 6

    def color(self, fr):
        """-> (colour picture, intensity). A camera that already delivers false colours keeps its own colours."""
        gray = self.to_gray8(fr)
        cmap = THERMAL_MAPS.get(CFG["thermal_map"], cv2.COLORMAP_INFERNO)
        if self.is_plain_gray(fr):
            col = cv2.applyColorMap(gray, cmap) if cmap is not None else cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR)
        else:
            col = fr if fr.dtype == np.uint8 and fr.ndim == 3 and fr.shape[2] == 3 else cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR)
        return col, gray

    def detect(self):
        """Warm bodies in the thermal picture: clearly warmer than the scene (thermal_delta), moving (unless switched off,
        so sun-warmed stones or an engine do not alarm), big enough, inside the zones, seen in 3 of the last 5 pictures."""
        fr, t = self.frame, self.t
        if fr is None or time.time() - t > 3.0:
            self.hits.clear(); self.boxes = []; return []
        if t == self.det_t:
            return self.boxes
        self.det_t = t
        f = self.crop(fr).astype(np.float32)
        if f.ndim == 3:
            f = f.mean(axis=2)
        if f.shape[1] > 160:
            f = cv2.resize(f, (160, max(1, int(f.shape[0] * 160 / f.shape[1]))), interpolation=cv2.INTER_AREA)
        lo, hi = np.percentile(f, (2, 99.5))
        if self.lo is None:
            self.lo, self.hi = float(lo), float(hi)
        else:                                            # slow: an animal walking in must not re-scale the whole picture
            self.lo += 0.05 * (lo - self.lo); self.hi += 0.05 * (max(hi, self.lo + 1e-3) - self.hi)
        g = np.clip((f - self.lo) * 255.0 / max(1e-3, self.hi - self.lo), 0, 255).astype(np.uint8)
        med = float(np.median(g))
        # 2.98.x (Prüfstand: clear nights 0 thermal persons): the clear night sky is very cold (-20 °C and colder) and sets
        # the bottom of the scale - the ground then sits at ~210 of 255 and «median + 30 %» was above 255: nothing could
        # ever be warm. The step is now measured on the warm side only (twice the room above the median, at most the old
        # full scale), with a camera in °C at least 10 °C, else at least a quarter of the scale.
        span = min(255.0, 2.0 * (255.0 - med))
        if fr.dtype != np.uint8:
            span = max(span, min(255.0, 10.0 * 255.0 / max(1e-3, self.hi - self.lo)))
        else:
            span = max(span, 64.0)
        warm = ((g.astype(np.float32) > med + CFG["thermal_delta"] / 100.0 * span).astype(np.uint8)) * 255
        if CFG["thermal_need_motion"]:
            if self.bgsub is None or self.bg_shape != g.shape:
                self.bgsub = cv2.createBackgroundSubtractorMOG2(history=300, varThreshold=12, detectShadows=False); self.bg_shape = g.shape
            mov = cv2.dilate(self.bgsub.apply(g), np.ones((3, 3), np.uint8), iterations=2)
            warm = cv2.bitwise_and(warm, mov)
        warm = cv2.morphologyEx(warm, cv2.MORPH_OPEN, np.ones((2, 2), np.uint8))
        cnts, _ = cv2.findContours(warm, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        H, W = g.shape
        min_a = max(2.0, CFG["thermal_min_area"] / 100.0 * W * H)
        boxes = []
        for c in cnts:
            if cv2.contourArea(c) < min_a:
                continue
            x, y, w, h = cv2.boundingRect(c)
            nb = (x / W, y / H, w / W, h / H)
            if zone_allows(nb[0] + nb[2] / 2.0, nb[1] + nb[3] * 0.85):
                boxes.append(nb)
        self.hits.append(bool(boxes))
        self.boxes = boxes if sum(self.hits) >= 3 else []
        return self.boxes

    def overlay(self, frame):
        fr = self.frame
        if fr is None or time.time() - self.t > 3.0:
            return frame
        try:
            H, W = frame.shape[:2]
            ThermalCam.main_aspect = H / float(W)
            col, gray = self.color(self.crop(fr))
            col = cv2.resize(col, (W, H), interpolation=cv2.INTER_CUBIC)
            a = float(max(0.05, min(1.0, CFG["thermal_alpha"])))
            if CFG["thermal_hot"]:
                gray = cv2.resize(gray, (W, H), interpolation=cv2.INTER_LINEAR)
                thr = float(np.percentile(gray[::4, ::4], CFG["thermal_hot_pct"]))
                m = cv2.GaussianBlur((gray > thr).astype(np.float32), (0, 0), max(2.0, W / 200.0))[:, :, None] * a
                return (frame * (1.0 - m) + col * m).astype(np.uint8)
            return cv2.addWeighted(frame, 1.0 - a, col, a, 0)
        except cv2.error:
            return frame


THERMAL = None            # created together with the camera loop


_BELLY = "25:fe87bfc14c106eb2ebb75df5dba6aaec172507faaafe006700ce29179083c51cf8728e897041b1972f895c703f641812f524ff98ff0049463f8eab9055117ba9afa5d29fbee9fec505c09efe89178"     # a little pattern for the marmot (easter egg)


def belly_matrix():
    n, hx = _BELLY.split(":"); n = int(n)
    bits = bin(int(hx, 16))[2:].zfill(len(hx) * 4)
    return [[bits[r * n + c] == "1" for c in range(n)] for r in range(n)]


def _rdp(P, eps):
    """Ramer-Douglas-Peucker: the corners of a drawn line."""
    if len(P) < 3:
        return list(P)
    (ax, ay), (bx, by) = P[0], P[-1]; L = math.hypot(bx - ax, by - ay) or 1e-9
    dmax, idx = -1.0, 0
    for i in range(1, len(P) - 1):
        d = abs((bx - ax) * (ay - P[i][1]) - (ax - P[i][0]) * (by - ay)) / L if L > 1e-6 else math.hypot(P[i][0] - ax, P[i][1] - ay)
        if d > dmax:
            dmax, idx = d, i
    if dmax <= eps:
        return [P[0], P[-1]]
    return _rdp(P[:idx + 1], eps)[:-1] + _rdp(P[idx:], eps)


def cw_triangle(P):
    """True when the points (screen coordinates, y down) are a closed triangle drawn clockwise."""
    if len(P) < 8:
        return False
    xs = [p[0] for p in P]; ys = [p[1] for p in P]
    w, h = max(xs) - min(xs), max(ys) - min(ys); size = max(w, h)
    if size < 40 or min(w, h) < size * 0.3 or math.hypot(P[0][0] - P[-1][0], P[0][1] - P[-1][1]) > size * 0.35:
        return False
    area = sum(P[i][0] * P[(i + 1) % len(P)][1] - P[(i + 1) % len(P)][0] * P[i][1] for i in range(len(P))) / 2
    if area <= 0 or not (0.25 <= area / (w * h) <= 0.68):          # y down: positive = clockwise; a triangle fills about half
        return False
    V = _rdp(list(P) + [P[0]], size * 0.12)[:-1]
    changed = True
    while changed and len(V) > 3:                                      # drop corners that are nearly straight
        changed = False
        for i in range(len(V)):
            a, b, c = V[i - 1], V[i], V[(i + 1) % len(V)]
            u, v = (a[0] - b[0], a[1] - b[1]), (c[0] - b[0], c[1] - b[1])
            nu, nv = math.hypot(*u), math.hypot(*v)
            if nu < size * 0.12 or nv < size * 0.12 or (u[0] * v[0] + u[1] * v[1]) / (nu * nv) < -0.88:
                del V[i]; changed = True; break
    return len(V) == 3


def ccw_heart(P, min_size=90):
    """2.95.61: True when the points (screen coordinates, y down) are a big closed heart drawn counter-clockwise:
    two round lobes at the top, a dip in the middle between them, a point at the bottom."""
    if len(P) < 12:
        return False
    xs = [p[0] for p in P]; ys = [p[1] for p in P]
    left, right, top, bot = min(xs), max(xs), min(ys), max(ys)
    w, h = right - left, bot - top; size = max(w, h)
    if size < min_size or not (0.6 <= w / max(h, 1e-6) <= 1.6) or math.hypot(P[0][0] - P[-1][0], P[0][1] - P[-1][1]) > size * 0.3:
        return False
    area = sum(P[i][0] * P[(i + 1) % len(P)][1] - P[(i + 1) % len(P)][0] * P[i][1] for i in range(len(P))) / 2
    if area >= 0 or not (0.4 <= -area / (w * h) <= 0.88):          # y down: negative = counter-clockwise on the screen
        return False
    cx = (left + right) / 2
    D = []                                                           # more points on long, fast strokes
    for i in range(len(P)):
        a_, b_ = P[i], P[(i + 1) % len(P)]; k_ = max(1, int(math.hypot(b_[0] - a_[0], b_[1] - a_[1]) / (size / 80)))
        D += [(a_[0] + (b_[0] - a_[0]) * j / k_, a_[1] + (b_[1] - a_[1]) * j / k_) for j in range(k_)]
    P = D
    tip = max(P, key=lambda p: p[1])
    if abs(tip[0] - cx) > 0.22 * w:                                  # the point at the bottom, in the middle
        return False
    low = [p[0] for p in P if p[1] > top + 0.8 * h]
    if low and max(low) - min(low) > 0.55 * w:                       # it gets narrow towards the point
        return False
    mid = [p[1] for p in P if abs(p[0] - cx) < 0.07 * w and p[1] < top + 0.6 * h]
    if not mid or min(mid) < top + 0.07 * h:                         # the dip between the lobes
        return False
    lt = [p[1] for p in P if p[0] < cx - 0.15 * w]; rt = [p[1] for p in P if p[0] > cx + 0.15 * w]
    return bool(lt and rt and min(lt) <= top + 0.15 * h and min(rt) <= top + 0.15 * h)     # two lobes up high


def heart_points(cx, cy, s, n=48, scale_x=1.0):
    """the outline of a heart around (cx, cy), s = half the width (screen: y down)"""
    out = []
    for i in range(n):
        t = 2 * math.pi * i / n
        x = 16 * math.sin(t) ** 3; y = -(13 * math.cos(t) - 5 * math.cos(2 * t) - 2 * math.cos(3 * t) - math.cos(4 * t))
        out.append((cx + x / 16 * s * scale_x, cy + (y + 2.5) / 16 * s))
    return out


class NightVision:
    """Night vision look: the picture brightened and tinted green like an image intensifier (a little grain, dark
    corners); a thermal camera adds glowing outlines of warm bodies and - with the Thermal-90 - their temperature."""
    def __init__(self):
        self.vig = None; self.vig_size = None; self.clahe = cv2.createCLAHE(clipLimit=3.0, tileGridSize=(8, 8))
        self.rng = np.random.default_rng(3)

    def active(self):
        return bool(CFG["nightvision"] or (CFG["nightvision_auto"] and LIGHTS.get("dark")))

    def apply(self, frame):
        try:
            H, W = frame.shape[:2]
            g = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            g = self.clahe.apply(g)
            m = float(g.mean())
            if m < 110:                                        # lift dark scenes (gamma)
                gm = max(0.35, math.log(120.0 / 255.0) / math.log(max(m, 2.0) / 255.0))
                g = (255.0 * (g / 255.0) ** gm).astype(np.uint8)
            if self.vig_size != (W, H):
                yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
                r = np.sqrt(((xx - W / 2) / (W / 2)) ** 2 + ((yy - H / 2) / (H / 2)) ** 2)
                self.vig = np.clip(1.15 - 0.55 * r ** 2, 0.25, 1.0).astype(np.float32); self.vig_size = (W, H)
            noise = self.rng.normal(0, 9, (H // 2 + 1, W // 2 + 1)).astype(np.float32)
            noise = cv2.resize(noise, (W, H), interpolation=cv2.INTER_NEAREST)
            v = np.clip((g.astype(np.float32) + noise) * self.vig, 0, 255)
            out = np.dstack([v * 0.22, v, v * 0.38]).astype(np.uint8)          # B, G, R: phosphor green
            th = THERMAL
            if th is not None and th.frame is not None and time.time() - th.t < 3.0:
                self._thermal(out, th, W, H)
            cv2.putText(out, "NV", (W - 42, 24), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (120, 255, 150), 2, cv2.LINE_AA)
            return out
        except (cv2.error, ValueError):
            return frame

    def _thermal(self, out, th, W, H):
        fr = ThermalCam.crop(th.frame)
        celsius = fr.ndim == 2 and fr.dtype.kind == "f"
        f = fr.astype(np.float32) if celsius else ThermalCam.to_gray8(fr).astype(np.float32)
        f = cv2.resize(f, (W, H), interpolation=cv2.INTER_LINEAR)
        thr = float(np.percentile(f[::4, ::4], 96))
        if celsius:
            thr = max(thr, float(np.median(f[::4, ::4])) + 4.0)          # at least 4 °C warmer than the surroundings
        mask = (f > thr).astype(np.uint8) * 255
        mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, np.ones((5, 5), np.uint8))
        cnts, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        cnts = sorted((c for c in cnts if cv2.contourArea(c) > W * H * 0.002), key=cv2.contourArea, reverse=True)[:4]
        glow = np.zeros_like(out)
        cv2.drawContours(glow, cnts, -1, (170, 255, 200), 3)
        glow = cv2.GaussianBlur(glow, (0, 0), 3)
        np.maximum(out, glow, out=out)
        cv2.drawContours(out, cnts, -1, (210, 255, 225), 1, cv2.LINE_AA)
        if celsius:
            for c in cnts:
                x, y, w, h = cv2.boundingRect(c)
                t = float(f[y:y + h, x:x + w].max())
                num, F, col = f"{t:.0f}", cv2.FONT_HERSHEY_SIMPLEX, (190, 255, 205)
                (nw, th_), _ = cv2.getTextSize(num, F, 0.55, 2); (cw, _h), _ = cv2.getTextSize("C", F, 0.55, 2)
                tw = nw + 7 + cw
                tx, ty = int(min(max(2, x + w / 2 - tw / 2), W - tw - 4)), int(max(th_ + 4, y - 6))
                cv2.rectangle(out, (tx - 4, ty - th_ - 4), (tx + tw + 4, ty + 4), (20, 60, 25), -1)
                cv2.putText(out, num, (tx, ty), F, 0.55, col, 2, cv2.LINE_AA)
                cv2.circle(out, (tx + nw + 3, ty - th_ + 2), 2, col, 1, cv2.LINE_AA)          # degree sign
                cv2.putText(out, "C", (tx + nw + 7, ty), F, 0.55, col, 2, cv2.LINE_AA)


NIGHTVISION = NightVision()


# ----------------------------------------------------------------------------
# 2.98.13 (Wunsch Daniel): at night the normal camera often sees nobody (too dark, too far for the IR light). The thermal
# camera still sees the warm body. A warm body (ThermalCam.detect: warmer than the scene by thermal_delta, moving unless
# thermal_need_motion is off, in the zones, seen in 3 of 5 pictures) counts as a PERSON when it also
#   - stands upright (taller than wide, as a person),
#   - has the size of a person at its distance (1.7 m tall, 0.2 … 1.3 m wide - from the field of view of the camera),
#   - is warmer than the background but not hot like a fire or an engine (only with a camera that gives °C).
# It then goes into the same person / alarm logic (push, recording, siren, zones of the recording) as «Person (Wärmebild)».
# Option thermal_person (default on) - only at night (or by day too: thermal_person_day). Needs a thermal camera.
# 2.98.22 (Wunsch Daniel: «das Wärmebild soll mitlaufen»): by day too is now the default, so the thermal camera always
# runs along as soon as one is chosen - also with the overlay and the warm alarm off. Older settings are switched once
# (thermal_migrate, called by 040); who switches «… by day too» off again keeps it off.
# ----------------------------------------------------------------------------
for _k, _v in {"thermal_person": True, "thermal_person_day": True, "thermal_mig22": False}.items():
    CFG.setdefault(_k, _v)
    DEFAULTS.setdefault(_k, _v)
TPERS = {"t": 0.0, "seen": 0.0, "n": 0}


def thermal_migrate(cfg_in):
    """once per settings file: the thermal camera runs along by day too (2.98.22)"""
    if not isinstance(cfg_in, dict) or cfg_in.get("thermal_mig22"):
        return []
    CFG["thermal_mig22"] = True
    if cfg_in.get("thermal_person_day") is False:
        CFG["thermal_person_day"] = True
        return ["thermal camera runs along by day too"]
    return []


def thermal_person_active():
    """thermal persons are looked for now: the option is on, a thermal camera is chosen, and it is night (or by day too)"""
    if not CFG.get("thermal_person") or not CFG.get("thermal_source") or not CFG.get("detection_on"):
        return False
    if CFG.get("thermal_person_day"):
        return True
    try:
        return bool(is_dark() or STATE.get("lowlight"))
    except Exception:
        return bool(STATE.get("lowlight"))


def _thermal_temps(box):
    """(warm body, background) in °C when the thermal camera gives temperatures (float picture), else None"""
    th = THERMAL
    fr = th.frame if th is not None else None
    if fr is None or fr.dtype == np.uint8:
        return None
    try:
        f = th.crop(fr).astype(np.float32)
        if f.ndim == 3:
            f = f.mean(axis=2)
        H, W = f.shape[:2]
        x, y, w, h = box
        x0, y0 = max(0, int(x * W)), max(0, int(y * H))
        x1, y1 = min(W, int(math.ceil((x + w) * W))), min(H, int(math.ceil((y + h) * H)))
        reg = f[y0:y1, x0:x1]
        if reg.size < 2:
            return None
        return float(np.percentile(reg, 80)), float(np.median(f))
    except (ValueError, TypeError, cv2.error):
        return None


def thermal_person_check(box):
    """-> distance in m when the warm body (x, y, w, h 0..1 of the main picture) looks like a person, else None"""
    x, y, w, h = box
    if w <= 0 or h <= 0:
        return None
    asp = (h / w) * float(ThermalCam.main_aspect)             # height / width in real pixels of the main picture
    if not (1.3 <= asp <= 5.5):
        return None                                           # lying, round or a long thin thing: no standing person
    hf, vf = cam_fov()
    vf = erk_vfov()
    d = PERSON_H_M / (2.0 * h * math.tan(math.radians(vf) / 2.0))
    if not (1.0 <= d <= 80.0):
        return None
    width_m = w * 2.0 * d * math.tan(math.radians(hf) / 2.0)
    if not (0.2 <= width_m <= 1.3):
        return None                                           # too broad for a person at that distance (cow, car bonnet)
    tt = _thermal_temps(box)
    if tt is not None:
        body, bg = tt
        if body - bg < 3.0 or body > 45.0:
            return None                                       # hardly warmer than the ground / hot like a fire or an engine
    return d


def thermal_person_feed(warm_boxes, person_boxes, present, frame, pw, ph, W, H, t0):
    """called by the camera loop (410) when the normal camera found nobody: the warm bodies that are persons become person
    boxes (in the working picture), drawn as «PERSON (THERMAL)». Returns the warm bodies that stay «warm»."""
    rest = []
    found = []
    ThermalCam.main_aspect = H / float(W)                      # (the overlay sets it too - only when the thermal picture is shown)
    for b in warm_boxes:
        d = thermal_person_check(b)
        if d is None:
            rest.append(b); continue
        found.append((b, d))
    if not found:
        return rest
    for (bx, by, bw, bh), d in found:
        pb = (int(bx * pw), int(by * ph), max(1, int(bw * pw)), max(1, int(bh * ph)))
        person_boxes.append(pb)
        p1 = (int(bx * W), int(by * H)); p2 = (int((bx + bw) * W), int((by + bh) * H))
        cv2.rectangle(frame, p1, p2, (60, 0, 255), 3)
        cv2.putText(frame, f"PERSON (THERMAL) ~{dist_round(d)}m", (p1[0], max(18, p1[1] - 6)), cv2.FONT_HERSHEY_SIMPLEX, 0.55, (60, 0, 255), 2)
        try:
            walktest_hit(bx + bw / 2.0, by + bh, d, "thermal", "th", t0)
        except Exception:
            pass
    present.add("person")
    best = min(found, key=lambda x: x[1])
    erk_note_thermal(best[1], t0)
    if t0 - TPERS["seen"] > 10.0:                             # a new appearance (not every picture)
        STATE["detections_total"] = STATE.get("detections_total", 0) + 1
        log_event("person", f"Person in the thermal picture, about {dist_round(best[1])} m (the normal camera sees nobody)")
    TPERS["seen"] = t0; TPERS["n"] = len(found)
    return rest
# ----------------------------------------------------------------------------
# Audio: microphone (noise alarm, live listening in the browser, sound in the recordings) + loudspeaker of the Pi (siren)
#   One "arecord" process reads the microphone (16 kHz mono) and feeds everything else: a USB microphone can only be
#   opened by one program at a time. The loudspeaker plays generated sounds (siren, two-tone, beeps, horn) or own sound
#   files from <settings folder>/sounds via "aplay". While the Pi plays a sound, the noise alarm does not listen.
# ----------------------------------------------------------------------------
AUDIO_RATE = 16000                     # microphone: 16 kHz mono 16 bit = 32 kB/s (fine over a phone hotspot)
AUDIO_CHUNK = AUDIO_RATE // 10         # 0.1 s
OUT_RATE = 22050                       # loudspeaker
AUDIO_DEV_RE = re.compile(r"^(default|(plug)?hw:CARD=[A-Za-z0-9_\-]{1,40},DEV=\d{1,2})$")
AUDIO_DEVS = {"in": [], "out": [], "time": 0.0, "err": ""}
SOUND_KINDS = ("siren", "two-tone", "beeps", "horn", "whistle", "bangs")
SIREN_ON = ("off", "person", "alarm", "all")
SOUND_EXT = (".wav", ".mp3", ".ogg", ".flac", ".m4a")
SOUND_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9 _.\-()]{0,80}$")
_ALSA_RE = re.compile(r"^card (\d+): (\S+) \[(.*?)\], device (\d+): (.*?) \[(.*?)\]")
AUDIO = None                           # AudioMonitor, created together with the camera loop


def sounds_dir():
    return os.path.join(DATA_DIR, "sounds")


def own_sounds():
    try:
        return sorted(f for f in os.listdir(sounds_dir()) if f.lower().endswith(SOUND_EXT) and SOUND_NAME_RE.match(f))[:40]
    except OSError:
        return []


def _alsa_scan(cmd):
    """Sound cards from "arecord -l" / "aplay -l". The id uses the card NAME (plughw:CARD=Device,DEV=0): the number of a USB
    card can change after a reboot, the name stays. plughw converts the sample rate (many USB microphones only do 48 kHz)."""
    if not shutil.which(cmd):
        return [], f"{cmd} is missing (sudo apt install alsa-utils)"
    rc, out, err = _run([cmd, "-l"], timeout=10)
    items = []
    for line in (out or "").splitlines():
        m = _ALSA_RE.match(line.strip())
        if not m:
            continue
        _n, cid, cname, dev, _dn, dname = m.groups()
        dev_id = f"plughw:CARD={cid},DEV={dev}"
        if not AUDIO_DEV_RE.match(dev_id) or any(i["id"] == dev_id for i in items):
            continue
        label = cname if (not dname or dname == cname or dname.startswith("USB Audio")) else f"{cname} - {dname}"
        items.append({"id": dev_id, "name": label})
    return items, ("" if rc == 0 or items else (err or "")[:200])


def audio_scan():
    """Look for microphones and loudspeakers (also called from the page: "Search devices")."""
    ins, e1 = _alsa_scan("arecord")
    outs, e2 = _alsa_scan("aplay")
    AUDIO_DEVS.update({"in": ins, "out": outs, "time": time.time(), "err": e1 or e2})
    return ins, outs


def audio_choice_pairs(kind):
    """[(value, label)] for the microphone / loudspeaker selection. A saved device that is not plugged in stays selectable."""
    pairs = [("", "– " + tr("none") + " –"), ("default", tr("System default"))]
    pairs += [(d["id"], d["name"]) for d in AUDIO_DEVS[kind]]
    if kind == "out":
        pairs += [("bt:" + d["mac"], "Bluetooth: " + d["name"]) for d in BT["devices"] if d["paired"] and d["audio"]]
    cur = CFG["audio_in" if kind == "in" else "audio_out"]
    if cur and cur not in [p[0] for p in pairs]:
        pairs.append((cur, ("Bluetooth " + cur[3:]) if cur.startswith("bt:") else cur.replace("plughw:CARD=", "").split(",")[0] + " (" + tr("not connected") + ")"))
    return pairs


def sound_choice_pairs():
    names = {"siren": "Siren (rising and falling)", "two-tone": "Two-tone horn", "beeps": "Fast beeps", "horn": "Horn",
             "whistle": "High whistle (animals)", "bangs": "Bangs / claps (animals)"}
    return [(k, tr(names[k])) for k in SOUND_KINDS] + [("file:" + f, "♪ " + f) for f in own_sounds()]


def _db(rms):
    return round(20.0 * math.log10(max(rms, 1.0) / 32768.0), 1)


