    STV["alarm"] = {"t": time.time(), "kind": kind, "label": str(label), "conf": conf, "dist": dist, "crop": crop, "n": int(n),
                    "clock": sim_now().strftime("%H:%M")}
    log_event("sys", f"SmallTV: alarm picture ({kind} {label})")
    STV["wake"] = True


