        w = self._msg_top = tk.Toplevel(self.root); w.title("MoveEye – " + tr("Message list")); w.configure(bg=C["bg"]); w.geometry("620x520")
        top = tk.Frame(w, bg=C["bg"]); top.pack(fill="x", padx=12, pady=(10, 4))
