def text_choice_pairs(key):                                 # + 7: pictures in push messages
    if TEXT_SPECS.get(key, (None, None))[1] == "push_pics":
        return [(k, tr(l)) for k, l in SX_PUSH_PICS]
    return _text_choice_pairs_before_sx(key)


