def _help_sicher(doc, lang):
    if '<section id="sicher"' in doc:
        return doc
    i = doc.find('<section id="tips"')
    if i < 0:
        i = doc.find('<section id="privacy"')
    return doc[:i] + _HELP_SICHER[lang] + doc[i:] if i >= 0 else doc


