def _help_blinki(doc, lang):
    i = doc.find('<section id="guide2"')
    j = doc.find("</ul>", i) if i >= 0 else -1
    if j < 0 or "<b>Blinki</b>" in doc[i:j]:
        return doc
    return doc[:j] + _HELP_BLINKI[lang] + doc[j:]


_hp_enb = HELP_PAGE.find('<div lang="en">')
